INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (20006, '追踪玩家是否解除了战争模式。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39977, '你在这里引起了不小的骚动。虽然我睡得很沉，但你那些烟花太多了，我终于注意到它了。诚然，我醒来时看到的是一个令人愉快的演出。看到大家齐声庆祝，给这个古老之灵带来了令人欣慰的温暖。也许你和我的好朋友海龟之灵谈过吗？他自己肯定很想看到这样的奇观。$B$B事实上，我也是。这种愉快的合作是罕见的，需要珍惜！如果你能多带些那些非凡的烟花和一些凉茶来放松，我会与你分享我的一些好运祝福！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39978, '伟大的旅行者！今年是充满冒险的一年，充满兴奋、惊喜、挑战和新朋友。你面对了许多困难，勇敢面对更多危险，并从中取得了胜利——更强大、更聪明！让我们庆祝一下，用盛大的烟花来表达我们的感激之情！$B$B然而，任何普通的烟花都嫌不足。为了适当地纪念您和您的同胞的成就，我们需要一些真正独特的东西！在艾泽拉斯危险的地下城深处，最可怕的敌人和怪物在他们的财产中保留了奢侈的烟花。战胜他们，在我面前点燃三种不同的烟花来迎接我的祝福！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (39979, '伟大的旅行者！今年是充满冒险的一年，充满兴奋、惊喜、挑战和新朋友。你面对了许多困难，勇敢面对更多危险，并从中取得了胜利——更强大、更聪明！让我们庆祝一下，用盛大的烟花来表达我们的感激之情！$B$B然而，任何普通的烟花都嫌不足。为了适当地纪念您和您的同胞的成就，我们需要一些真正独特的东西！在艾泽拉斯危险的地下城深处，最可怕的敌人和怪物在他们的财产中保留了奢侈的烟花。战胜他们，在我面前点燃三种不同的烟花来迎接我的祝福！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41274, '你能感觉到吗，$C？弥漫在空气中的爱情与甜言蜜语的芬芳？那些热切的情侣们彼此分享着快乐的魅力？没有什么比目睹爱的奇迹传遍艾泽拉斯更让我心动的了！$B$B你的眼睛出卖了你的心，我可以像一本打开的书一样轻易读懂你。我能看出你渴望了解更多，甚至想亲自体验这种感情。爱有多种形式，并不总是想象那样一目了然。即使是我，爱情的天使，也经常对那些被我的祝福之箭选中的人感到惊讶！爱情真是难懂！没有比过去被我的箭射中的人更能证明这一点的了。给我带来一个他们独特的爱和钦佩的象征，在任何一个主城把这些纪念品交给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41275, '$N！你有空吗？你在珠宝制作方面的技能非常出色，我的学生很少能通过我自己的教学达到这样的技艺水平。当然不需要师傅就能看出来——你天生就是这个手艺的专家。$B$B虽然你的表现已经远远超出了我的期望，但我无法教给你更多东西了。这并不意味着你的旅程结束了，而是还有更有能力的人可以帮助你。其中一个可能正好是我的朋友。或者你可能已经遇到过他了，他也许有点忧虑和不满，但只要提供一些帮助，他就会分享他的知识。$B$B如果你想专门学习这个手艺，成为一名珠宝制作大师，可以去秘法区找塔瓦斯德·基瑟尔。他将会给你未来在这行中的道路指明方向。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41276, '$N，能再次见到你真是太好了。我注意到了——你肯定也注意到了——你的技艺进步神速！真的，我已经很久没有见过如此高超的技艺了。很遗憾，这意味着我已经没有什么能教你的了。不过，你渴望学习更多东西是显而易见的；幸好我最后一次还能帮到你。$B$B如果你想加强对珠宝加工领域的理解，可以去卡加斯找我的好朋友加卡尔。危险的荒地不适合像我这样的不死者，但像他这样坚强的巨魔可以轻松承受如此恶劣的环境。路上小心，祝你一路平安，$B$B。<古尔迈尔鞠了一躬>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41277, '$N！你有空吗？你的珠宝制作技术非常出色，很少有我的学生仅凭我的教导就能达到如此高水平。即便不是专家也能看出——你天生就是这块料。$B$B虽然你的技艺突飞猛进，但很遗憾我已经没有什么可以教你的了。不过，不要担心，因为我的师父齐格伦可能会在我达不到的领域提供帮助。$B$B如果您希望专攻你的技术并成为宝石切割大师，一种在物品上镶嵌宝石来提高能力的技艺，请寻找齐格伦。作为比现今任何文明都古老的古代文明的一员，他选择了隐居在荒芜之地。在古代遗迹科萨恩废墟附近寻找他。他不善言谈，但如果你向他展示这块水晶，我向你保证—他会听取你的意见。要小心，前往那个阴沉的地方是一次危险的旅程！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41278, '$N，能再次见到你真是太好了。我注意到了——你肯定也注意到了——你的技艺进步神速！真的，我已经很久没有见过如此高超的技艺了。很遗憾，这意味着我已经没有什么能教你的了。不过，你渴望学习更多东西是显而易见的；幸好我最后一次还能帮到你。$B$B如果你想加强对宝石学的了解，有一个神秘的人可以帮助你实现你的理想。他比我所知道的任何东西都要古老，是一个古代秩序的成员，掌握了艾泽拉斯矿物的知识。因此，他很重视隐私；这意味着他很可能不会和你说话。拿去，把这块水晶带走。这是我受他教导的证明，它会让他知道你是值得信赖的。请小心您的旅途，祝您旅途平安。$B$B。<古尔迈尔鞠了一躬>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41279, '<齐格伦张开嘴，但嘴里没有说任何话，只有粗糙石头的摩擦声。你困惑地看着他，不知道他想表达什么。看到你的困惑，这个土灵摇了摇头，示意你跪下。你犹豫地跪下后，他把宽大的石手放在你的额头上。$B$B突然间，排山倒海的画面涌入你的脑海，其中一个景象在你的记忆中留下了深刻的印象。荒芜之地的赤褐色巨人，还有一颗宝石。你镇定下来，转向齐格伦，他只是深沉地看着你。他指着东边，犀利的眼神，催促你快去寻找。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41280, '<恢复视觉后，你看到齐格伦正在用双手摆弄着什么。仔细观察发现，他毫不费力地将一颗红宝石切割成你刚刚看到的样式并放在石桌上。然后又拿起一颗黄水晶重复了同样的过程，接着又切割了一颗灰烬石。$B$B工匠严肃地看着你，并指着他的工艺品，然后向你伸出他的手。你思考了一会儿，明白了齐格伦的手势：他希望你用刚刚学到的三种切割方法重复五遍。$B$B应该不会太难吧？>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41281, '<这次没有任何手势，你便跪下来接受新导师的下一个教导。$B$B洁白的大厅、无尽的瀑布，温暖的感觉萦绕在你的心头。在卡利姆多大陆遥远的西方，凄凉之地的群山中隐藏着你脑海中幻象的线索。曾经神圣的玛拉顿洞穴是下一个目的地，其中有一个完美的大理石巨人，我需要他身上的大理石块。$B$B你站起来，向齐格伦点了点头，他只是把拳头放在胸前，然后继续工作。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41282, '<齐格伦面前的桌子上摆放着三件东西。分别是博尔哈斯特身上取下的源血宝钻、兰斯利德身上的大理石块和一块精致的布片，这块布片似乎不受时间流逝的影响。仔细观察了它们之后，你转向齐格伦—他仍然面无表情地看着你，什么也没有说。$B$B这似乎是你的最终考验。用你所学到的宝石切割技艺将这块火热的石头切割成完美的形状。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41283, '好吧，听着。老实说这不是做慈善，我显然不会把独家技艺传授给你，绝对不会！但如果你帮助我……补充货物。也许，可以考虑考虑。怎么样？这个主意相当完美！$B$B请尽快给我带来以下东西，我不想等太久。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41284, '信不信由你，住在山下并不能保证你的仓库里有源源不断的宝石。如果一些传言成为你在这里进行良好和诚实交易的阻碍，那显然对我们都没有好处。如果我还在诺莫瑞根，这一切都会更容易，相信我。不过，宝石对珠宝加工来说很重要——没有宝石，就没有珠宝，就没有贸易，就没有钱，就付不起租金。你懂的！鉴于我迫切需要一些钱，我需要相当多闪亮的美丽之物来弥补我的损失，可以这么说。$B$B你同意吗？显然必须同意。给我带来以下这些宝石，我会给你一些奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41285, '无论你听说过什么—那都是谣言！我绝没有为任何人制作过什么诅咒物品。我很尊重我的技艺，并且必须遵守誓言！请不要问我和谁立下的誓言。这是秘密，但绝不是邪恶的秘密。$B$B不管怎样，似乎一些冒险者又把别人的不幸怪罪到我头上，玷污我的名誉。事情起因是一位胆大的法师在前往北方最近被发现的吉尔尼斯城冒险途中，向我索要一根可以增强法力的项链。我当然答应并为他制作了一条。眼看付款期限就要到了，而他去了那个该死的地方就再没回来。。。。。。也许不用付款对他来说是件好事。可惜他的伙伴现在把他的失踪怪罪在我头上，还欺骗铁炉堡的人说我在项链上附加了什么邪恶诅咒！$B$B$N，我要你亲自深入吉尔尼斯城，把那条项链带回来！我最不想看到的，就是有人拿它来污蔑我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41286, '就这样吧，旅行者，我能教你的新东西不多了。但如果你对知识的渴求不止于此，那我就把我所有工匠技艺的来源告诉你。$B$B我本来不该告诉你的，但你之前热心地帮助了我，我不能让你空手而归。在遥远的西方，危险重重的凄凉之地，你会发现我隐居的导师。虽然他不希望被人打扰，但也许会对你这种陌生人有兴趣呢。如果他一开始不理你，请不要气馁，对于那些希望寻求知识的人来说，坚持不懈是他最喜欢的品质！$B$B寻找一座俯瞰大海的大塔，那是我最后一次见到他的地方。既然我们已经解决了这个问题，你最好快点离开，不然我的老板又会认为我在干坏事！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41287, '说实话，在荒野中，我们的物资并不充足，没办法好好教你。我可不像奥格瑞玛的矮个儿绿皮小朋友那样拥有无限的资源。不过，没有什么是我们无法利用的。幸运的是，这些土地拥有丰富的自然资源，你可以将其化为己用。$B$B把它当作一种考验，让我看看你多有能耐。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41288, '众所周知，宝石、贵重石块和矿物对于珠宝加工至关重要。虽然没有它们也能制作时尚饰物——但说实话，这样的饰物还有灵魂吗？在我看来，精致华丽的宝石是赋予珠宝产品灵魂的元素。$B$B给我带足够多的艾泽拉斯大陆的宝石，这样我们就可以一起分析它们的属性。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41289, '我的人民有着金匠和镶嵌的丰富历史，无论是可拆卸的还是永久的。虽然我会分享我对赞达拉古老金匠习俗的见解，但拓宽你的视野以了解其他知识来源也很重要。$B$B我希望你深入研究人类的制作方式。在北方，离我们的被遗忘者盟友不远的地方，你会发现古老的国家吉尔尼斯。据我所知，这个古老的遗迹，现在向那些渴望挑战危险的人开放。根据冒险家流传的故事，吉尔尼斯城位于高耸的山峰塔顶，是一个拥有自己的商业、贸易和习俗的地方。$B$B在那里，你会找到一份适合我们分析的文献。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41290, '亲爱的旅行者，谢谢你让我练习这项我很久以来无法做到的技艺。我曾承诺要继续磨练我的技能，但过去几年我一直为部落效力，我再也无法履行这个誓言了。然而，如果有更多像你这样的冒险者出现，我也许还是能做到的。$B$B对于你的帮助，我得好好奖励你——分享我提高金匠技能的地方。在遥远的西方，危险重重的凄凉之地，你会发现我隐居的导师。虽然他不希望被人打扰，但也许会对你这种陌生人有兴趣呢。如果他一开始不理你，请不要气馁，对于那些希望寻求知识的人来说，坚持不懈是他最喜欢的品质！$B$B寻找一座俯瞰大海的大塔，那是我最后一次见到他的地方。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41291, '那么你是坚持要学习金匠技艺？我一般不收学生，但是……如果我曾经的学生推荐你，还让你漫无目的地到处找我，那我显然不能拒绝你的请求。我们可以立即开始学习，但我们面临着一个小小的困难。不幸的是，我在收集被冲上岸的矿物时丢失了我珍贵的珠宝工具包。我当时被一个海巨人吓了一跳，我只能放弃，直到现在也没找到安全的机会取回它。我的战斗生涯已经结束，所以如果你想学习我的技艺，那你得帮我把它拿回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41292, '年轻人，你可以称呼我为“巧匠”。几千年前，伟大的城市埃雷萨拉斯沦陷时，我放弃了曾经的名字。从那时起，我就在卡利姆多大陆的荒野中徘徊，与我认为值得的凡人种族分享我的智慧。这位送你来这里的朋友——他是我教导过的被选中的人之一，这听起来可能令人难以置信。然而，似乎他对这门技艺的热爱并没有随着时间的推移而减弱，我感到很欣慰。$B$B你想学习跨种族、跨文明，甚至跨世代传承的百年金匠技艺吗？向我证明您的才能。让我看看你能多么清楚地听到大地之血的悲鸣。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41293, '所以说，他已经教会了你一些东西。好吧，请放心，他所拥有的大部分知识都是我传授给他的。他可能是一位熟练的珠宝匠，但却未能发现更多难以捉摸的秘密。如果你想深入研究一门技艺，就必须对它有深刻的理解。这恰好就是我希望你做到事情：告诉我，你对于金匠技艺的基础知识了解到哪种程度了，这样我才知道从哪里开始教你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41294, '真正的工匠会将生活的方方面面融入到自己的作品中。生与死、天与地、以及我们这个世界中起作用的元素。如你所知，艾泽拉斯的宝石拥有潜在的元素属性，在任何人手中都可能变得极其强大，或者非常危险。$B$B向我证明，你在制作珠宝时能够正确处理艾泽拉斯宝石的能量。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41295, '在过去的几个世纪里，我有过很多学生。坦白地说，我已经记不清有多少了，但有一个学生永远活在我的心中。一个年轻的精灵，白皙的皮肤，对金匠无与伦比的好奇和渴望。我欣赏她这种年轻而富有活力的风采。$B$B她对艺术没有偏见，认为它是一种表达心灵和灵魂的方式。当她完成了最后一个作品—一根高质量的法杖时，大风吹散了冒险之路—她离开了我。尽管我希望有朝一日她会回到我身边，哪怕只是一次看望。但遗憾的是，我们从未重逢。她的存在——以及她的缺席——给我留下了难以磨灭的印象，所以我教导今后的学生都要像她一样对工匠技艺有清晰的认识。请证明自己能够将她作为榜样。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41296, '我的族人已被分裂。为了寻求安全的生存之地，我们忍受苦难、背井离乡。虽然避难营的同胞坚韧不拔，心怀希望，但我敢说那些迷失者却不是这样。疯狂已经深深扎根在他们的脑海中，其根源再也无法斩断。他们徒劳地收集德拉诺水晶，试图回到德拉诺这个地狱般的世界。这些来自德拉诺世界的宝石强大而危险，但他们却不知道自己无法正确使用。然而，情况并非总是如此。$B$B他们中有一位强大的裂隙行者，名叫库米沙，他不同于农田避难所里疯狂的德莱尼人。他现在在南方危险的平原上游荡，寻找神话和传说。我寻求的是他对我们的神圣水晶的了解—但如果你能够说服他加入我们，请马上行动。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41297, '迷失者的领袖变成了愚蠢的傻瓜，对神圣的德莱尼水晶垂涎三尺，失去了目标也失去了未来，所以我离开了他们。珊弗科拉也不例外，不切实际的幻想毒害了迷失者的心，导致他们迷失在贪婪之中。你也不例外。你站在我收藏家库米沙面前，想必只是想夺走你想要的东西吧？但我了解你们这些人，你们的贪婪倒是可以发挥点作用。$B$B呆滞的德莱尼人在这个被诅咒的土地上游荡，他们掌握了裂隙行者的魔法，但却无法使用。他们已经失去了理智，不断地搜寻德莱尼水晶，像蟑螂一样在地上乱爬。这些野蛮的疯子偷袭了我的营地，偷走一些珍贵的水晶。杀了他们，夺回我的宝物，也许我会奖励你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41298, '<库米沙正在研究这份外来卷轴，他的身影时而出现在我的视野中，时而消失。读完之后，他愤怒地将羊皮纸撕成碎片。>$B$B卡拉克托卡尔！他们在想什么？这对所有德莱尼人来说都是异端，异端！他们像无头苍蝇一样在这片死亡之地漫游，虽然并不构成威胁，但令人担忧。然而，他们的目标却非常危险。根据这些文字，你遇到的搜寻者正在为一个邪恶的生物收集德拉尼水晶，一个名叫马托加尔的裂隙行者，仅此一点就已经亵渎了我的信仰。但他们真正的目的是邪恶的，必须被阻止。如果他们把水晶带到德拉诺，我们唯一的回家之路就堵死了——我们将被诅咒，被囚禁，归乡之途终究不能实现。$B$B你不会让这种事情发生的，因为库米沙会满足你的愿望用以换取他的头颅。他正在我的营地西北部等待他的寻隙者。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41299, '来，拿着这个卷轴。上面记载着我对德莱尼水晶的了解，只要不干扰我的计划，你和天真的珊弗科拉就可以随心所欲地使用。他最好听从我的警告，否则就会像马托加尔的下场一样。$B$B至于你：如果你不想继续帮我做事的话，就快滚吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41300, '天呐，真是糟糕！一个侏儒能有多不幸？我犯了一个可怕的错误，现在它会让我失去理智，甚至更糟——我的家！$B$B长话短说，我的财务状况非常糟糕！尽管我绝望了，但我还是接受了一位可疑商人的提议，并承诺会给我一大笔钱。然而，在他第二次来访时带着两个可怕的打手，向我索要比预定更多的货物！我向他解释没有那么多，但他们不听——现在他们还在威胁我——宽宏大量、气度非凡的塔瓦斯德·基瑟尔！$B$B请帮我解决这个麻烦！我保证，你会得到合适的回报。这伙恶棍已经离开，去了下议院方向，我敢肯定这些恶棍就藏在外环无数的房子里！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41301, '你来这里想怎么样？是礼貌地要求我停止骚扰你那位不愿履行承诺的朋友？还是来这里采取更……强硬的手段？很遗憾地告诉你，这两种方法都行不通。我的组织是很重视承诺期限的，那些无法按时履行承诺的人……$B$B<他指着站在你身后的两名可怕的打手。>$B$B但是呢，我是一名友善的商人，不会因为交易对象令人失望的做法而放弃赚钱的机会。相反，我会给你一个提议。把塔瓦斯德欠我们的货物数量翻倍，我和我的朋友们就会考虑放过他。非常合理，不是吗？俗话说，识时务者为俊杰……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41302, '<在莫特索格仔细检查货物时，你可以感受到身后的打手正盯着你。这个狡猾的商人检查完毕后，把珠宝放进一个盒子里，然后扔给你一袋钱。>$B$B很高兴和你做生意。拿去给你的朋友。从今以后不要让我看到你，快滚。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41303, '真是一场灾难！我名誉受损，财富流失。我那些珍贵的珠宝被运往藏宝海湾的拍卖会，其中还有一枚特别珍贵的戒指。我以为它们安全抵达港口城市，便继续工作，没有多想，不知道它从未离开棘齿城！现在我成了尊贵商人和拍卖师们的笑柄，他们在嘲笑我的无能。$B$B亲爱的朋友，你能否帮我解决这场灾难？我最信任的承包商格雷兹比不见了，我不能失去这些价值连城的货物。由于没有任何线索，你最好在棘齿城附近打听一下。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41304, '我认识格雷兹比很久了，他是个善于交际的人。他有很多朋友，他的工作就是如此。我当时正在处理一些事务，因为下一艘船要很长时间才到，格雷兹比来到码头与我聊了一会儿。$B$B就在我们消磨时间的时候，另一个地精走过来，就像见到失散多年的兄弟一样，他们熟悉而亲近地攀谈起来。我没有听清他们在说什么，好像是说要去南方什么的，不知道具体什么原因。$B$B已经过去一段时间了，我有点担心格雷兹比的安全，请务必找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41305, '我会亲自把这份合同带给纳特，他应该知道我们以前的雇主在科赞的阴谋。如果可以的话，我会直接走进安德麦，把他们的贸易大王扔进贫民窟的最深处。但我不能，所以我必须尽我所能。$B$B我的珠宝被盗，物资也快用完了，我已经无法为下一次拍卖做任何准备——我必须在拍卖会上拿出一些轰动的东西，否则我的名声就毁了。我看你挺能干又有才华，愿意再帮我一次吗？$B$B我需要一颗巨大的宝石，我在怒水港的冒险者那里听说血色十字军拥有一颗拳头大小的红宝石，我猜在他们的首领身上。此外，一条简单的金项链可以让我把红宝石放进去，你应该可以自己动手制作。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41306, '话说，我这么倒霉，也许是被谁诅咒了。看看现在的贸易路线上到处都是海盗，海运货物就等于直接送给那些戴着大帽子的海盗。这显然不行。我还有另一种选择，那就是走陆路，但同样危险，你肯定知道我在说什么。$B$B不管怎样，我选择了后者，因为我实在是很需要运送这批货物。所以我在棘齿城出钱雇了一个看起来最凶狠的食人魔陪我去热砂港。可惜我们被亡灵野猪人伏击了，他们把我珍贵的货物连同食人魔一起带走了。$B$B我快绝望了。你能从剃刀高地取回我的货物吗？我不知道他们会怎样对待我的食人魔保镖，如果他还活着，他应该能找到他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41307, '很抱歉，失败了，萨哈斯没有足够的力量保护绿皮小朋友。凶恶的野猪人把我带到这里。他们想吃掉我，但妈妈总是说萨哈斯太胖了，可能味道不太好。$B$B如果您正在寻找特拉克西斯的盒​​子，它就在这里。可怜的萨哈斯被石头击中，想逃跑，但所有的石头都掉了下来。现在恐怖的僵尸和鬼魂已经拥有了闪亮的宝石！萨哈斯想回家，你可以把特拉克西斯的珠宝收集起来交给塔纳利斯的小侏儒。特拉克西斯说那个侏儒正在海边的小镇上，等着箱子！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41308, '好吧，我收回刚才的话。我绝对不会再向他订货了！这些宝石都表面有裂痕是怎么回事？他做了什么？$B$B<你向凡齐解释这些宝石是如何进入几个不死生物的胃里并被他们的胃酸腐蚀的。>$B$B呃，你没必要解释得这么详细，太恶心了吧。正好现在我手头有点额外的工作，但是我现在忙不过来，但幸好有你在这里。哦，别用那种眼神看着我，我会付钱给你而不是特拉克西斯，他最好不要出现在这里。$B$B要修复宝石，我们需要一些更有用的东西，普通的宝石油是不行的。这里南边不远处有一个靠近海滩的小海湾，你会发现。。。一个我们称之为生意伙伴的人。带上海岸线上那些海龟的腺体，一个强效秘法精华和一个水晶瓶，告诉他是我派你来的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41309, '<萨拉辛将油性腺体挤进小瓶。他一边用嘶哑的声音喃喃自语，一边施展不知名的魔法，让混合物发出耀眼的光芒。>$B$B拿去吧，陌生人。这种油应该可以封住宝石表面的裂缝，使其可以被精确加工。赶紧走吧，虽然我允许她经常来我这里，但你不一样。也许我比我的同类更好客，但也并不意味着我的耐心是无限的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41310, '<你找到的这本书看起来并不像其他散落的书卷那么古老，上面装饰的肯瑞托的印记，看起来属于一位强大的法师。$B$B你翻阅着书页，推测这是一位名叫卡德加的法师的日记。你之前听说过，他是守护者麦迪文的年轻弟子，也是德拉诺远征军“洛萨之子”的成员，在第二次战争期间带领联盟进攻德拉诺。$B$B你更加专注地研究里面的内容，也许会揭开更多的谜团。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41311, '我亲眼目睹了阿尔萨斯在恶魔领主的命令下围攻达拉然。他的军队在抢夺麦迪文之书的过程中犯下了令人发指的罪行，洗劫了我们保管在金库中一些贵重的遗物。我在一个寻求毁灭和杀戮的强大末日守卫面前，全力保卫这座魔法城市。如果你要寻找桑拉嵌座，那么你得先找到这个末日守卫。在达拉然陨落后的重建时期，幸存的法师们调查出阿克蒙德及其军团的下一个目标——西边的世界之树诺达希尔。如果末日守卫还在艾泽拉斯大陆上，那么他应该在靠近海加尔山的一个恶魔出没的深渊里策划着邪恶的计划。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41312, '当这个嵌座被存放在达拉然的肯瑞托时，我深入研究了它的形态、功能和用途。虽然麦迪文是个神秘的人，但他所用的器具和饰品都带有类似的魔法标记。即使是不熟悉守护者的法师也能注意到这一点。我在研究后得出结论，这个嵌座是某个伟大物件的一部分，而这个物件又是一个更伟大神器的一部分。从它的形状来看，它的顶部应该有一块巨大的宝石。$B$B如果你在那座鬼塔的冒险中找到这样的宝石，我相信我可以把这件神器恢复到原本的样子。然而，要做到这一点，我需要强大的奥术能量来引导我的法术。蓝龙军团是艾泽拉斯魔法的守护者，他们保管着这些物品，但只有他们之中最强大的成员才会随身携带。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41313, '这个世界充满了魔力。众多的原因让我来到这里进行研究，其中之一就是遍布大地的无数地脉。强大的奥术能量就像奔腾的溪水那样涌出，吸引无数的从各个世界而来渴望魔法的生物。我希望更清楚地了解为什么这片被遗忘和诅咒的土地会出现这样的现象。别让好奇心从你眼中溜走——你打算帮助我吗？$B$B我还有其他事情要做，所以如果你能出去帮我找来些材料，你会得到回报。我需要的是地脉能量的结晶，我的学生们找到了两个，分别位于这里的东边和南边。也许那里的蓝龙和堕落的血精灵是我们最好的线索，就从那里开始搜索吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41314, '这两颗水晶具有相同的整体结构，但是朱红色那颗——当与我的微量魔法产生共鸣时……$B$B<克希雷姆将少许魔力注入红色水晶，便爆发出剧烈的火花和布里森。>$B$B现在我们掌握的情报：蓝龙军团出于某种原因从门纳尔湖收集地脉水晶，而水晶的生长或许以某种方式被人为加速。这里的血精灵也同样拥有这种水晶，但比我们之前得到的水晶更不稳定。这两种情况是否有关联，仍需调查。$B$B我将继续测量这些水晶的稳定性，同时麻烦你帮我取回一件重要的遗物，我们需要它来完成研究。我以前的一个学生愚蠢地以为把它从我的塔里拿出来不会被人发现。萨纳斯告诉我，那个可疑的学生匆忙离开前往东部的木喉要塞附近，毫无疑问她在利用当地的关系来隐藏自己。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41315, '拿回聚焦宝珠后，我们还需要做最后一件事。来，把水晶和宝珠放在我塔前的基座上。我对宝珠施加的咒语将与地脉水晶发生反应，能证实我关于它们性质的理论——希望如此。$B$B不要害怕，我会在塔内观察着你，随时进行必要的干预。你很能干，不要太过担心，但时刻记住：细致谨慎是明智之人的生命线。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41316, '这本书再次被装订完整，原本空白的封面上神奇地出现了标题——高级珠宝加工XI：坚如磐石。你试图打开它，感到一阵剧烈灼烧的疼痛感。封住书卷的锁上出现了一个炽热的符文。也许某个珠宝匠可以帮助你破译它的秘密。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41317, '我花了毕生的时间来研究这本传奇的珠宝制作百科全书。传言说，这些上古世界遗物的主人，是今天我们所知人类的祖先。考古学家发现了越来越多的遗物——这些祖先被称为阿索拉。到目前为止，只发现传闻十一本之中的五本。我认识的一个同样古老的人打开了其中一本——并告诉了我这件事。他说这些书是用元素符文封印的，元素符文是用艾泽拉斯元素制作的古老文字。从那时起，我就一直在研究它们，这把锁上火焰的符文似乎是布莱兹的符文。$B$B我们需要一个与该符文对应的元素碎片。听说黑石山最深的洞穴，充满了炽热元素的熔火之心。我相信能够在那里找到我们需要的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41318, '那我们随机应变，先研究这一页，看看上面写了什么……“汝追寻真理，奉上土与火之心，提取能量以揭示真相。”古人阿索拉确实喜欢他们的谜语。我猜这与之前的情况类似，我们必须在拥有合适的材料的情况下，才能解开这本魔法书的秘密。$B$B土与火之心……这一定意味着一些强力元素比如炽热之核或者熔岩之核。从中提取热量……也许是火焰精华？是的，一定是它！$B$B$N，你知道该怎么做。我会在这里等你带上所需的材料，并试着理解这本“超乎寻常”的书。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41319, '越看这些东西，我就越相信这些书里所有的秘密都只是某个卑鄙的地精为了快速赚钱而耍的花招。其中只有一两页上有字迹，而在这里甚至连一句话都没有！“通过血液的结晶引导太阳的能量。”这到底是什么意思……等等！我明白了！$B$B<凡齐翻了翻她的东西，然后拿出一张蓝图。>$B$B这些是我从未制作过的珠宝透镜的设计图。它可以把光线汇聚成能够加工金属的强力射线。它需要非常特殊的材料——现在轮到你发挥作用了。“血液的结晶”一定是指黑石山深处非常稀有的山脉之血。另外，我还需要一个镜头框架，黑石深渊的弗诺斯·达克维尔拥有一种透镜，可以抵御山中高温。把这两样东西都给我，我就能制作出一件工具来解读这本书上的文字！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41320, '陌生人，我跨越了多个世界，经历了无数危险的旅程。裂隙行者能够使用不存在于艾泽拉斯的古老魔法。要施展这个法术，需要大量的能量，而经验不足的裂隙行者通常会利用德莱尼水晶，这是我们那个世界生命之血的源泉。珊弗科拉让你来找我是明智之举，因为我对返回家乡德拉诺的努力中所经历的一些事情感到震惊和疲惫。$B$B坐下来，继续听我说。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41321, '在拯救族人之前，需要做一些准备，包括我自己和所需的物品。裂隙移动魔法非常耗费施法者的精神，期间中断就更会如此。如果我没有恢复精神能量，就无法拯救大家。$B$B我的族人发现，吞食生物的大脑可以加速恢复精神能量。野兽越聪明，你的精神就恢复得越快。我在岸边看到蛇一样的怪物四处爬行，其中一些还会施展法术。给我带回来这些会施法的怪物的完整大脑。$B$B希望你们世界的物种是我想象的那样聪明。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41322, '暴露在扭曲虚空的湍流中是一种危险的行为，这种影响至今还残留在我身上。德莱尼人有种世代相传的古老配方，用以对抗长时间裂隙移动的副作用。虽然在这里无法获得我们世界的传统材料，但这里的动物看起来也很健康，也许可以当做替代材料。$B$B在我向东冒险时，我遇到了长着巨大多肉爪子的可怕生物——它们的肉应该能提供足够的营养。在西边不远的地方，毛茸茸的生物采集着气味浓烈的草药。从气味判断，应该具有药用价值。给我带来以上两种足够的材料，我就可以为我疲惫的身体制作这种古老的药。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41323, '现在我感觉精神了许多，下一步就是找回最珍贵的宝物：我的裂隙行者法杖。那时我被困在赤褐色草原的悬崖边上，被恐怖的生物包围。他们的样貌犹如恐怖的燃烧军团，其中还有一个使用邪恶诅咒魔法的头上长着角的恶魔，他们像捕食受伤动物那样向躺在地上毫无防备的我慢慢靠近。我好不容易才逃脱，慌忙中却弄丢了裂隙行者法杖——对于这个意外，我久久不能释怀。$B$B现在就算找回这把耗尽能量的裂隙行者法杖也已经毫无用处。我需要给它注入新的能量——从一位禁忌法术的专家。去往悲伤沼泽，一座沉没的神庙耸立在树冠之上。里面住着一位巫术大师，他可以控制死去的巨魔和龙类。结束他在神庙和沼泽的恶行，并将他的能量精华带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41324, '现在，你只能在做到这些了。为我的裂隙行者法杖注入这种新能量需要的时间比我们预想的更长，所以我需要你继续前进。在我为法杖充能时，你将前往诅咒之地，悲伤沼泽南部的荒凉的平原。我的徒弟卡斯塔尔等待着你，他在一座山顶上俯瞰着这片红色沙漠。在这一切发生之前，我命令他调查黑暗之门附近的可疑波动。他肯定很担心我，请务必向他保证无需担心我的安全了。$B$B一旦你找到他，告诉他我会在避难营等着你们，这样我们就可以为任何不希望发生的事做好最坏的打算。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41325, '大师把你派到我这里，真是太好了，感谢他敏锐的洞察力。几分钟前我目睹了一件非常可怕的事。你看到右边那个诡异的黑暗之门了吗？这是远古兽人入侵你们世界的遗迹。大师对黑暗之门能量的怀疑是正确的。就在你来之前，一股巨大的能量涌动和可怕的毁灭力量冲刷了这片红色沙漠。$B$B直觉告诉我，这里面的东西一定不简单。$N，绝对不要独自面对它。虽然老师很信任你，但我们即将面对的事对你一个人来说还是太过沉重了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41326, '快点，赶到避难营并警告珊弗科拉！如果我们不及时撤离，谁知道会有什么可怕的悲剧降临到我们身上呢！在此期间，我将尝试联系阿克资阿多大师，希望他能比预期更早地帮助我们。$R，我把所有的希望都寄托在你身上。也许还有时间。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41327, '现在避难营一片混乱，很多人都受了伤。虽然我们还有很多事情要做，但请您原谅我只能优先照顾族人。我很感激您帮了我们那么多，但有些事情，我们必须坚持自己来做。您已经做得够多了，我们再要求更多就显得太不礼貌了。$B$B不过，在您离开之前，阿克资阿多希望再次与您谈谈一些紧急的事情。您可以在外面找到他。“EnkilToralar（艾瑞达语）”，朋友，祝您好运。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41328, '$N！很高兴再次见到你，你过得怎么样？我的族人们仍在恢复元气，但他们的士气仍然很高。他们中有些人仍对即将到来的不确定未来感到焦虑。$B$B我一直在研究我给你的纯净德莱尼水晶宝石的制作过程，现在应该可以利用从中得到的知识再制作一颗。虽然制作它需要大量的能量，但绝对物有所值。如果你想要另一颗宝石，请把下面的东西带给我，我非常乐意效劳。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41333, '<你手里拿着的这本书虽然纤薄，却感觉非常沉重。仔细检查书页后，你意识到其中大部分内容都超出了你的理解范围。也许其他人，这方面的大师可以帮你解读这本书。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41334, '<你手里拿着的这本书虽然纤薄，却感觉非常沉重。仔细检查书页后，你意识到其中大部分内容都超出了你的理解范围。也许其他人，这方面的大师可以帮你解读这本书。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41335, '<你手里拿着的这本书虽然纤薄，却感觉非常沉重。仔细检查书页后，你意识到其中大部分内容都超出了你的理解范围。也许其他人，这方面的大师可以帮你解读这本书。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41336, '嗯，真奇怪。这句话……缺少一个符文，没有它，我就无法解读这段文字，看来我们不得不停下。不过别以为我会就此放弃，这种事根本不会成为多大的障碍。$B$B<巧匠拿起一根微型法杖样式的小工具，沿着书里的句子比划着。沉思片刻，他转身面对你。>$B$B我知道在哪里可以找到缺少的符文。实际上这本魔法书的本质就是用魔法创造的，因此上面的文字也是如此。我们可以用类似效果的符文来替代它，通灵学院里有个阴森的大厅里或许可以找到。我听说那是一个令人痛苦的地方，但里面的邪恶研究为我们这个问题提供了解决方法。从他们的一位通灵导师那里取回一个这种形式的符文，把它带回来给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41337, '<你手里拿着的这本书虽然纤薄，却感觉非常沉重。仔细检查书页后，你意识到其中大部分内容都超出了你的理解范围。也许其他人，这方面的大师可以帮你解读这本书。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41338, '$C，在神圣的海加尔山之巅，一则震撼的消息如风般传开：我们长久以来的恐惧——梦魇，已然卷土重来，其黑暗的触手再次伸向了我们的世界。许多英勇之士已经响应召唤，踏上了前往世界之树的征程，决心助我们的同胞一臂之力，共同抵御梦魇的肆虐。$B$B$N，我恳请你登上海加尔山，与诺达纳尔的守护者并肩作战。你的力量，将是我们驱散黑暗的关键！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41339, '$N，当我们的族群在现实世界中英勇奋战时，伊瑟拉与她的盟友——那些古老的荒野诸神们，也正倾尽全力抵御梦魇的猛烈侵袭。梦魇，这一潜藏在翡翠梦境深处的邪恶力量，虽深不可测，却始终被他们牢牢地压制着。$B$B数年前，第三次大战期间，怒风大导师和高阶女祭司语风，在海加尔山低山区域中一座被尊为神圣的山丘上，曾与某个强大存在举行过一场秘密会晤。那座山丘原本恒定地散发着他们会面后留下的神秘能量，然而近期我们却察觉到，整座山体开始异常地散发出不和谐的波动。鉴于目前情况的紧张性，我们迫切需要尽快揭露这背后所隐藏的秘密。$B$B$N，前往暗谷小径南面的那处地方，回来告诉我你找到了什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41340, '在艾泽拉斯的漫长历史中，唯有一位存在与你的描述相契合——那便是荒野之神马洛恩，被誉为道路的守望者。自世界诞生之初，他便已存在，是分裂前的原始守护者，在无垠的荒野中自由穿梭。他的力量深不可测，威严令人敬畏，但他的慈爱和对自然的呵护也使他深受爱戴。$B$B你所经历的景象实在令人惊骇，若噩梦之力竟侵蚀了伟大的马洛恩，哪怕只是一丝一毫，都足以让我们心生恐惧。刻不容缓，我们必须立刻采取行动。$N，在我向月光林地传达此消息的同时，我恳请你搜集二十枚璀璨的梦幻碎片。这些碎片至关重要，它们能保护你免受噩梦的侵蚀。请你协助我们，遍寻海加尔山的每一寸土地，尽快集齐这些碎片！$B$B一旦你完成任务，请即刻前往月光林地，将碎片交予守护者雷姆洛斯。他将为你提供进一步的指引。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41341, '玛洛恩绝不能沦为梦魇的傀儡。幸运的是，梦魇所控制的仅是玛洛恩从翡翠梦境中逸散出的一缕灵魂。然而，即便是守护者的一小部分力量，也足以让梦魇在这场对我们不利的战争中占据压倒性优势。为了清除祖父身上的邪恶力量，我们必须找到能够唤起他对亲人深切记忆的遗物。$B$B我们需要寻回塞纳留斯之角，那是我父亲鹿角的一部分，曾在他殒命灰谷后被带回影歌神殿，进而安葬于月光林地。或许，神殿中的龙人知晓它的下落。$B$B此外，伊瑟拉——玛洛恩的挚友与父亲的养母——她身上的一块翠绿鳞片对我们至关重要。她珍爱的子嗣们都持有这样的鳞片，但他们多居于遥不可及的翡翠梦境。$B$B最后，我们还需寻觅一件与月神艾露恩相关的圣物。传闻，她的守护者——月夜枭兽在冬泉谷藏有诸多神器，那里或许有我们需要的线索。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41342, '年轻的勇士，请接过这把记忆之杖，它由你带来的遗物与梦境碎片共同铸就。此杖将赋予你力量，让你能在噩梦的侵袭中坚守，直至从它的掌控中夺回玛洛恩的灵魂碎片。$B$B但请务必小心，噩梦不会轻易放弃它的猎物。你需寻求盟友，集结志同道合之士，共同拯救我祖父的灵魂。$B$B行动须迅速，切莫让噩梦有机会在我们的世界中彻底显现。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41343, '$R，这里？拜托，不要杀人。不杀大尖叫！大尖叫在这里是个错误。大尖叫看到透明的人。大胡子只想离开。但大尖叫不能离开。不。大尖叫首先需要大蜡烛！$B$B大蜡烛对大尖叫和他的朋友们非常重要。是的。大胡子给奖励，奖励，是的！带上大蜡烛给大尖叫。拜托？$B$B问门卫，门卫准知道！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41344, '当我思考你的请求时，我感到不确定，不知道该笑你还是关心你的理智状态。你对这个相当大的，我是说巨大的烛台的要求，暗示了主人实验室内的某种实验。$B$B您描述了您打算完成任务所需的蜡烛的大小，以及您进入该场所的可疑方式，我承认我感到怀疑。尽管如此，我确实感觉到你身上散发出一种明显的强大气息，这让我相信你有能力在那些神秘的大厅中穿行。$B$B说了这么多，我似乎记得在访客大厅的尽头放了一根相当大的蜡烛。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41347, '我无聊得无法估量。我被锁在这永恒的炼狱中，它并不像你想象的那么痛苦，而是更加令人难以忍受的乏味。我再也无法体验尘世的乐趣，我对珠宝的热爱也因无法佩戴而稍减。即便如此，我最喜欢的小首饰已经不为我所有。$B$B当我收到麦迪文的邀请时，我的物品中有一堆珠宝和宝石。最珍贵的是一条价值连城的项链，纯正的艾泽拉斯钻石，装饰在精致的奥金链子上。比这闹鬼大厅里的任何客人一生中所拥有的都更有价值。哦，如果我在死亡的那一刻只带着它，我仍然可以珍惜它的美丽。唉，它已经被偷了，比你现在的时代早了很多年。我最后一次看到它是在我离开暴风城的庄园之前。$B$B生者啊，帮我找到我的宝藏，我会用麦迪文亲自送给我的一件珠宝来奖励你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41348, '您在寻找厄尔威克庄园？别逗我笑，那个悲惨的地方只不过是一段回忆，几年前就被烧毁了，还有我所有的梦想和希望。你眼前看到的就是厄尔威克这个名字最后所剩下的东西——这堆可悲的、毫无价值的残渣。$B$B<他喉咙里打了个嗝，呕吐物也随之而来，滴到了他已经脏兮兮的衬衫上。>$B$B我们失去了一切，一切！他们洗劫了我们的金库，杀害了屋内的任何人。甚至……甚至我心爱的乔治娜......看到她躺在那里，毫无生气......我为她偷来的钻石项链，仍然闪闪发光......那只野兽，那个兽人从她身上扯下来——我可能是瞎子，但我仍然能看到它......在我的脑海中！他如何大笑和崇拜他的首领，那个毁灭之锤！我永远不会忘记那个怪物，永远！如果是我，我会把他们全都杀了，而不是把他们关进营地！$B$B无论你想从我这里得到什么，我都没有，别再问我问题了！滚开，别管我！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41349, '<幸运的是，你似乎有所发现。这个兽人的日记中有关于你寻找的项链的信息>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41350, '<检查这把剑发现，除了它明显的破旧状况外，你看不到任何异常。剑刃脆弱且生锈，而剑柄的皮革在你的摸它时正在剥落。它的剑柄出奇地完整，边缘有精致的雕刻。上面写着：H.C.在它上面，可以看到新月内的洛丹伦标志。也许这就是剑的主人。如果命运女神站在你这边的话，他有也许有那条项链>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41351, '你带到我面前的那把断剑属于拉祖夫·伊瓦尔迪，洛丹伦最强的骑士之一。在洛丹伦围城的命运之日，仅他的剑下之鬼就比其他任何士兵都多，因为他一击就砍倒了他们。$B$B在侵略者被击退后的几天里，他被誉为勇士，因为正是他阻止了那个如入无人之境的恶毒女兽人。作为击杀她的战利品，他从她那里拿走了一条美丽的钻石项链——这条项链被她狂热地抓住——宣称这是他最伟大成就的证明。$B$B他是个好人和好朋友，但他对那个吊坠及其含义的痴迷使他心烦意乱。我最后一次看到他是在他带着叛徒米奈希尔回来的时候，当时他作为他的死亡骑士同伴之一，将他那被玷污的符文剑刺向了我。$N，我恳求你找到他，代替他的师长让他烦恼的灵魂得到安息。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41352, '<完成工作和奖励后，你只剩下一枚昂贵的金戒指，这对你你毫无用处。鉴于这实际上是伯爵家族的财产，你思考阿基巴德是否会在他糟糕透顶的境遇中接受这个>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41353, '只需轻轻一按，紫水晶就会开始在昏暗的灯光下闪耀，很容易让您的眼睛一直沉迷的注视它。然而，吸引你心动的并不是它的美丽。一个声音在你的脑海中响起。一个不属于你的声音。它以严厉而舒缓的语气回荡着：$B$B“你得多想一想因塔苟斯。回到凯斯利尔并在我面前找到安慰。那座塔是不可预测的，它祈祷的魔网纯粹是混乱的。不要再自欺欺人了，朋友。还有别的方法！$B$B紫水晶不再闪耀。每当被触碰时，它都会简单地说出同样的信息。你偶然发现了一件多么奇怪的事情。也许探索凯斯利尔湖会为您提供某种答案。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41354, '紫水晶似乎正在失去它的魔力。我请求你不要质疑它的运作方式。这是一个秘密，也许应该与我的这个家一起消亡。$B$B唉，我向你表示欢迎。这里曾经是一座值得流连的城市，现在则是我和我亲人那不安的灵魂的归宿。我不知道你为什么找我。我非常怀疑这是杀死因塔苟斯的罪业。$B$B<阿尔多雷尔叹息着.>$B$B一个愚蠢的儿子试图取悦他的父亲。然而我或你又有什么资格，能评判他的对错呢？如果你寻求的是答案，你就得先帮我。我就用我的答案来报答你。徘徊在附近的上层精灵必须得到安息。在湖的另一边，可以看到它们毫无目的地游荡。让他们解脱，你会得到我的感谢。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41355, '因塔苟斯寻找高塔，是因为那里不稳定的魔网，以及在那里徘徊的强大力量。因塔苟斯试图在蓝龙军团中扬名立万，以推进他们对艾泽拉斯进行伟大控制的事业。他想亲自见玛里苟斯，但哈尔琳否认了他这个权利，因为她认为现在还不是他们见面的时候。$B$B我不确定她的理由。事实上，我开始日复一日地质疑蓝龙的行为，因为他们开始变得相当激进，甚至对那些他们曾经称之为盟友的人也是如此。有几次我会在我破败的房子里接待龙族。可悲的是，这样的时代已经过去了，现在他们偷走了对我来说神圣的东西。$B$B在你了解更多关于因塔苟斯的选择之前，先把这个东西给我。一架远古的月锻望远镜，可以通过其迷人的水晶看到天空之外。$B$B他们应该把它带到东南方向的麦索瑞尔内。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41356, '在因塔苟斯动身前往东部王国之前，我试图给他提供建议。因为我真的是蓝龙的朋友。我告诉他，他寻找的魔网是不稳定的，即使是他，一条蓝龙，也无法真正驾驭它。唉，即使是我——甚至伟大的守护者都无法真正理解。$B$B在他离开之前，他选择在霜语峡谷中休息。他在巨人之中找到了慰藉，我想不出任何原因。龙在沉睡时会脱落鳞片。让那些游荡的巨人灭亡，他们可能会扰乱在这些土地上漫游的元素。同时搜寻我们需要的鳞片，因为它们可以告诉我们更多。$B$B不要动摇，朋友。也许你认为我的这些任务毫无意义。但我向你保证，我们不能放任这些不管。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41357, '朋友，请看一看。这些质朴的鳞片曾经闪耀着蔚蓝的光泽。然而现在，它们毫无生气,它们更像是一块未经加工的青金石。我对你没有恶意，不要担心。我只是对因塔苟斯的死亡感到遗憾。如果我再快一点，也许他会活下来。$B$B无论如何，我们似乎还没有更接近真相。我很害怕这个。随着因塔苟斯的消失，这些鳞片的魔力早已消散。我们可以短暂地让它们恢复生机。但要做到这一点，我们恐怕得吸取另一条蓝龙的生命，诸如此类。$B$B恐怕你得再次往东走了，朋友。在现在最大的人类王国、暴风城地牢中，您会找到它。那个可鄙的造物。它为什么那样做，我永远无法理解。寻找阿克提阿斯的活碎片。在它的核心中，您会发现蓝色的魔力，玛里苟斯的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41358, '收集了这些物品后，我终于可以找到我们俩都在寻找的答案。请允许我花点时间施展我的咒语。$B$B<阿尔多雷尔闭着眼睛低声哼唱。>$B$B这很难接受。我不确定该如何应对。我——我想这无可避免。亚雷戈斯寻找高塔的魔网，因为蓝龙们认为艾泽拉斯的凡人种族配不上奥术。看来玛里苟斯本人正在为......我不会称它为战争或战斗。$B$B蚂蚁会把你的脚看作是宣战或战斗吗？或者只是纯粹的灭绝。我必须知道是否所有人都认为这是正确的道路。我不能离开这个地方，所以拜托了。请代表我与哈尔琳交谈。她是卡利姆多的母龙。她在麦索瑞尔上面休息，洞里面有一个符文，你可以用它来联系上她。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41359, '所以因塔苟斯已经死了。如果不是阿尔多雷尔派你来的，我会用我的牙齿而不是我的言语。唉，我想意外又一次带走了蓝龙的孩子。$B这都是真的,凡人。蓝龙军团随时准备剥夺你们凡人种族的奥术。我希望尔等不敢质疑这个决定。你们的愚蠢不仅带来了大分裂，该死的燃烧军团和随之而来的一切。通往异世界的门户？这是一项伟大的壮举，用鲜血换来了一百万倍的回报。$B$B作为这个世界的保护者，我们应该限制对奥术的访问。然而，你们所有人都变得如此盲目自大。玛里苟斯大人，也正是那个教导了你们中第一批法师的人，已经决定了你们不再配承担这个责任。艾泽拉斯可以治愈，新的种族可以诞生。$B$B有时，空白的画布是解决问题的最佳方法。将此视为警告，然后离开吧，因为我仍然对一个同时扮演拯救和终结因塔苟斯的人感到遗憾。告诉阿尔多雷尔，只有他一个人可以幸免。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41360, '看来，因塔苟斯并不是唯一一个这样做的人。他们怎么能如此盲目，如此无情？他们必须明白，这不是他们必须走的路。他们必须！$B$B<阿尔多雷尔叹了口气。>$B$B好了，朋友。这真相即使你说出去，也没有人会相信。我们所能做的就是活下去。即使在这寒冷的土地上，也能感受到太阳的温暖。末日和死亡的承诺永远无法阻止我们活在当下。别担心。因为我是蓝龙的朋友。我会准备好的，你也会。$B$B$终有一天，我们将再次相见。我祈祷这段时间会尽可能长。在那之前。来吧，我有一个来自我们多年前还活着时的纪念品，我想送给你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41361, '<难以忍受的烟雾让人很难看清，但你还是在沸腾的地面上发现了一块充满活力的水晶，摸起来很烫。虽然它的价值非常高，但你不敢尝试在宝石上工作，因为缺乏正确切割宝石的专业知识。看来你需要找一个能教你这些技能的人。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41362, '你的假设是正确的;我确实可以教你如何自己切割山脉之血。然而，要做到这一点，需要一套我无法使用的试剂。这个仓库曾经很多，但随着索瑞森计划的所有阴谋，好玩意都耗竭了。$B$B来，把这些材料给我，我很乐意向你展示切割山脉之血的古老黑铁技艺。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41363, '你可能已经和我的弟子奥兰达利亚会面了，她已经亲自领受了调查哀嚎洞穴中出现的危险的任务，哀嚎洞穴是灰谷以南贫瘠之地的一个被诅咒的洞穴迷宫。$B$B虽然高贵——当然也很天真——但纳拉雷克斯的愚蠢对卡利姆多的平衡造成了无法弥补的破坏，最明显的是从石头迷宫中发芽并异常生长的植物。其中一些植物开始自行移动，这证明了纳拉雷克斯的非自愿力量的潜力。我想研究这些植物，以便与塞纳里奥议会一起制定对策。.$B$B给我带来足够的植物样本,就你在哀嚎洞穴里能找到的最凶猛的那种就行，你会得到奖励的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41364, '你好$N。还在找活干？我有一份报告需要送到格伦郡的纳格拉斯男爵那去。$B别担心，你不用把报告送到他本人手里。你所要做的就是把这个卷轴交给亡灵卫兵马库斯，他应该驻扎在纳格拉斯男爵出没的教堂外面。$B$B只是为了让他们知道我们已经决定派冒险者进入影牙要塞。不能让阿鲁高活着。到达格伦郡应该不会那么难。您可以沿着小路向北走，也可以回到提瑞斯法林地并通过穿越索利丹农场到达它。取决于你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41365, '格伦郡没有很多圣光信徒，尽管很明显，当时我们都相信自己是生于圣光。相反我们更专注于保护我们的土地。即使是现在，由于我们所谓的黑暗重生，我们能够再次行走在大地上，我仍然效忠于这个地方的人民。我在世时未能保护公爵，但我在死后也要继续保护他。$B$B撇开我的雄心壮志不谈，我必须表达我请求的理由。布莱特考坡弗神父引导我们穿越了过去的刺眼圣光，现在他正在帮助我们爬进阴影中。他视被遗忘者的需要高于一切，在死后表现出与生前相同的无私。$B$B这里以北矗立着洛丹伦残党军队的最后一个营地。我们的乖宝宝二等兵威廉走在他们中间。我们不能鼓起勇气杀了他。所以我请求你执行这项行动。众所周知，威廉从沙特里奇塔巡逻到营地入口。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41366, '纳格拉斯男爵和席瓦莱恩男爵是生活中的好朋友。由于他们对彼此的尊重和友谊，我也决定与席瓦莱恩城堡的主教保持密切联系。艾隆迈恩教长很快就成为了我最亲密的朋友。他是一个与众不同的人。$B$B有时候，我会离开格伦郡，只是为了听他的布道。他谈论圣光的方式和它给他带来的和平，让我感到作为一个神官感到自卑，甚至可能嫉妒。如果他看到我处于这种状态，他会感到羞愧。$B$B<布莱特考坡弗神父停顿了几秒钟。>$B$B我知道这听起来有点怪，$N，但我听到了他的灵魂的呼唤从现在已经腐化的堡垒里传来。鬼魂面临着不同类型的不死，与我们不同。虽然我在巫妖王的控制减弱后设法恢复了自己，但他将永远被困在时间的某个地方。甚至不知道他自己已经死了。$B请让我的朋友安息。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41367, '虽然唤醒纳拉雷克斯应该是您的主要目标，但您还需要做其他事情。$B$B穿过裂缝，尽管他们可能很滑，但科卡尔在蜿蜒裂隙的分支中找到了隐藏的路。当我们试图杀死那些在这次入侵者时，其中一个人声称哀嚎洞窟是他们与生俱来的权利。$B$B当然远非如此。科卡尔践踏了大地之母的爱，在他们认为合适的任何地方都只带来了毁灭！这个狂热的科卡尔半人马的名字是赞达拉·风蹄。$B虽然这听起来很激进，但我希望你把她的头给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41368, '我们做活人做不——呸！我厌倦了装作什么都没发生过！$B恭喜$N，你会听到实际上——多么——疲惫。这一定很刺激，对吧？对吧？！$B$B<巴兹尔深深地叹了口气.>$B$B我道歉，刚才似乎有什么东西在我的脑海中刺激了一下。你看，感觉有点忧郁。$B我曾经是现在被称为可怕的血色修道院的顶级铁匠。我记得我曾经在光明的祝福中锻造盔甲的日子。$B$B而现在，这些蛆虫甚至盯着我看，哪怕是提到我们以前的信仰。傻瓜，他们全都是。$B幸运的是，在邪恶的阿尔萨斯蹂躏整个城市的那天，我离开了修道院——现在我注定要在淤泥中锻造我的作品。太离谱了，我告诉你，太离谱了！$B我的徒弟达格海姆应该还活在军械库的某个地方。那个傻瓜可能拿着我在光锻锭上的日记——我想要它回来，即使你得从他冰冷的手指上撬开它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41369, '你身上散发出强大力量，陌生人。类似于在这座被诅咒的塔中缭绕的残余，在这片死寂的峡谷中若隐若现。感觉像是很久之前了，我们这座教堂的居民被指派保管一件遗物，这是汉瓦不久前为您修复的。它是一件强大神器的一部分，是自由魔法的管道。它以前由守护者本人使用，现在已经损坏-这是一种安全措施，以确保没有邪恶——像他曾经那样——滥用它来伤害艾泽拉斯。$B$B它的部件不仅散布在整个塔中，而且也散布在全世界。如果你能在旅途中得到它们，就把它们带到我这里来，我可能会把它们恢复到原来的形态。然而，为了实现这一点，需要大量的奥术能量。我不能离开这个地方，所以由你来给我带这样的东西。守护者之塔将是找到这些零件的适当所在。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41370, '我从你身上感觉到的——这种令人窒息的高温，如此大的压力，我几乎无法承受！你带着权杖头回来了，它渴望与它的其他部分重聚。让我们不要浪费时间，以免这些东西的力量太大而无法承受。$B$B在剩下的宇宙残骸的帮助下，我有能力将麦迪文权杖恢复到完整状态。然而，这只是表面的修复。如果没有注入守护者的本质，权杖就只是一个无用的小玩意，因为是守护者的触碰唤醒了它。除非我们找到一种方法将其与麦迪文调谐，否则将无法使用它。$B$B鉴于守护者已经不在，找到他这样的微小希望似乎是不可能的。拜托，你我必须找到它，否则权杖将永远不起作用。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41371, '权杖已经完成，然而......与我记忆中的不同。它看起来一模一样，但它的存在感很薄弱，几乎是空壳。虽然守护者的力量非常明显，但权杖本身内部无疑残留着外来能量。这种能量处于休眠状态，沉睡着，渴望被唤醒。$N，恐怕在我们把这魔法从权杖中释放出来之前，我们还没有结束。$B$B当我将注意力集中在这件古物上时，我认出了一些漂浮的石头，一片饱受折磨的土地，火从地面喷出。一个被翡翠般的火焰所征服的，迁徙的神秘种族。$B$N，请原谅我不够帮忙。为了驾驭权杖的外来魔法，我需要将它与我向你描述的那个时空的充能物品相协调。然而，我却无法看到你在哪里可以找到这样的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41372, '这种调和会占用我的一些时间和精力。如果您希望我开始，请告诉我一声。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41373, '上面的文字是用一种慢吞吞的地精俚语写的。当你在翻阅书页时，一些熟悉的食谱映入你的眼帘，但没有什么有趣的新菜谱。叹了口气，你翻到下一页，注意到一个缺失的页面。如果这本书没有就此结束，你不会介意这一页，但现在书被翻完了，你正在权衡各种可能性。$B$B当您决定合上这本书时，您会想到十几个假设。在它的背面，你可以认出“伟大的加斯蒂诺”这个名字——这本普通的书有什么了不起的地方？这个加斯蒂诺是谁，谁能告诉你更多？当好奇心深深扎根于你的脑海深处时，你想起了卡拉赞下层大厅里一位幽灵般的厨师。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41374, '正如您可能已经注意到的那样，加斯蒂诺的食谱书很常见。但它确实包含某种配方，可以让任何治疗者的注意力恢复活力。奇哉怪也，虽然牧师们承认了地精的贪婪野心，但他们还是忍不住对他留下的这个食谱感到感激。$B$B在某种程度上，我认为他们欣赏它的简便。因为它只不过是一份什锦沙拉。恐怕我不能背出配方，但我认为这个缺失的页面应该在墓穴的某个地方。这本书属于埋葬在那里的人。小心，我觉得时间对那个地方并不友好。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41375, '乍一看，这本书似乎是一本非常普通的书。然而，当你开始研究它的内容时，你很快发现它的外观更像是一本粗糙的日记，而不是一本专业写作的作品。从标题上看，它声称是一本研究书，但破旧的页面和潦草的文字似乎是通过一个孩子的手写成的。$B$B“虽然我张开双臂欢迎埃雷萨拉斯内部的古灵们和树人们的想法，但我的许多兄弟都认为这是不必要的。我们更习惯于奥术，在他们心目中，与这些魔法生物合作是德鲁伊的领域，他们使用与他们相似的魔法。然而，似乎随着时间的推移，这些神奇的树木的两种表现形式似乎都适应得相当好，有些树人甚至长出了蓝色调的叶子。$B$B当你眯起眼睛时，你可以在刚刚读到的文字下看到一个名字：莱德罗斯。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41376, '我确实认得这本日记。这是我以前留给托塞德林王子的东西。我们过去常常见面并讨论各种事情，不仅仅是他和我，还有大多数的博学们者。埃雷萨拉斯是一个知识之地。可悲的是，它只不过是过去的影子。感谢您带回这个。$B$B如果您有时间，我有一个请求。在检查这本书时，我发现最后一页上刻着一个不完整的字形。由于我们从未完成我们的研究，我必须请求您前往扭木区，击败在该地区游荡的受污染的树人。如果运气好的话，它们的叶子上可能仍然保留着曾经装饰它们的蓝色。如果你把这些叶子带到我这里来，我会用我们的调查结果来奖励你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41377, '现在，我需要一些时间来深入研究乌尔的教义。我必须确保没有一个重要的细节能逃过我的注意。这本书内容广泛，众所周知，乌尔会为那些头脑敏锐的人嵌入秘密信息。$B$B与此同时，我有一个任务要交给你。在这个世界上的睿智圣人中，很少有人拥有我们德鲁伊领袖范达尔·鹿盔的智慧和洞察力。他住在达纳苏斯。$B$B前往达纳苏斯，告诉他你的发现。他肯定会就这件强大的文物提供宝贵的建议。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41378, '艾露恩的奥秘是深奥的，即使是我用我所有的知识，有时也能发现它们难以理解。我不完全理解她为什么要把艾露恩之镰这样的神器托付给维琳德——是的，那是她的名字。然而，它召唤狼人的力量可能确实是解开其更深层次真相的关键。$B$B我长期以来一直在研究一种叫做晨光麦的特殊草药。有趣的是，我的研究表明，它可能有助于清除从卡拉赞时期附着在镰刀上的黑暗能量。但要激活晨光麦，需要一种有效的催化剂。所以，给我带来血——从以下各个部落收集的狼人的血液：从潜伏在卡拉赞最黑暗深处的，在吉尔尼斯城的废弃街道上徘徊的，躲在影牙城堡的阴影中的狼人。$B$B收集完之后，把它们带到我这里来。不要拖延。镰刀的力量必须由像我这样有能力的人来驾驭和理解。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41379, '一如既往，我是对的。多亏晨光麦，我成功地从你收集的狼人血液中清除了黑暗。现在，见证吧！$B$B<大德鲁伊范达尔·鹿盔伸出手，展示了一小瓶纯净的蓝色血液。>$B$B这对你来说可能并不多，但你眼前所看到的不仅证明了他们血统的力量，也证明了他们与艾露恩的联系。仔细看。你在他们的血液中注意到了吗？$B$B确实。像我们月亮井的水一样纯净。这就是他们在血魔法玷污他们的种族之前的样子。立即将此带给梦风。他会知道下一步该怎么做。$B$B而且，如果你觉得挥舞镰刀的负担对你疲惫的肩膀来说太重了......你知道在哪里找到我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41380, '现在，我需要一些时间来深入研究您的教义。我必须确保没有一个重要的细节能逃过我的注意。这本书内容广泛，众所周知，乌尔会为那些头脑敏锐的人嵌入秘密信息。$B$B与此同时，我有一个任务要交给你。在这个世界上的睿智圣人中，很少有人拥有我们德鲁伊领袖范达尔·鹿盔的智慧和洞察力。然而，我担心他可能不像我那样接受你的存在。$B$B然而，并不是所有的希望都破灭了。在你的牛头人盟友中，有一个人几乎和范德拉一样聪明。我说的是玛加萨·野性图腾。尽管她的部落偶尔不守规矩，但他们一直很尊敬艾露恩，他们称她为穆莎。$B$B据我所知，她现在住在伟大的城市雷霆崖。去那里寻求她的建议。也许她拥有连我都躲避的关于镰刀的知识。你的旅程远未结束，而恐怖图腾的智慧可能被证明是无价的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41381, '我听说过许多关于这种武器的故事，以及它所遭遇的邪恶命运。然而，并非一切都完了，因为我们或许能够将它从卡拉赞的黑暗中净化出来。$B$B最近，塞纳里奥议会的一些成员，尤其是那些最接近范达尔·鹿盔的人，已经开始积累大量的一种叫做晨光麦的草药。从大德鲁伊哈缪尔与我分享的内容来看，我相信这种草药可能是净化镰刀的关键。$B$B无论如何，要让它发挥作用，需要一个强大的催化剂。我们需要狼人的血液——从以下各个部落收集的狼人的血液：从潜伏在卡拉赞最黑暗深处的，在吉尔尼斯城的废弃街道上徘徊的，躲在影牙城堡的阴影中的狼人。$B$B收集他们的血液，把它带到我面前。我们也许能够一起净化镰刀，让它恢复它的真正目的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41382, '无论范达尔的走狗用晨光麦策划什么，都必须是真正非凡的......但我跑题了。血确实被洁净了。来，看看，孩子。$B$B<玛加萨·野性图腾伸出手，展示了一小瓶纯净的蓝色血液。>$B$B像月亮井的水一样纯净，像星星一样闪耀。毫无疑问，在这些孩子遭遇可怕的命运之前，他们是穆莎最喜欢的孩子。$B$B立即将此带回给梦风。他会想知道。$B$B并保持镰刀一直在你身边。塞纳里奥议会的一些成员可能不太高兴它掌握在你的手中。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41383, '在您不在期间，我深入研究了乌尔的教义，仔细检查了这本书中的每一段话、每一个字和每一个隐藏的含义。我发现的知识既有启发性，又令人深感不安。$B$B请稍等片刻，听听，年轻的$r。乌尔的著作中蕴含着深奥的智慧，但它也揭示了关于艾露恩之镰及其力量本质的严峻真相。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41384, '是时候打倒守护者纳尔穆恩了。我们世界的命运取决于它。他在卡拉赞的存在是不能容忍的祸害，他的计划必须在实现之前被挫败。自然本身的平衡岌岌可危。$B$B在寻找这本书的过程中，你已经冒险进入了卡拉赞的上层房间，所以你对迷宫般的走廊和阴暗的大厅很熟悉。未来的旅程不会一帆风顺，但您以前的经验将对您有所帮助。守护者纳尔穆恩已经将自己深深植根于卡拉赞的黑暗魔法的核心，从这个被诅咒的地方汲取力量来助长他的邪恶计划。$B$B但要小心，因为守护者纳尔穆恩不是普通的对手。他是一位拥有传奇力量的血法师，几个世纪以来一直涉足最黑暗的艺术。他对血魔法的控制是无与伦比的。单独面对他将是愚蠢的。命运女神在上,你将需要盟友，强大而勇敢的同伴，和他们一起你才有把握对抗黑暗的浪潮。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41385, '我的乌鸦低语着曾经笼罩在吉尔尼斯城街道上的黑暗存在。在遥远的大海对面，在黑暗与薄雾中，一位狼人血法师正在编织他邪恶的魔法。这种生物在已经动荡不安的土地上留下了不可磨灭的印记。细节很少，但有一点是肯定的：他经常与臭名昭著的吉尔尼斯摄政王哈鲁恩家族合谋。$B$B哈鲁恩是一个狡猾而无情的家庭。据说，他们会不惜一切代价与任何能够实现他们抱负的人结盟。血法师在他们身上发现了心甘情愿的帮凶，只要符合他们的需要，他们就会对他的黑暗做法视而不见。正是在他们阴暗的交易中，血法师计划的关键可能就在。$B$B如果我能离开海加尔的圣山，我会亲自前往吉尔尼斯。但是你，年轻人，有自由去我不能去的地方冒险。你的路很清晰，它通向吉尔尼斯城薄雾笼罩的街道。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41386, '在乌尔所写的古代传说中，人们低声说，仅仅说出普利克巫妖的名字就可以成为一座灯塔，将他的黑暗存在引向我们的位面。但要密切注意我，因为有一个计谋，一个狡猾的计划，要引诱他到我们的控制之下。$B$B拿着这个神秘的球体，这是很久以前的遗物，注入了原始魔法的精华。带着它，向西冒险前往古老的力量法阵，一个既原始又强大的能量枢纽。在那里，在低语的风和沙沙作响的树叶中，说着普利克巫妖的名字。$B$B但要小心，因为他的到来必须经过精心安排。一旦被召唤出来，我们将使用法阵的力量诱捕他，剥夺他的黑暗力量，使他变得脆弱。就在那时，在那虚弱的时刻，我们将出击，将他放逐回他来时的阴影中，并永远保护我们的位面免受他的恶意控制。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41387, '所以你走在我前面。当然是寻求战争艺术的指导-否则你为什么要寻找武器大师。您是众多希望学到武术专业知识的人之一，但您会成为极少数真正学成的人之一吗？我已经数不清有多少容天真单纯的战士认为自己值得我的教导，结果却在最简单的挑战中失败了。除非向我证明你的价值，否则我无法确定你是否适合即将发生的事情。$B$B在北面的高山上，有一片被玷污的森林，名叫费伍德。再往北，您会发现铁木山洞;从这个洞穴里有一根藤根，像铁一样冷，同样沉重，这就是我对你的要求。摘下根，安全地带到我这里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41388, '为我之前的傲慢道歉，但我必须确保你已经准备好走上战争之路。你可能在武术方面很有经验，但追随我的道路需要的不仅仅是你迄今为止所取得的成就。$B$B如前所述，许多雄心勃勃的人都曾站在你现在的位置上，但只有少数人成功了。从错误中学习很重要，无论是我们自己的错误还是他人的错误。与我以前的学生交谈，他们会分享失败的故事。只有当你真正了解他们的缺点时，你才能继续前进。与这个岛上的萨格斯和克兰诺克以及塔纳利斯的佳辉交谈。我听说沙漠的刺激吸引了他来到加基森。一旦你和他们聊完了，就回来回答我关于他们讲述的问题。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41389, '来，把玻璃弹珠带给萨格斯。它是你行为的证明，表明你和他现在势均力敌了。时刻保持警惕并记住您学到的内容。我很高兴见证您的进一步成长！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41390, '嘿你。碰巧要去西部荒野？军情七处对迪菲亚涉及西部荒野以外的独特阴谋方面有很大的了解。我们怀疑他们正在处理某种高度挥发性的化学物质，这种化学物质不仅可能对暴风城构成威胁，还会对东部王国的其他地区构成威胁。我们可以使用一些……“额外的力量”，因为这份工作很可能不是那种隐蔽的交易。$B$B我们的一位特工位于西部荒野通往暮色森林的桥上，靠近废弃的法师塔。我希望你去见她，而且要快点。突然发生了值得调查的事件。她叫吉尔妮;一旦你找到她，就按照她说的去做。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41391, '我已经监视这座塔很长一段时间了，它周围发生的任何事情都诡异莫测。迪菲亚在这里很少，但肯定装备精良。仅此一项就足够令人担忧了，但最让我困惑的是那些在周围巡逻的僵尸。每隔一段时间，一些迪菲亚就会进入塔楼;但这些僵尸并没有再次离开，而是以一张全新的丑陋面孔在周围出现。$B$B我想进一步调查这座塔的内部阴谋，但我正在等待军情七处的增援。您来这里的目的相当简单，但更为关键。在塔附近的码头上，我注意到一个阴暗的地精停泊着她装满板条箱的划艇。当然是某种交付，但我们需要的是文件，最好是带有参与这些操作的人员的姓名。随你喜欢的方式对付她，并把任何有价值的信息直接带回给军情七处总部的雷吉克。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41392, '杰里德·维斯是威廉·维斯的儿子，威廉·维斯是一位技术娴熟且受过良好教育的炼金术士。他的父亲在老城区开了一家炼金术店，受到许多人的喜爱。当暴风城第二次被烧毁时，他家的房子也被烧成了灰烬。在石匠公会重建期间，维斯自然而然地认为他的房子要修复，因为他是暴风城最著名的炼金术士。讽刺的是，这事没成。$B$B暴风城的贵族们有不同的城市重建计划，最终，维斯和他的家人无家可归。他心中仇恨越来越强烈，他谴责了那些抛弃他们的人。我们假设维斯在去世前把他的儿子送到了石匠那里，石匠和他一样对暴风城不满。看来杰里德在仇恨和能力上都继承了他父亲。$B$B$N，维斯家不能再这样继续了。根据你带来的名单，他住在死亡矿井。清算他，给我拿他最新炼制的样品来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41393, '你有钢铁般的意志。你从过去的错误中汲取智慧。现在向我展示你所拥有的力量。$B$B在遥远的东方，在赤脊山脉以北的燃烧平原上，一个蓄势待发的巨人正在沉睡，他的力量无与伦比。搜查北方的山区，杀死那凶猛的野兽，把它燃烧的眼睛带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41394, '随着普利克巫妖们挥之不去的阴影逝去，他们的影响力逐渐减弱，现在是我们握紧艾露恩之镰的时候了。然而，这样的壮举并非易事，因为编织在其本质中的黑暗魔法已根深蒂固。$B$B年轻人，请紧紧聚集起来，听我的话。要开始净化过程，我们需要六个永恒梦境碎片和二十块月布。这些碎片将构成我们努力的基石，作为流经它们的净化能量的管道。$B$B但通往纯洁的道路充满了危险，因为侵扰镰刀的黑暗魔法渴望再次释放到世界上。为了遏制如此强大的力量，我们必须塑造一个具有无与伦比的力量的容器——一个强大恶魔的灵魂。在虚空的某一层中，传来了一位名叫孟菲斯托斯的恐惧领主的低语。$B$B冒险进入虚空深处，寻找孟菲斯托斯灵魂的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41396, '$N，请稍等片刻。就在刚才，我感觉到一股能量从爷爷的灵魂碎片中涌出。一种温馨的温暖，我错过了几千年。不过，这还不是全部。这很难理解，但我觉得伟大的玛洛恩正在努力与我们交流——与您交流。我能感受到他在身边的紧迫感。这不可能是任何其他方式：玛洛恩希望将他的祝福放在你身上，我确信这一点。$B$B要得到爷爷的祝福，你必须和我一样与翡翠梦保持一致。然而，让自己与伊瑟拉的领域保持一致是一项只有经验丰富的德鲁伊在经过多年冥想后才能成功完成的任务。然而，还有另一种方法。为此，需要做好准备。$N，帮助我，我会为你获得梦境铺平道路。$B$B首先，我们需要一个由梦境皮革和梦境丝线编织而成的梦境帷幕。此外，翠绿蘑菇，浸透着梦之能量。在菲拉斯的加德米尔湖找到这些。最后，给我带来大量的昏睡药水。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41397, '凭借绿龙的古老能力梦境视觉的馈赠，您或许能够透过梦境的帷幕直接与祖父交流。在绿龙军团中，曾经有一位善良的典范维特库斯，他特别喜欢凡人种族。他被称为永恒沉睡者，进入了无休止的冥想，最终离开了自己的肉体，然后将他的灵魂锚定在梦中。你需要与他谈谈。找到他的身体，点燃我用剩下的蘑菇制作的这炷香，应该可以让你召唤他的灵魂。$B$B我上次见到维特库斯是在分裂之前，所以我不知道他的身体在当今时代在哪里。然而，树林里低语着一个名字——瑟拉丹。寻找这个地方，我确信你会找到维特库斯。别忘了戴上梦境帷幕！它的保护可能并不强大，但应该足以满足您与维特库斯的对话。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41398, '是时候了，朋友。现在你能够凝视梦境本身，你可以向我的祖父表示敬意——并接受他想加在你身上的恩惠。当你走的时候，我把玛洛恩的灵魂碎片还给了他。他再次完整了，尽管仍然很虚弱。他费了很大劲才告诉我他打算去见你的地方。我恳求你，不要让他等待。我们可能已经削弱了梦魇的影响力，但这样一股力量不太可能那么容易地放弃它的猎物。$B$B$N，你可以感到自豪，因为您的行为和对这个世界平衡的承诺是非凡的。成为守卫者祝福的对象是一种无与伦比的荣誉。现在冒险进入大洋对面的黎明森林。凝视石坡道上的梦见宝石，沐浴在白鹿灿烂的优雅中吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41399, '许多英雄在上次战争中倒下，许多人死于天灾军团之手。从倒下的尸体上，盔甲被剥去并带回纳克萨玛斯，用于未知目的。$B$B在这些物品中，不知何故可以找到梦行者之戒。你必须把它还给我，以确保它没有被损坏。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41400, '你已经有了怒风的套装，$C。我能在你身上感觉到自然本身，但它似乎相当朦胧。也许您现有的那些不适合您当前渴望的天赋。$B$B<卡祖德哼了几秒钟.>$B$B然后把它放在这里，告诉我，你真正面对了你的内心了吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
