INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41416, '我不做任何伪装，蛆虫。瘟疫之心所拥有的黑暗很可能会毁掉我们俩。这就是价格如此之高的原因。如果我要死，那会像个有钱人一样。$B$B我不在乎你是怎么死的，只在乎你按照我的要求去做。把戒指给我，我们俩都会受益——或者两个一起死;但我已经解释过了......') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41417, '你穿上了复仇的套装，$C。我能感觉到黑暗在你周围若隐若现，但似乎相当暗淡。也许你现有的不适合您当前渴望的天赋。$B$B<梅鲁斯哼唱了几秒钟。>$B$B把它递给我，告诉我，恶魔会闲聊吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
