INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41433, '在你与纳克萨马斯的天灾军团的战斗中，如果你遇到了无畏之戒，把它还给我，我会用更适合你的东西来换它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
