INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41450, '<蒙托尔神父在你面前的空中做了一些奇怪的手势。>$B$B有福的孩子，在寻找阵亡者的法衣时，你也可能遇到信仰之戒。然而，我觉得它现在对你来说可能没有多大用处。$B$B如果你找到了它，把它还给我，我会确保它对你有用。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41451, '你穿上了卓越的衣服，$C。我能感觉到它的光芒，但似乎相当昏暗。也许您携带的那些不适合您当前渴望的天赋。$B$B<梅鲁斯哼哼作响了几秒钟.>$B$B把它交给这里，告诉我，这是你寻找的影子吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
