INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41467, '作为观察者，我被允许访问麦迪文的许多个人物品。在这些项目中，我发现这些巨著最有启发性。虽然大多数书都装满了——坦率地说——废话，但也有一些瑰宝。其中一本巨著记录了一套适合大法师的护甲的创造：霜火。$B$B<安吉拉指着她的头>$B$B你也许能找到一枚带有这个名字的戒指，如果它不适合你的能力——根据我所掌握的知识，我们可以为你重新塑造它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41468, '你穿着灵风的衣服，$C。我能感觉到它的神秘力量，但似乎相当暗淡。也许您携带的那些不适合您当前渴望的天赋。$B$B<梅鲁斯哼唱了几秒钟.>$B$B把它交给我，告诉我，你是寻求秩序还是混乱？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41469, '你穿着灵风的衣服，$C。我能感觉到它的神秘力量，但似乎相当暗淡。也许您携带的那些不适合您当前渴望的天赋。$B$B<梅鲁斯哼唱了几秒钟.>$B$B把它交给我，告诉我，你是寻求秩序还是混乱？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
