INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41484, '你会在纳克萨马斯领主的尸体上找到我们阵亡英雄的遗物。如果它们不适合您的需求，请将那些被亵渎的纪念品带到我这里，我会提供替代方案。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
