INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41515, '你已经有了大地之怒的衣服，$C。我能感觉到元素的意志和你的力量，但它似乎相当黯淡。也许您携带的那个不适合您当前渴望的天赋。$B$B<卡祖德哼唱了几秒钟.>$B$B把它交给我，告诉我，这些元素应该如何帮助你？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41516, '你已经有了大地之怒的衣服，$C。我能感觉到元素的意志和你的力量，但它似乎相当黯淡。也许您携带的那个不适合您当前渴望的天赋。$B$B<卡祖德哼唱了几秒钟.>$B$B把它交给我，告诉我，这些元素应该如何帮助你？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41517, '你愿意把那些为保卫这片土地而倒下的人的盔甲归还给我吗？$B$B在你跨越许多困难后，你最终会找到它，碎地者之戒。有了它，你的套装就会完整。$B$B它可能不是为了围绕您的技能的使用而专门制造的，请不要担心。还给我，我会帮你改制。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41518, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41519, '<这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅试图通过翻阅概览就会让你感到畏惧。谁能想到，用法杖打斗这么简单的事情，竟然能写满整本书？最引起您兴趣的是关于熊猫人的简短部分，熊猫人是来自大洋彼岸的一个像熊一样的类人生物的神秘种族。显然，他们以无与伦比的大师级战斗能力而闻名。出于好奇，你决定把这本书带给诺拉。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41520, '塞拉摩士兵经常来拜访我们，他们常常提起这个故事。想象一下：在那场围攻中，那些站在吉安娜和萨尔新部落那方的人有一个非凡的盟友——熊猫酒仙陈·风暴烈酒。他战斗时豪情万丈、技艺精湛，让人仿佛在目睹一股兼具力量与精准的旋风！陈对他那根酒仙杖的掌控堪称传奇。但是，听着——战斗结束后，那家伙把他的酒仙杖插在地上，然后就消失在地平线上了。你敢信？据说那场战斗太过残酷激烈，以至于他再不忍回忆起此事。现在，我不是说这个故事一定是真的，但如果它是真的，如果我们能找到那根熊猫人的法杖，光明之心大师一定会欣喜若狂的！想象一下，从它的设计和构造上我们能学到多少东西。这完全可以彻底改变我们对武器工艺的理解！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41521, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41522, '这部厚重的巨著见证了马迪亚斯大师对战争艺术坚定不移的奉献。仅仅翻翻书页就能留下令人敬畏的印象，书中展示了对阿曼尼巨魔的细致描述，挥舞各种投掷武器的技术，以及投掷手套的复杂艺术。然而，仅仅了解历史并不等于精通。既然你必须把书还给诺拉，也许她能帮助你实际应用书中的教义。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41523, '光明之心大师对阿曼尼巨魔制作的一套奇特的投掷斧头表现出了浓厚的兴趣。遗憾的是，自从阿尔萨斯洗劫了奎尔萨拉斯之后，来自祖阿曼的消息就很少了，没有一个头脑正常的商人冒险去那里与阿曼尼人进行贸易。这些斧头在战前就很罕见；现在，它们几乎是遥不可及的。然而，还是有一线希望的。这些斧头通常由高级阿曼尼酋长使用。其中一个首领，战争大师沃恩，忠于旧部落而不是祖尔金。有传言说他拥有这些令人垂涎的武器，尽管他不太可能愿意放弃它们。如果你成功地获得了他们，把他们交给光明之心大师。他一定会为您提供进一步的指导！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41524, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41525, '这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。这本书大部分时间都在自相矛盾，因为它声称枪既有用又有缺陷。虽然它的破坏力得到了充分的考虑，但它的噪音和对粉尘的要求是一个相当大的缺点。作为一名研究人员，诺拉可能会提供更多的见解。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41526, '说实话，我很困惑。的确，枪很响，但仍然有效，但人们如何接受这一点，并愿意使用它们？我们必须看到有人在行动中使用它，也许它会激励你也使用它们。$B$B我所持有的信息清楚地说明了寻找枪支使用者的最合乎逻辑的地方-黑石深渊，它拥有黑铁矮人的资本。肯定有至少一个持枪的人，但为了不让你们盲目进去我知道你们要追捕的人的名字。前往黑石深渊，找到并杀死训犬者格雷布玛尔，如果你碰巧找到一些黑石粉，请返回给主人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41527, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41528, '这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。可以从中推测出弩的发明和改进的详细历史，但你觉得它的真正本质和联系都逃避了你。不管怎样，你都需要把书还给这个诺拉，也许她能帮助你更好地理解它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41529, '你可能已经在书中读过了，但是书中有整整三个章节专门讲述了威利家族的成就和他们在弓弩开发方面的突破。在近代史上没有其他制造商像他们那样完善了弓弩的制造。他们曾为洛丹伦国王泰瑞纳斯二世服务，后来成为他儿子十字军东征的牺牲品，很快就被遗忘了。几代人的遗产，顷刻间化为乌有。至少我们是这么认为的——随着猩红十字军的兴起，威利这个名字再次出现了。现在，他是这个狂热组织中的一名将军，指挥他们的炮兵；利用前人无数代人的知识。马迪亚斯大师对他家的一把弩很感兴趣，但一直没有找到找到一把的方法——直到现在。威利控制着血色堡垒对抗斯坦索姆的不死族。寻找他的军械库，找到威利的家传弩。；一旦拿到了，直接拿给马迪亚斯！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41530, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41531, '这本厚重的书证明了马赛厄斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。暗夜精灵几个世纪以来的射箭宣言，阿拉希弓箭的早期制作和赞达拉巨魔使用的奇怪技术只是这些页面中包含的智慧的一小部分。感到不知所措，你想知道诺拉·萨格斯提到的这一点是否能帮助你充分利用它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41532, '我读到过一种古老的弓，一种早已被遗忘的武器。它可以追溯到大分裂之前！一种特定类型的上层精灵弓，它迫使持用者适应一种特定的技术，否则它将无法正确发射箭！似乎那个时代的弓箭手用这种方法达到了令人难以置信的速度和准确度——这正是大师所追求的。我给大师安排了一节课，至于你能不能上手，就看你自己了。但是一件上层精灵武器……卡利姆多到处都是他们的废墟，其中最大的是厄运之槌废墟。我觉得这是你最好的选择。祝你好运，热心的学生。如果你成功了，请直接把弓带给马迪亚斯大师！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41533, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41534, '这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。长柄武器被描述为有效和强大。由于它们的长柄，持用者可以在没有直接近身格斗的情况下进行攻击。据说人类军队在与兽人的战斗中更喜欢使用它们，因为它们的大小不同。你觉得这种武器没有得到应有的尊重，所以你找诺拉学习更多。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41535, '我相信我能理解你的感受。也许事实上长柄武器并没有得到应有的尊重，因为其他战士会认为这是最后的选择。但这是一个喜好和技巧的问题。马赛厄斯说每种武器都有它的用途它的力量来自于它的使用者。我在塔纳里斯的朋友给我捎了个信。似乎当地的龙族已经向冒险者开放了洞穴，试图将他们送到时空之外。你看，我这个朋友很爱说长道短。有传言说，有一只高个子龙拿着一支长矛，手里拿着一根牙签。似乎这个叫做克罗纳的生物在一次私人恶作剧冒险中被人类刺伤后声称拥有这把武器。请原谅我的冷漠，但我对时间旅行魔法和任何包含它的东西都没有浓厚的兴趣。去那里看看编年史是怎么使用它的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41536, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41537, '这本厚重的书证明了马赛厄斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。它描述了达隆郡之战以及一个决定了这场战役命运的天灾军团首领。这本书描述了他的行为是邪恶和残酷的，但没有错过描述黑衣玛杜克使用的剑的机会。对这样一个怪物的崇拜让你感到困惑，当你走向诺拉的时候，你血管里的血液开始沸腾。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41538, '我们对达隆郡战役知之甚少。毕竟，只有少数人幸存下来。有传言说天灾军团的军阀腐化了一个人类的灵魂，而这个灵魂反过来又终结了所有保护者的努力。无论你走到哪里，故事都不一样。所以这不是我们的重点。玛杜克拥有其他死亡骑士所拥有的，符文之刃。一个被天灾军团的堕落所扭曲和变得黑暗的，哀伤之刃。我们怎么知道的？嗯，你可以看到他在战斗中大胆地呼喊它的名字。你的任务是找到他，把剑还给我们研究。最后我们知道的是，他又回到了通灵学院——尽管是作为教师。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41539, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41540, '这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。书中提到了锤子在矮人文化中的重要性。虽然你看不懂大部分内容，但这本书以一个传奇结尾。据说，矮人过去常常通过向空中投掷锤子来占领丘陵和山脉，锤子落地的地方就是他们的新家。被这个传说所吸引，你找到了诺拉。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41541, '并非所有的矮人都值得钦佩，因此有些人缺乏荣誉和道德。虽然这么说别人让我很痛苦，但黑铁已经赢得了一个让大多数人觉得无可救药的名声。只有未来才能知道这是真的还是假的——那么，明天的问题。为了满足他们主人的意愿，黑石山的矮人召唤了他们的黄昏盟友，在他们的土地东边挖了一个采石场。一个叫巴古·黑锤的卑鄙小人监督着那里的工作。有传言说他有一把叫做断指者的锤子，因为他用它来打断那些没有达到配额的人的手指。你要打断他的骨头，找回那把锤子。虽然我通常不希望别人落得这样的下场，但那个人活该。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41542, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41543, '这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。兽人部落对斧头之爱的研究。在书中，一个名字被多次称颂。被字里行间所描绘的深深的敬意所淹没，你发现自己急切地走向诺拉，这样你就可以了解更多。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41544, '对许多人来说是邪恶的敌人，对一些人来说是酋长，对少数人来说是战友。这只是对地狱咆哮格罗玛什的描述的开始。马迪亚斯四处旅行，穿过联盟和部落都能通行的城镇，有时他会听到格罗姆的故事，对他的人民来说，他既是瘟疫又是英雄。纵观这个半兽人的过去和行为，只有一个事实凌驾于所有其他事实之上——他是一个天生的战士。即使是那些一听到他的名字就会吐唾沫的人也不会羞于承认他的战斗技巧。把你的脚挺直，$N，准备好你的敬意——带着一点泥土作为你旅行的证明。带着这样的礼物，你会得到主人一段时间的关注。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41545, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41546, '这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。你开始意识到你一直都带着武器。自从艾泽拉斯第一个种族的黎明开始，进化本身就开始于拳头。不然它们是如何生存和适应的？你羡慕地盯着你的拳头——如果你就是武器，你就不需要武器。你准备好和诺拉谈谈你对拳头的新欣赏了吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41547, '让我给你讲个故事。一个叫艾斯卡达尔的夜刃豹的故事，他在菲拉斯的土地上打猎。这是一种声望很高的野兽，它能在几秒钟内抓住所有的敌人。但就像所有的生物一样，死亡随之而来。当这头野兽结束生命的时候，它被撕成碎片用作物品。相信你可以在这个广阔的世界的某个地方找到它的手套，也许可以借用它的前主人的力量。我相信，找到它的坟墓并对它表示敬意，可能会让你从我们自己的世界之外获得它的恩惠——当然，如果你相信这类事情的话。它落在菲拉斯的左侧孪生巨像附近。暗夜精灵说，当它死去的时候，它的血滋养了一棵垂死的树苗，这棵树苗现在就长在那里。寻找它，也许你会有所收获。之后再回到马迪亚斯。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41548, '现在告诉我：被大师证明有价值是什么感觉？当他选我做他的徒弟时，这是我一生中最大的荣幸，你肯定也有同样的感觉。如果大师愿意与你分享他的知识，我可以帮助你——当然，这是有代价的。他可能是仁慈的，但没有愚蠢到去做慈善，你也必须贡献你的那份价值。隐藏在艾泽拉斯最危险的地方，你会发现那些来自远古时代的文本，包含着早已被遗忘的教义。找到他们，用你的一点金币，我可以让你走上正确的道路，为你解锁新的战斗策略。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41549, '这本厚重的书证明了马迪亚斯大师对战争艺术的严谨奉献。仅仅通过翻页来获得概述会让你感到畏惧。这本书的大部分内容都是围绕着匕首的不同形状和长度，以及招架和刺杀技巧展开的，但书中的大部分内容都是关于解剖学的：重要器官、肌肉群、肌腱和动脉的位置。同样的好奇和不知所措，你决定和这个诺拉谈谈马迪亚斯大师的作品，希望能更多地了解它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41550, '一段时间以来，我们一直在关注一套奇特的匕首。大多数人会认为它们是刀，但在我们老师这样受过教育的人看来，它们是无声谋杀的致命武器。它们属于一个叫戴米安的人，尽管他通常被称为开膛手。他的过去披着血淋淋的帘子，是一个没有道德的怪物。然而，即使像他这样的怪物也有它的目的。戴米安被关押在暴风地窖里，这是一座位于同名城市内的高级监狱。我们听说它的主人因为某种超自然的干预而逃脱了；让他在任何活着的人身上追求自己的欲望。$N,冒险进去，把那把戴米安的手术刀套交给马迪亚斯。照做，我保证他会指导你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41551, '很高兴看到你回来，我的学生。我的老学生很少回到他们的老师那里重新学习他们已经根深蒂固的东西。但我不能怪你。一个人的头脑只有这么大的空间，像你这样年轻的人去体验其他地方是很自然的。现在，我们继续吧？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41552, '齐格伦的脸上浮现出喜悦的表情，至少你可以猜测，这是一种喜悦。他的手势表明他想让你跪在他面前，就像你已经跪过很多次一样。远古的土人渴望再次成为你的导师。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41553, '听着，听着！一个独特的比赛在繁忙的棘齿城展开！任何对精美麦酒、烈酒和黑啤酒的鉴赏家都不应错过这个无与伦比的机会。带上你的酒友，来帮忙酿造整个艾泽拉斯最完美的酒精饮品！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41554, '听着，听着！一个独特的比赛在繁忙的棘齿城展开！任何对精美麦酒、烈酒和黑啤酒的鉴赏家都不应错过这个无与伦比的机会。带上你的酒友，来帮忙酿造整个艾泽拉斯最完美的酒精饮品！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41555, '我一生的目标是创造出艾泽拉斯最烈、最劲的饮品：角牙酿！它浓郁的风味和独特的口感将让任何享受其泡沫和苦味的人着迷。前提是我能将配方调制成功。我不想承认，但我之前的尝试总是不成功。我缺少一些能真正将所有原料结合在一起的东西。我只需要找出它是什么！这就是我来棘齿城的原因，收集关于那缺失的成分的各种传闻和故事。$B$B显然，剃刀沼泽当地的野猪人在酿造他们自己的酒。谁能想到这些原始的野猪人能够自己酿造烈酒？我需要找出这个烈酒的真相，它是如何制作的，是否有我正在寻找的秘密成分！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41556, '我想我对这个烈酒的制作有了很好的理解。它与我之前用石南草酿造的酒不太一样，然而，他们一定使用了不同的方法。也许他们使用了更高的温度...? 是的，这一定是！在酿造石南草时使用更高的温度可以将苦味减少到令人愉悦的程度。但我仍然不知道他们是如何实现如此强烈的火焰的。他们一定使用了魔法。由于我没有魔法手段，我们必须寻找其他东西。这个世界的元素有时会留下他们本质的一丝火花。这样的一种东西可以潜在地将火焰加热到所需的水平。$N，出去从任何火元素那里带回一些元素火焰 - 我们需要它来助燃！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41557, '那边的索尔登刚刚喋喋不休地谈论发现了关于东部王国洛丹伦酒的突破性发现。我不能让这个小家伙在我面前占便宜，这就是为什么我们要更上一层楼！虽然他对自己那糟糕而乏味的洛丹伦酒感到满意，但我们的目标是神秘的血色甜酒，这是一种极少有人机会品尝的酒，据说是个传奇。$B$B我听说这是一种圣光驱动饮料，是血色十字军的一种烹饪特产，在提瑞斯法林地的修道院里酿造。如果这种酒真的有这些神奇的特性，那我需要得到它！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41558, '银松森林拥有独特的植被，能够在山区和恶劣的环境中生长。它们的风味表面上看似苦涩，因此很少被不成熟的酿酒者使用。然而，我们可以充分利用这种植物。它可能没有复制血色甜酒热辣感觉所需的特性，但结合野猪人的酿造技术，我们或许能够提炼出独特的风味，供我们的酿酒使用。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41559, '找到一种味道辛辣火热的植物可能很困难。我在酿酒冒险中遇到的许多植物都有一定的香料味，但没有一种能达到血色甜酒的水平。幸运的是，我从码头的地精那里听到了一些传言；你会惊讶于这里贸易的繁荣，他们能听到多少故事。$B$B在东部王国，荒芜之地上生长着一种鲜艳的红色蛇麻草。显然，当地的食人魔会抓起这些蛇麻草的团块并咀嚼它们——生嚼！每当我不得不与这些大块头打交道时，他们总能让我感到惊讶。把它们的蛇麻草抢过来，带给我，我们会更好地利用它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41560, '让我们尝试一些非常规的方法。没有同样确切的配方，重现血色甜酒的热度将是一项挑战，但我相信我们可以尝试一些不同的东西。灼热峡谷是一个灼热的沙漠，几乎没有植被。尽管如此，一些植物似乎在火山土壤上生长得很出色——其中之一就是黑色蛇麻草。我推测蛇麻草从加热的土壤中吸收营养，自然赋予它们一种烟熏香料的风味。找到它的最好方法是亲自去抓一些来试试！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41561, '好的，$N。我们距离完善配方非常接近，我能感觉到！我们有银色蛇麻草，带着浓重的泥土苦味，还有红色和黑色蛇麻草的香料和烟熏质感，以及将其蒸馏成清晰而辛辣饮品所需的热度和技术！我们只需要那甜美的后味来完成这个组合；我知道完美的来源！$B$B在菲拉斯茂盛的荒野中，隐藏着厄运之槌的可怕废墟。在它那被诅咒的花园里，生长着一种根，我相信他们称之为洛恩塔姆地薯。这种薯块被认为具有强烈的甜味，即使在高温下烹饪也能存活。我们需要这个根来完成角牙珍藏！我们距离不朽只一步之遥，$N。不要浪费时间！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41562, '我一生的目标是创造出最强烈、美味和香醇的饮品，誉满艾泽拉斯：雷酒金啤！它那丰富的风味和独特的质感将吸引任何沉醉于其泡沫和苦味的人。至少我希望如此，但我之前的尝试总是以不同的方式失败。总有一些东西缺失，无法将所有的成分结合在一起。我只需要找出是什么！这就是我来棘齿城的原因，铁炉堡那些笨蛋们只会胡言乱语，根本看不出伟大是什么，直到伟大咬了他们的屁股！$B$B要酿造出真正美味的啤酒，需要多种不同类型的蛇麻草。由于常见的蛇麻草变种没有我渴望的强烈风味，我需要寻找一些不寻常的东西。我听说南方的野猪人擅长酿造艺术，他们一定有自己的蛇麻草！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41563, '酸味是每种啤酒都需要的一种味道，有些多一些，有些少一些。洛丹伦啤酒就是前者，你不会找到比这种美酒更酸的酒。个人来说，我不喜欢这种饮品，但我能欣赏不同文化所创造的多样性……即使人类酿造酒的方式只是小孩子的把戏。哈！$B$B不过，我们仍然可以同样利用他们的资源。在希尔斯布莱德的东南山丘上，生长着希尔斯布莱德蛇麻草，这是一种真正独特的蛇麻草，具有整个东部王国最浓烈的酸味。我需要这些作为我新的酿造尝试！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41564, '我可能是一个骄傲的铁炉堡矮人，但即使我也必须承认我们的蛮锤兄弟所酿造的精美麦酒和烈酒。我很少有机会享用如此极其苦涩的浓烈麦酒。仅仅一口就让我失去了平衡，真是一种无与伦比的体验！这种苦涩必须出现在我完美的麦酒中，必须如此！我一个好朋友告诉我，最苦的蛇麻草生长在辛特兰，距离鹰巢山不远。没有这种强烈的苦味，我的酿造无法完成。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41565, '你可能已经察觉到了，但那边的这个业余兽人认为他能酿出比我们矮人更好的饮品。依我看，这是个傻瓜的差事。但我并不是傻瓜，所以我们必须确保他的野心以失败告终。$B$B我无意中听到他兴奋地宣布要用元素火焰来点燃他的蒸馏火，所以我们自己也要利用元素。似乎这才公平，不是吗？我已经开始酿造你给我的蛇麻草，但它们并没有很好地融合在一起。元素之水或许正是解决这个问题的办法——而且，它可能甚至给饮品增添一丝额外的刺激！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41566, '我碰到了一个……可以说是“小”问题，关于我现在的饮品。将三种蛇麻草混合在一起是个绝妙的主意，但浓烈蛇麻草的苦味压倒了其他所有味道！如果我们保持蒸馏物不变，我不如就用浓郁蛇麻草酿造。幸运的是，我在港口听到一个传言，或许这正是解决我们问题的办法。金棘酒是一种应该非常苦涩的饮品，但它的味道却意外地顺滑柔和，正是完美的下午饮品！我怀疑那秘密成分就是金棘本身。有了几根根茎，我就可以测试我的理论是否成立。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41567, '$N！这是个灾难！我刚刚检查我的帐篷，寻找更多的材料，却发现我的“雷酒金啤”计划不见了！这一定是该死的霍尔雷·黑须，他和他的家族已经和我们家族是死敌，已经很多年了。他们无法接受我们的啤酒是优于他们那温吞的烂泥汤的事实。我们必须把它找回来。这个配方包含了完成我完美饮品的最后几个关键步骤。黑须肯定逃回了黑石深渊，找到他，给我把我的计划找回来！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41568, '我们有了蛇麻草、我们的魔法成分和金棘草来减少一切的苦味。拿回我的计划后，只剩下一件事情来完成“雷酒金啤”：金色蛇麻草。$B$B一种神话般的成分，许多矮人认为这不过是铁炉堡酒馆里醉汉讲的童话。但我知道得更清楚——我见过它！它在我喝空十桶啤酒后出现在我的梦中。一只金色的兔子，闪闪发光，宛如你见过的最上等的啤酒。它就在那里，在一片沙漠中那些巨大的骨骼间神秘地站着，仿佛一个预兆。然而我知道这真正的意义。它在召唤我去寻找它；去用金色蛇麻草创造金啤！无论它在哪里，找到这只兔子，金色蛇麻草就会是我们的！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41569, '喂，我跟你说，没有什么比不停地喝啤酒然后融入节日的节奏更令人振奋的了。来，抓起你的酒杯，开始扭动你的臀部！我想看到你完全喝醉，和这里的每个人一起跳舞。干杯！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41570, '喂，我跟你说，没有什么比不停地喝啤酒然后融入节日的节奏更令人振奋的了。来，抓起你的酒杯，开始扭动你的臀部！我想看到你完全喝醉，和这里的每个人一起跳舞。干杯！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41571, '喂，我跟你说，没有什么比不停地喝啤酒然后融入节日的节奏更令人振奋的了。来，抓起你的酒杯，开始扭动你的臀部！我想看到你完全喝醉，和这里的每个人一起跳舞。干杯！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41572, '哦，我的天哪！你想这样去见守卫吗？大胆，我必须说，但也许有点太大胆了。看在对时尚的热爱上，我不能让你穿着这身破衣服登上塔顶。虽然听起来很残酷，但这是事实！我一看你戴的头饰就浑身起鸡皮疙瘩。策划这场暴行的人应该受到审判。我可以帮你，帮你设计一个新的，更时尚的——如果你帮我处理一些我自己的用品。我们成交了？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41573, '哦，我的天哪！你想这样去见卫兵吗？大胆，我必须说，但也许有点太大胆了。看在对时尚的热爱上，我不能让你穿着这身破衣服登上塔顶。虽然听起来很残酷，但这是事实！光看你穿在身上的那条护腿，我就浑身起鸡皮疙瘩。策划这场暴行的人应该受到审判。我可以帮你，帮你设计一个新的，更时尚的——如果你帮我处理一些我自己的用品。我们成交了？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41574, '哦，我的天哪！你想这样去见卫兵吗？大胆，我必须说，但也许有点太大胆了。看在对时尚的热爱上，我不能让你穿着这身破衣服登上塔顶。虽然听起来很残酷，但这是事实！光看你穿的这些破布，我就浑身起鸡皮疙瘩。策划这场暴行的人应该受到审判。我可以帮你，帮你设计一个新的，更时尚的——如果你帮我处理一些我自己的用品。我们成交了？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41575, '哦，我的天哪！你想这样去见卫兵吗？大胆，我必须说，但也许有点太大胆了。看在对时尚的热爱上，我不能让你穿着这身破衣服登上塔顶。虽然听起来很残酷，但这是事实！光看你穿的那件胸衣，我就浑身起鸡皮疙瘩。策划这场暴行的人应该受到审判。我可以帮你，帮你设计一个新的，更时尚的——如果你帮我处理一些我自己的用品。我们成交了？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41576, '哦，我的天哪！你想这样去见卫兵吗？大胆，我必须说，但也许有点太大胆了。看在对时尚的热爱上，我不能让你穿着这身破衣服登上塔顶。虽然听起来很残酷，但这是事实！你披在身上的斗篷让我浑身起鸡皮疙瘩。策划这场暴行的人应该受到审判。我可以帮你，帮你设计一个新的，更时尚的——如果你帮我处理一些我自己的用品。我们成交了？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41577, '在你的手中，是荒芜巨岩的统治者，恐怖魔王孟菲斯托斯仍然在跳动的心脏。你和你的远征军挫败了他利用卡拉赞作为再次入侵艾泽拉斯的入口的计划。被永远驱逐到黑暗的彼方，这就是那个邪恶阴谋家的全部遗存了。为了万无一失，你应该把它交给能彻底清除它生命的人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41578, '这顶王冠上有艾泽拉斯王国的标志，与莱恩国王曾经戴过的王冠非常相似。也许即使在他疯狂的时候，麦迪文仍然把他的朋友放在心里。断裂，几乎坍塌——就像卡拉赞塔一样，一个失落的历史守夜。正是在这段历史的基础上，我们可以重新塑造一些东西。把我需要的材料拿来，我保证这顶王冠对它的新主人有用。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41579, '我猜你的旅程中对扭曲虚空和外域的短暂一瞥不是没有麻烦的。然而，我感觉到你拥有的一件物品带有超凡脱俗的气息。让我看看这件斗篷吧。嗯，据我所知，你面对的敌人确实很强大——也许强大到可以在不同的平面之间转换。不管;虽然它的前主人已经去世，但它的一些魔力仍然存在。如果你能给我所需要的材料，我也许能根据你的需要制作这个产品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41580, '击败如此强大的恐惧魔王绝非易事。甚至在生死的面纱之外，许多人诅咒着被诅咒的孟菲斯托斯的存在。你可以听到扭曲虚空中受折磨的灵魂的回声，当恶魔死去的那一刻，他们欢欣鼓舞。$B$B唉，这一点也不重要，因为你不仅成功地杀死了这样一个可怕的敌人，而且还夺回了它的盔甲。这件盔甲将作为你下一块拼图的基础；事实上，它甚至可以被认为是最后一部作品。像以前一样，给我带来我需要的材料，并获得一个甚至能让强大的艾瑞达也感到颤抖的奖赏。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41581, '末日守卫是他们主人的精英保镖——没有人能面对更凶猛的敌人，而你面对的是他们最好的敌人之一。从军团大领主的愤怒中幸存下来本身就是一项了不起的壮举，但你却打败了他。我感觉你拥有他的一些东西——一场有价值的战斗的纪念品，我们可以用它作为你盔甲的基础。你说呢？把我需要的材料带来，我们会确保你在精神上和身体上都能承受这场战斗。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41582, '你在扭曲虚空和外域的短暂一瞥之旅并非没有艰辛。不过，我能感觉到你拥有的一件东西——一件散发着超凡本质的遗物。请让我检查一下这双靴子。看来你面对的对手确实很强大，甚至可以穿越飞机。然而，虽然它的前主人现在已经死了，但它的魔力仍然存在。你说呢？把我需要的材料带来，我将根据你的需要锻造这件物品，确保你随身携带这场战斗的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41583, '这个护身符上有乌瑞恩家族的徽章，这是他的朋友莱恩国王送给麦迪文的珍贵礼物，因为他为暴风城的人民做了许多高尚的事情。即使在他疯狂的时候，麦迪文也坚持着。残破不堪——就像塔本身，一个曾经强大的历史哨兵。然而，也许这段过去的片段仍然具有价值。把我需要的材料拿来，我会确保这个护身符对它的新持有者有好处。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41584, '这顶王冠上有艾泽拉斯王国的标志，与莱恩国王曾经戴过的王冠非常相似。也许即使在他疯狂的时候，麦迪文仍然把他的朋友放在心里。断裂，几乎坍塌——就像卡拉赞塔一样，一个失落的历史守夜。正是在这段历史的基础上，我们可以重新塑造一些东西。把我需要的材料拿来，我保证这顶王冠对它的新主人有用。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41585, '我猜你的旅程中对扭曲虚空和外域的短暂一瞥不是没有麻烦的。然而，我感觉到你拥有的一件物品带有超凡脱俗的气息。让我看看这件斗篷吧。嗯，据我所知，你面对的敌人确实很强大——也许强大到可以在不同的平面之间转换。不管;虽然它的前主人已经去世，但它的一些魔力仍然存在。如果你能给我所需要的材料，我也许能根据你的需要制作这个产品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41586, '击败如此强大的恐惧魔王绝非易事。甚至在生死的面纱之外，许多人诅咒着被诅咒的孟菲斯托斯的存在。你可以听到扭曲虚空中受折磨的灵魂的回声，当恶魔死去的那一刻，他们欢欣鼓舞。$B$B唉，这一点也不重要，因为你不仅成功地杀死了这样一个可怕的敌人，而且还夺回了它的盔甲。这件盔甲将作为你下一块拼图的基础；事实上，它甚至可以被认为是最后一部作品。像以前一样，给我带来我需要的材料，并获得一个甚至会让强大的艾瑞达颤抖的奖品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41587, '末日守卫是他们主人的精英保镖——没有人能面对更凶猛的敌人，而你面对的是他们最好的敌人之一。从大领主的愤怒中幸存下来本身就是一项了不起的壮举，但你却打败了他。我感觉你拥有他的一些东西——一场有价值的战斗的纪念品，我们可以用它作为你盔甲的基础。你说呢？把我需要的材料带来，我们会确保你在精神上和身体上都能承受这场战斗。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41588, '你在扭曲虚空和外域的短暂一瞥之旅并非没有艰辛。不过，我能感觉到你拥有的一件东西——一件散发着超凡本质的遗物。请让我检查一下这双靴子。看来你面对的对手确实很强大，甚至可以穿越飞机。然而，虽然它的前主人现在已经死了，但它的魔力仍然存在。你说呢？把我需要的材料带来，我将根据你的需要锻造这件物品，确保你随身携带这场战斗的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41589, '这个护身符上有乌瑞恩家族的徽章，这是他的朋友莱恩国王送给麦迪文的珍贵礼物，因为他为暴风城的人民做了许多高尚的事情。即使在他疯狂的时候，麦迪文也坚持着。残破不堪——就像塔本身，一个曾经强大的历史哨兵。然而，也许这段过去的片段仍然具有价值。把我需要的材料拿来，我会确保这个护身符对它的新持有者有好处。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
