INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41621, '我猜你的旅程中对扭曲虚空和外域的短暂一瞥不是没有麻烦的。然而，我感觉到你拥有的一件物品带有超凡脱俗的气息。让我看看这件斗篷吧。嗯，据我所知，你面对的敌人确实很强大——也许强大到可以在不同的平面之间转换。不管;虽然它的前主人已经去世，但它的一些魔力仍然存在。如果你能给我所需要的材料，我也许能根据你的需要制作这个产品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41622, '击败如此强大的恐惧魔王绝非易事。甚至在生死的面纱之外，许多人诅咒着被诅咒的孟菲斯托斯的存在。你可以听到扭曲虚空中受折磨的灵魂的回声，当恶魔死去的那一刻，他们欢欣鼓舞。$B$B唉，这一点也不重要，因为你不仅成功地杀死了这样一个可怕的敌人，而且还夺回了它的盔甲。这件盔甲将作为你下一块拼图的基础；事实上，它甚至可以被认为是最后一部作品。像以前一样，给我带来我需要的材料，并获得一个甚至会让强大的艾瑞达颤抖的奖品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41623, '末日守卫是他们主人的精英保镖——没有人能面对更凶猛的敌人，而你面对的是他们最好的敌人之一。从大领主的愤怒中幸存下来本身就是一项了不起的壮举，但你却打败了他。我感觉你拥有他的一些东西——一场有价值的战斗的纪念品，我们可以用它作为你盔甲的基础。你说呢？把我需要的材料带来，我们会确保你在精神上和身体上都能承受这场战斗。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41624, '你在扭曲虚空和外域的短暂一瞥之旅并非没有艰辛。不过，我能感觉到你拥有的一件东西——一件散发着超凡本质的遗物。请让我检查一下这双靴子。看来你面对的对手确实很强大，甚至可以穿越飞机。然而，虽然它的前主人现在已经死了，但它的魔力仍然存在。你说呢？把我需要的材料带来，我将根据你的需要锻造这件物品，确保你随身携带这场战斗的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41625, '这个护身符上有乌瑞恩家族的徽章，这是他的朋友莱恩国王送给麦迪文的珍贵礼物，因为他为暴风城的人民做了许多高尚的事情。即使在他疯狂的时候，麦迪文也坚持着。残破不堪——就像塔本身，一个曾经强大的历史哨兵。然而，也许这段过去的片段仍然具有价值。把我需要的材料拿来，我会确保这个护身符对它的新持有者有好处。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41626, '这顶王冠上有艾泽拉斯王国的标志，与莱恩国王曾经戴过的王冠非常相似。也许即使在他疯狂的时候，麦迪文仍然把他的朋友放在心里。断裂，几乎坍塌——就像卡拉赞塔一样，一个失落的历史守夜。正是在这段历史的基础上，我们可以重新塑造一些东西。把我需要的材料拿来，我保证这顶王冠对它的新主人有用。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41627, '我猜你的旅程中对扭曲虚空和外域的短暂一瞥不是没有麻烦的。然而，我感觉到你拥有的一件物品带有超凡脱俗的气息。让我看看这件斗篷吧。嗯，据我所知，你面对的敌人确实很强大——也许强大到可以在不同的平面之间转换。不管;虽然它的前主人已经去世，但它的一些魔力仍然存在。如果你能给我所需要的材料，我也许能根据你的需要制作这个产品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41628, '击败如此强大的恐惧魔王绝非易事。甚至在生死的面纱之外，许多人诅咒着被诅咒的孟菲斯托斯的存在。你可以听到扭曲虚空中受折磨的灵魂的回声，当恶魔死去的那一刻，他们欢欣鼓舞。$B$B唉，这一点也不重要，因为你不仅成功地杀死了这样一个可怕的敌人，而且还夺回了它的盔甲。这件盔甲将作为你下一块拼图的基础；事实上，它甚至可以被认为是最后一部作品。像以前一样，给我带来我需要的材料，并获得一个甚至会让强大的艾瑞达颤抖的奖品。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41629, '末日守卫是他们主人的精英保镖——没有人能面对更凶猛的敌人，而你面对的是他们最好的敌人之一。从大领主的愤怒中幸存下来本身就是一项了不起的壮举，但你却打败了他。我感觉你拥有他的一些东西——一场有价值的战斗的纪念品，我们可以用它作为你盔甲的基础。你说呢？把我需要的材料带来，我们会确保你在精神上和身体上都能承受这场战斗。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41630, '你在扭曲虚空和外域的短暂一瞥之旅并非没有艰辛。不过，我能感觉到你拥有的一件东西——一件散发着超凡本质的遗物。请让我检查一下这双靴子。看来你面对的对手确实很强大，甚至可以穿越飞机。然而，虽然它的前主人现在已经死了，但它的魔力仍然存在。你说呢？把我需要的材料带来，我将根据你的需要锻造这件物品，确保你随身携带这场战斗的精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41631, '这个护身符上有乌瑞恩家族的徽章，这是他的朋友莱恩国王送给麦迪文的珍贵礼物，因为他为暴风城的人民做了许多高尚的事情。即使在他疯狂的时候，麦迪文也坚持着。残破不堪——就像塔本身，一个曾经强大的历史哨兵。然而，也许这段过去的片段仍然具有价值。把我需要的材料拿来，我会确保这个护身符对它的新持有者有好处。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41632, '我想一座充满亡灵的浮空城是完美的的狩猎场。虽然那的猎物与你迄今为止遇到的都不同，但我有信心相信你有足够的能力继续这你生平最伟大的狩猎。$B$B正如我们之前所聊到的，地穴追猎者套装可能触手可及——然而，与之前的任何一套护甲不同，这套护甲似乎只有一个强大的戒指。如果你发现类似的东西，把它还给我，我们将一起释放它真正的潜力。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41633, '看来我拥有许多指骨。我不会给你留下他们“正确”的解剖学名称，因为教你手的结构既不是我的目的，也不是我的工作。然而，作为一个盗贼，也许你应该学习......不过——没关系。我们偏离了主题。$B$B正如我之前告诉你的，唐·胡里奥设法教了我他的骨镰盔甲的手艺，我会把它提供给你——这不是免费的。如果你在战斗时遇到任何类似戒指的东西，不仅是为了你的生存，也是为了我们其他人，把它带到我这里来。我会确保它装饰上这些指骨，这反过来又会完善你的护甲。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41634, '多么无礼的孩子啊！我已经数不清我教过她多少次关于奥术魔法的危险了。她那种鲁莽的好奇心总有一天会让我们大家都倒霉。$B$B你准是注意到从这个破房子往上爬的那座塔了？通常我会和来自北风领周围和其他地方的那些魔法爱好者住在那，但我“最亲爱的”学徒斯隆达认为召唤她自己的奥术元素集会来帮助她做家务是个绝妙的主意。太糟了，它们失控了，现在正在我的塔里到处唬人！$B$B$N，爬上塔，取回我的年鉴以及它们死亡的残渣。一旦我与它们的能量调和，我就可以施放咒语来阻止他们重新出现。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41635, '我在北风领度过了我的一生，自第一次大战以来，这里从未如此混乱过。豺狼人、兽人和黑铁矮人都在我们宁静的山坡上晃荡，无论走到哪里都会制造混乱。即使是迪菲亚恶棍也也想来捞一笔。这些大胆的强盗竟然敢袭击我们附近安伯郡东北部的伐木营地。当然，所有的工人都逃走了，但镇上没有足够的地方让护他们住，所以现在他们在我的仓库里落脚。要是安伯伍德的守卫能勇敢地帮助北风的好公民就好了！$B$B营地似乎又落入了他们的手中。冒险家，你看起来身体健康，头脑清醒，你会帮助我们吗？将迪菲亚赶出伐木营地;帮助我们为我们美丽的家园恢复哪怕一丝的平静！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41636, '$C，您能抽出一点时间吗？我现在正处于危机中，而你似乎是解决问题的合适人选。我是一名旅行商人，销售适合全年龄和兴趣的书籍。我每个月都会带着暴风城教堂的邮包来这里到安伯郡;市民为所有参加在河对岸的安伯郡教堂举行的讲座和学校的孤儿捐款。然而，在我来的路上，我被小偷抢劫了，他们的战利品中据说有捐赠箱！$B$B我试着跟着他们，但我的年纪已经太大了。我只看到他们逃进了北方的山里，其中一个人戴着一条乌鸦黑的围巾。请帮助我履行对这个王国无辜儿童的义务。如果你找到板条箱，把它带到安伯郡北部的教堂的阿金特修女那里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41637, '再次感谢您将这些书带回给我们。孩子们听到我们不必取消今天的教学，会很高兴。你可能会以为他们会因为不得不上学而感到烦恼，但他们实际上喜欢来这里，一起更多地了解这个世界。这是一个温暖的景象，给了我希望，他们将踏上通往光明未来的道路。$B$B由于抢劫案，我们的时间有点晚了，我需要一些时间来准备今天的讲座。您愿意帮我们吗？孩子们肯定会渴望与那个勇敢地从那个强盗手中拯救他们书籍的人交谈！上周，我们向他们介绍了巴洛岛的历史，巴洛岛位于这里以西。也许你可以通过提醒他们来帮助他们巩固知识。你可以在教堂里找到我们用的那本书。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41638, '看到北风领发生的事情令人羞愧。当我在大主教本尼迪塔斯的推荐下回到这里协助阿金特修女时，我从来没有想过我会发现这里。人们害怕来自东边的入侵，罪犯已经踏上了我们的山丘。即使是古老的修道院也是……$B$B抱歉，我说话不合时宜，请原谅。你看，北风领是我的出生地，我记得它柔和的自然风光和人们可以在这里度过的无忧无虑的日子。但我想那些日子已经一去不复返了。如果我知道，我会带着妈妈一起去。她的安息之地被往日的噩梦所占领;这让我心碎。她在我还很小的时候就去世了，她的骨灰盒被放在圣玛拉修道院的地下室里。$B$B$C，我问的太唐突了，但你愿意找回我母亲的骨灰盒吗？这对我来说意味着整个世界，不是要对你不利，我以我对光明的誓言发誓。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41639, '真是奇景，人们很少走近我的女巫集会;更别说如此大胆地进入我的家了。您认为这些礼仪对于像您这样的$r来说合适吗？当然不。但我可不想浪费宝贵的时间来批评你的无礼，或许我还能好好利用一下这事。$B$B我需要一些食材。通常收集它们对我来说没问题，但北风领的树林最近发生了变化。有令人讨厌的人在鬼祟出没，我很希望他们别盯着我看。不如你出去，把我想要的给我带来。这是个简单的任务，让我忘记你对我家的无礼冒犯。我相信你一定能出色地完成它，亲爱的。您可以从北风领周围的当地野生动物中收集它们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41640, '这是咋的啦？就在今早，我正在为巡山人准备啤酒和吃的，这时我突然看到黑铁矮人袭击了我心爱的小酒馆！泰坦准在照看着我，因为我只受了点轻伤就跑掉了。这个驻守的巡山人帮助我恢复了一点体力，但我仍然对发生的一切感到震惊。尽管如此，我不能让这种不公正再存在了！既然这里的好人暂时帮不上我，也许你愿意把你的剑和魔法借给这个老头子？你看起来足够健壮和坚强，足以胜任这项任务。$B$B盔枕湖以南是通往我的山居的通道。我敢肯定它已经被那些恶魔般的黑铁家伙占领了。如果你，也许还有你的一个朋友能从我的小房子里取回我的个人物品，那将极大地抚慰我忧心忡忡的心。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41642, '当这里西北部的伐木营地被肮脏的迪菲亚袭击时，伐木工们很快就逃脱了，几乎毫发无损。我和我父亲在他的仓库里照顾那些伤员，因为他们现在没有其他地方可以住。尽管如此，虽然他们当中有许多熟悉的面孔，但他的一位好朋友克里斯托弗·——他在营地工作——还没有出现，无论是在这还是在安伯郡。$B$B克里斯托弗有一个年幼的儿子，恐怕最糟糕的事情已经发生了。请帮我这个忙，去找他。也许他藏在营地附近的某个地方......') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41643, '为了国王的荣誉，$c。我必须承认，现在不是访问北风领的好时机。通常这个山谷是一个宁静的地方，没有受到世界各类麻烦的影响。但最近，许多危机在这些山上爆发了。如果你从暴风城来到这里，你已经明白我在说什么了。然而，在夜色的阴影中，还有更多令人痛心的事件正在发生。$B$B几周来，我们收到了王国发生失踪事件的报告。起初他们很少，没有什么不寻常的，但现在数量已经上升到惊人的数量。这在技术上是机密的，但我就一个调查员，无论如何都没法独自完成这件事。军情七处在西部荒野上正与迪菲亚全力对敌，所以我只好找你来协助我。别着急，我会给你安排公正的酬劳。$B$B首先询问剩下的镇民、场地管理员、巡官和受害者的一名亲属。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41644, '伊格纳兹和朱迪思的证词与我们关于迪菲亚在该地区活动增加的报告相符。提到的这些“偷偷摸摸的角色”很可能是迪菲亚恶棍，正在侦察该地区是否有盗窃机会。我们还没有找到他们的行动基地，所以我们可能会在这里一石二鸟。$B$B搜索安伯郡周围区域，了解迪菲亚的活动和有关他们从哪里派遣爪牙的潜在情报。一旦你得手了，就潜入其中并给我带来任何可能有助于我们找到失踪人员的线索。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41645, '在卡兹莫丹的土地上，刚过冰冷的山脉，铁炉堡的矮人与他们疏远的兄弟黑铁矮人不断发生冲突。这些矮人将火山黑石山称为他们的家园，并以其在发黑的洞穴中严格的采矿作业而闻名。令联盟沮丧的是，他们并不是靠自己实现这一目标的，而是通过无情和无情的奴隶制来实现的。伯克顿镇长告诉我他们最近在北风领掀起了新动乱——这是一个不祥的预兆。$B$B如果他们绑架北风领公民做奴隶的可能性存在，那么我们必须调查一下。前往西北部的舍伍德采石场，收集有关我们当前调查的情报。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41646, '我们最后的选择是黑石兽人们，您无疑已经见过他们。根据我们的侦察，他们几周前开始向北风领推进，没有明显的动机或理由。它发生在黑铁矮人们采取侵略行动后不久，因此可能存在联系。洗劫比尔克庇护所恐怕只是一个开始。$B$B现在，我们将把注意力转移到保护北边的哨塔的兽人小队上。他们远远领先于主力，这里肯定有不同的目标。此时您知道该怎么做，我会在安伯郡等待你的消息。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41647, '$C，我能和你聊一会儿吗？我无意中听到了你和霍桑特工的讨论。你们俩为解决我们最突出的问题所做的努力值得称赞，但至少可以说，暴风城只指派他来做这件事是令人担忧的。北风领在能想到的最糟的时候被袭击，安伯伍德领主正将他的大部分军队派往暴风城。如果你问我，考虑到王国其他地区的情况，这很奇怪。关于你的调查-我相信我可以告诉你找到你实在找不到的东西的方法。$B$B在遥远的西北方向，你会发现一片坐落在山中的小树林。一位老妇人住在深红色的树下——她一定能帮你，我敢肯定。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41648, '所以你迷失了。亲爱的，我能从你的脸上清楚地看到它。你需要有人为你指路，而你被告知那人是我。一定是那个愚蠢的女孩莉迪亚，自从她离开了我的女巫团后，她就不想再来看我了。她的野心和作为镇长的职责束缚了她，锁定了她的真正潜力，她会接受它吗？不管那些漫无边际的事情，她是对的。我可以而且会帮助你满足你的需求，但不是出于我内心的善良。这些闯进我树林的恶棍在这里毫不讲理！$B$B我需要你搞到的相当简单：死亡帽和寡妇的裙边，这些山丘上的原生蘑菇。死亡帽生长在洞穴中，有一个橙色的盖子，寡妇的裙边在潮湿的土壤附近以三个为一组生长;在格里门湖附近的大桦树林中搜索。把这些和最近被绑架的人的私人物品给我。我相信你会在城里找到我想要的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41649, '如果说查波·查皮布拉斯有一件事是无法忍受的，那就是他们的抱怨会破坏其他人的乐趣。在昨天的广播中，我和我的团队失去了与我们的信号塔的连接，几秒钟后才听到一条神秘的消息通过我们的输出通道发送！这个厚脸皮的家伙在我的广告中抢走了关注，开始诽谤我们，比一个喝多了的僵尸还严重！咱关闭广播塔也不行，在最近的暴风雪之后，我们工作了一整天想让广播恢复！可我们现在广播的只是一片寂静！一场灾难！$B$B你看起来挺活跃……或多或少。我需要一些帮助来揭露这个冒牌货。没人能简单地干扰查波·查皮布拉斯而不付出代价！$B$B你可以在我旁边找到我们的录音盒。只需按下绿色按钮，然后向下拉动滑块，将旋钮向左旋转至最大输出！再次倾听干扰将有助于我们弄清楚这一切的真相。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41650, '当你听录音时，我注意到一个独特的声音——不，两个不同的声音，甚至我以前都没有意识到。调制器似乎只改变了暴徒的声音，而不是整个输入通道。真是个业余爱好者，比一个被遗忘者想买人寿保险更无知。$B$B你看，我能记得我听到的任何声音。我听到的不仅仅是啥普通的噪音：就在几天前，我和其他人开始了一段旅程，为我们的多元化广播收集一些素材。我们冒险去的地方之一是艾萨拉那琥珀色的山。正是在北部的悬崖上，劫持者选择拦截我们的无线电。你说这令人印象深刻？我知道，但这就是查波·查皮布拉斯。$B$B像你这样的冒险家如果你愿意冒险去那里面对那个家伙，可以赚到一些良心钱。搜索东北部悬崖。那是海浪拍打声和角鹰兽尖叫声最突出的地方。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41651, '<翻阅日记，你会推断出那个地精的身份是比兹邦·链盒，一位来自科赞的工程师，显然在安德麦的一些原型机械上与查波合作过。从你能读到的内容来看，他一定对没有被查波的永望广播公司录用内心感到非常不满。$B$B案件已结案。有点太容易了，你不喜欢。有些事情真的说不通，但结案了就是结案了。是时候回报给永望镇的查波·查皮布拉斯了。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41652, '<在最初的几次广播后不久，节目突然被切断，取而代之的是一个奇怪且不祥的干扰。它并没有持续很长时间，因为它就像它出现的那样迅速结束。现在你能听到的只是深入你耳朵的令人麻木的静电。显然不是由查波·查皮布拉斯或他的任何客人派来的，你对刚刚目睹的事情感到困惑。对整个场景感到好奇，你决定亲自去永望镇拜访那个电台地精>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41653, '您好，旅行者，祝您农历新年快乐！每年的这个时候都会召唤着我们在未来一年努力实现的新志向、梦想和抱负。因此，倾听和思考那些在言行中蕴含智慧的人是很重要的。我的祖先走遍了 卡利姆多，遇到了许多神话中的生物和精灵。其中一位，对大多数人来说并不起眼，却拥有最深刻的洞察力。直到今天，我的部落在需要的时候寻求这种精神的指导。$B$B我 希望您去拜访它，从它的话语中学习并牢记在心。大自然在它的巢穴中低语;在尘泥沼泽的西北沼泽中，你会找到它。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41654, '农历新年是许多牛头人部落和家庭的盛宴。虽然我们到处都有习俗，但其中大多数都是他们部落独有的。我仍然记得我父亲曾经给我讲的故事，关于他在新年庆祝期间参加的第一次狩猎。那时，野猪在草原上漫步是很常见的。它们的猪群可以很远很远地看到，我们的猎人每年都会聚集在一起，为整个部落准备盛宴。$B$B 如今，野猪早已被刺背野猪人屠戮或圈养起来。$N，我想亲自准备一场盛宴来向我的祖先致敬，所以请帮助我实现这个目标。杀掉任何种类的野猪，把它们的尸体带回来十个，这应该足够月光林地这里所有快乐的旅行者吃了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41655, '祝福你的家庭， 旅行者。庆祝活动如火如荼，来自艾泽拉斯各地的游客源源不断地来到 月光林，渴望与他们的同胞一起庆祝，无论他们来自哪里。我看到你还年轻，充满精神和雄心壮志;对于那些过着冒险生活的人来说，这是令人钦佩的品质。如果这是您寻求的挑战，那么农历新年就是最佳时机。这是一个挣扎的时刻，克服依旧依附在你灵魂上的重担，这样你就可以带着不受束缚的精神进入新的时代。$B$B在世界上冒险，潜入邪恶的巢穴，直面内心的疑虑。向我展示你的胜利信物，向我证明你是如何征服自我的，我会奖励你的努力。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41656, '任何勇于和龙喉氏族作战的人都会获得赏金。我们许多勇敢的兄弟姐妹都死于这场冲突。如果不采取一些措施来结束这种侵略，更多的我们自己人就会倒下。$B$B 碎刃的安全岌岌可危，敦促有能力的人以部落的名义战斗。$B$B 目前已知它们在冷酷海岸的许多地方向西聚集。$B$B 将你完成任务的证明交给指挥官阿格纳什以获得奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41657, '在祖鲁希德的尸体上发现了一封破旧的信。这封信似乎是写给他的，字迹粗糙，内容如下：$B$B<所以你终于回来了？自从我们其他人为生存而拼命战斗以来，你消失去寻找你的神器已经多久了？你为了自己愚蠢的荣耀抛弃了龙喉氏族，现在，因为你已经回来了，你还指望所有的酋长们毫无悔意或仇恨地联合起来？$B$B不要指望我和其他祖鲁希德人一样愚蠢。你可以随心所欲地躲在格瑞姆巴托的地下。我会带领我们的氏族在冷酷海岸的土地上取得辉煌而伟大的胜利，而不是像雷德和他的同伙那样躲在洞穴里。我们中的一些人知道黑石的真相，并且不想将事实隐藏在看似辉煌的所谓“黑暗部落”的概念背后……你的订单被拒绝了，老朋友。$B$B科尔拉格·末日之歌，龙喉氏族。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41658, '这封信证实了流传的一些谣言，龙喉氏族并未完全团结。$B$B 现在祖鲁希德已被杀，只有一个人可以争夺酋长，那就是指挥官科尔拉格·末日之歌。如果我们要战胜龙喉氏族，我们必须先杀死科尔拉格本人。$B$B 我必须警告你，他是一个危险的敌人，应该对他的武艺给予最大的尊重。我建议带一整队的战士来祝你战斗。$B$B 你会在西北方向的扎姆盖斯要塞深处找到科尔拉格。带上他的头，荣耀归来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41659, '遥远的南方是塞尔加拉兹矿井，曾经被丹基塔斯的矮人占据，现在被肮脏的碎骨穴居人占领。如果部落想要宣称拥有冷酷海岸，就必须坚决处理侵扰。你的任务是杀死碎骨穴居人，并清除他们的肮脏存在。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41660, '几周前，一大群黑铁人穿过了冷酷海岸，在碎刃以北的 格罗丹挖掘场定居。他们已经探查了我们的防御工事，我们的哨兵不止一次地发现了间谍。他们正在计划什么，我很确定。$B$B如果我们要保证我们的安全，我们必须先发制人，削弱他们的队伍，以阻止他们发动任何攻击。前往格罗丹挖掘场，让他们为自己的入侵付出代价。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41661, '我经常发现自己盯着看——这对一名守卫来说是个坏习惯，不是吗？但我还是忍不住，我的目光飘向树木。树叶飘落，微风将它们卷入打转的风中，舞动起来——就像树叶本身会舞动一样。$B$B<加斯帕尔笑了笑，看着你身后展开的风景。>$B$B嗯，在我拿起武器之前，我曾经是一名画家。在我们生活的日子里，这是必要的牺牲。我遥远的家，现在已经被遗弃，而我日夜守护着这座塔。虽然我的眼睛看到了美丽，但我的耳朵却被那疯狂的笑声折磨着。$B$B不能离开我的塔。即使暴风城如此接近，商旅之路仍然受到那些可怕的豺狼人的困扰。我请求你，请弄死一些他们的人来让我安心。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41663, '随着蜚语流言的不胫而走，疑虑的种子已在平民的心中萌芽了。可这又怎能怪得了他们呢？众口铄金，寡难敌之。我们在过去数月都处于动荡之中。$B$B北风领的人们已经很久没有过这种朝不虑夕的生活了。然而，我们的上级却无视迫在眉睫的危险，尽情展露着自己的愚蠢——想象一下，如果你的家园遭到袭击，你会呼吁举行骑士锦标赛，而不是向其他贵族寻求帮助或用你的力量为人民提供庇护吗？$B$B我想这样的人不是小丑就是傻瓜。除非我们考虑第三种可能性：有些人会利用混乱而为自己谋取权力。我觉得这次也是如此。向演武场的舍伍德公爵汇报我的担忧。只有那个人才能在其他人都无法应对的情况下挺身而出。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41664, '不知何故，这只狡猾的老狐狸又猜对了。这是我今天能想到的最令人愤怒的事情之一。若非形势已经如此荒谬绝伦——也就是说，我们把这里描绘成“安全的”，让整个人类王国都能看到，实则不然——同时我们要与豺狼人、兽人、迪菲亚以及天知道的其他东西作斗争，这还不够荒谬吗？我们还背负着这个“黑暗骑士”的负担。$B$B<公爵摸了摸额头，叹了口气，疲惫的眼睛里带着一丝希望看着你。>$B$B这一定是某种狡猾的阴谋，我无力应对。帮帮我吧，北风领的人民都依赖你我。我知道你从中得不到什么好处，但我恳求你发自内心地行动。我只需要你潜入黑暗骑士的帐篷，寻找任何……诅咒的东西。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41665, '可怜的安伯伍德领主，被诅咒要承担这个负担——这不是领导的负担，而是有这样一个兄弟的负担。唉，我们没有选择家人的奢侈。安伯伍德领主是一个宽容的人，他太多次忽视了他兄弟的行为——然而，我怀疑他是否会接受这一点。$B$B我害怕结果。北风领已经崩溃了——如果我们领主的心也碎了，我们可能永远无法恢复。我向光明祈祷，希望这些信息能坚定他的决心，而不是让他头脑迟钝。然而，当自己的兄弟想要杀死他时，一个人怎么能不心痛呢？$B$B哥哥在贵族院的支持下寻求统治，以终结自己的兄弟——在这个黑暗骑士的手中。想想他们现在还在继续他们的计划。$B$B平民只是这些“贵族”的玩物。把这封信交给安伯伍德领主，但不要提及你所知道的事情。我会召集真正的贵族，亲自告诉他真相。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41666, '您是来尝试我们广受好评、备受追捧的琥珀甜甜圈的吗？我非常高兴，但很遗憾，我们的甜甜圈已经售罄。看来它们真的很受欢迎！要是我早料到这一点就好了。人们想要更多，而我现在却没有任何配料。$B$B如果您能帮助我采购一些配料，我会很荣幸为您炸一些我著名的甜甜圈。老实说，我甚至会提供一些报酬。我需要面粉、盐、糖和蜂蜜。其余的我可以自己准备。我特别提到这些配料是因为它们需要花点时间才能获得。$B$B我将为您提供一份清单，您应该在安伯郡找到它们。我非常感谢您的帮助。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41667, '这场比赛简直就是一场闹剧。我们怎么可能赢？我敢打赌他们给马蹄铁附魔了。我知道，我就是知道！我不能让激流堡被一个书呆子王国和一个新成立的——呃，我甚至不会称它为王国——击败。$B$B塞拉摩和库尔提拉斯会过于专注于对方，但真正的威胁是达拉然。我不喜欢莫德拉那女人斜眼看我，他们有自己的阴谋——我知道他们有！$B$B听着，$R，我会付给你丰厚的报酬。回到暴风城，乘船去黑海岸，然后前往阿尔萨拉斯。我听说有个叫查杜斯·桑克利尔的人可以提供一对附魔马蹄铁。把它们给我找回来，你对激流堡的贡献将被铭记——你的口袋也会更鼓。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41668, '冒险者，您是否愿意为一位老妇人完成一项任务？我已经很久没有见到我的孙子了，我无法联系到他。由于我年事已高，有人建议我不要离开北风领，出于安全原因，他不能离开要塞——至少有人告诉我是这样。$B$B我想给他寄一份便当。这个可怜的孩子可能吃得不好，可能因为到处跟着他的蠢大人而压力过大。您能否前往演武场购买一包琥珀甜甜圈，然后去旅馆旁边的玛丽莎那里买一捆苹果，最后到我家——市政厅旁边——取回我今天早上烤的馅饼？$B$B请将它们全部还给我，我准备剩下的包。我还需要补充一些其他内容。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41669, '收集好所有东西后，你只需要前往暴风要塞，把这个袋子交给安度因王子——但只能交给他，明白吗？否则，那些讨厌的贵族苍蝇会围着他检查它。如果必须的话，就像骡子一样固执。你需要亲自把这个袋子交给安度因，明白吗？$B$B这是你的辛苦钱，还有你必须交付的袋子和这个毛绒玩具。把它放在身边，它可能会让你付出生命的代价。当然，我是在开玩笑，但它是属于我的蒂芬（指安度因王子的母亲,瓦里安国王的王后）的。我知道孩子会很高兴得到她的东西。现在去，告诉他我爱他正如秋叶必然落下。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41670, '照顾亲人的最后安息之地是我的责任。虽然责任可能很沉重，但用这双手照料墓地让我感到自豪。还有什么比照顾那些不再与我们同在的人更好的责任呢？安伯郡的大多数公民每天都会来这里，手里拿着鲜花。缅怀死者已经成为一种惯例。$B$B然而，时代已经变得暗淡——甚至黑暗。习惯上，人们会在亲人的墓碑旁放上鲜花，旁边点上一根蜡烛。这样，蜡烛的闪烁可以引导灵魂回到我们的世界，这样它就可以接受祭品。很少有商人还会走以他们的职业命名的道路，因此教堂的蜡烛用完了。$B$B卑鄙的狗头人一天晚上偷走了我们仅剩的蜡烛，躲在他们的洞穴里。要到达这个洞穴，你必须沿着道路前行。返回狮子岗哨，朝“丰满的南瓜”旅馆走去，穿过格里门湖后，你会发现附近的洞穴。把蜡烛还给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41671, '圣光已经多次考验过我们王国的土地。对于少数人来说，这足以让他们的信仰黯然失色。我们的修道院每年都会举行一次福音布道会，我们会在那里纪念这片土地上所有的死者，无论需要多少时间。修道院院长有责任念出每一个名字。$B$B修道院阴沉悲哀的音乐被一个燃烧的女人的哀号打断了。“火——火！”她尖叫着，她的声音在修道院的墙壁里回荡。她全身着火，倒在地上，眼泪被热气吹干，皮肤被火焰灼伤。她的哀号拯救了许多人的生命，尽管也有少数人丧生。$B$B有人悄悄说是豺狼人放火烧了修道院，其他人则认为这是圣光的愤怒。一些人甚至认为可怜的修女自己不小心点燃了火。谁说的是实话？往东走，去修道院的废墟。石墙依然矗立，也许我们的讣告也还在。把它还给我，这样我们今年就可以再次纪念死者。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41672, '鱼人就像蟑螂。你刚杀死一只，又有两只从它们肮脏的产卵地孵化出来。世界上有这么多这种令人作呕的生物，真是难以置信。好像世界上只要有水的地方，它们就注定会出现。哼，这真是一个适合居住的世界——而这个世界本身似乎在追杀你。$B$B像你这样的冒险者有责任消灭这些堕落的生物。你可能看到我愤怒背后的傲慢，但其实这是自怜。如果我能自己对付这些生物，我会毫不犹豫地举起武器。但我做不到。无论我试了多少天，我都无法挥动剑。我的技能最好用在别处。$B$B帮我这个忙，我会尽我所能报答你。消灭它们的数量——不管有多少，就这么做。它们越少越好。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41673, '冒险者，要去杀一些鱼人吗？几秒钟前，特蕾莎和我还在愉快地聊天。正如她指出的那样，她看到一个蛇一样的女人对着那些丑陋的东西咆哮。我说“咆哮”是因为我们真的不明白她在说什么。我想她应该是他们的头头之类的——我对鱼人了解不多。$B$B不管怎样，特蕾莎注意到那个女人带着一颗巨大的琥珀珍珠——她声称有她的头那么大！如果你冒险进入那个洞穴并打败她，你能把珍珠带回给我吗？我想把它作为礼物送给特蕾莎。她是我的好朋友，我想好好感谢她。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41674, '我的酒庄被那些野蛮的灰毛蠢蛋占领了。呸！该死的！想想看，我们必须一次又一次地面对兽人。我对他们那猪一样的脸已经感到厌烦。如果我不是这么老，我会拿起干草叉，不放过任何一个！$B$B希望我的儿子们也能有同样的感觉。他们现在还像孩子一样闷闷不乐。我对他们太宽容了，他们不知道战争，这就是战争的后果。我们家族拥有的一切都掌握在那些该死的兽人手中。我试图监视他们，但我看到的景象让我非常非常愤怒。他们不仅吃着我的葡萄，喝光了我所有的酒，还玷污了我的家！$B$B他们必须被消灭。帮助我，冒险家，我家族的传家宝就是你的了。求求你，做我和我胆小的儿子们做不到的事！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41675, '那个我称之为父亲的絮絮叨叨的老头已经完全疯了。不管是年迈，还是他所谓的失望，因为我们不愿意在与兽人的战斗中毫无意义地死去，他都还气呼呼的。我不是不理解他的沮丧，而是我不是士兵，我是个他娘的酿酒师。我该怎么与比我强大十倍的东西战斗？$B$B如果我不是已经有些秃了，我会扯掉一把头发。我才二十多岁，这个老人给我太大的压力，我的头发都掉了。“我们需要一个新的配方，——做这个，耶利，做那个，耶利。”他喋喋不休。但我爱这个老人，毕竟，他是我父亲。说实话，如果我必须从人群中挑选一个男人做我的父亲，我仍然会选择他。$B$B这就是为什么，在他因气到崩掉自己血管前，我想让他看看我做的新配方。你会在酿酒厂的上层找到它，我把它藏在衣柜里，然后逃跑了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41676, '尽管这些灰白的兽人看起来很没头脑，但现实却完全不同。我设法让一些人——嗯，我该怎么说呢？一些非常（他强调了‘非常’）熟练、鬼鬼祟祟的人——为我收集情报。这些信息很有用，但我们能做的不多。虽然我之前提到的人非常擅长收集情报，但他们在战斗中不会有太大作用。$B$B这就是为什么我相信一群冒险者，由像你这样经验丰富的人领导，可能能够结束这个兽人的威胁。他们有三个。你会发现索克大王在一个我们称之为黑石裂口的山洞里，奥扎克·末日之刺在外面一所废墟的房子里咆哮着发号施令，而舒尼·钢牙已经深入我们的领土，她已经占领了我们的一座瞭望塔。你会发现那座塔坐落在山上，曾经守护着我们的英雄祭坛。$B$B做掉他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41677, '如果兽人本身的威胁还不够大，我们还得对付黑铁矮人，他们离开他们烧焦的地盘，在我们这里挖了一个采石场。以圣光发誓，这世上每有一个黑铁矮人，就会有一个采石场。就好像是某种神灵希望矮人和采石场在全地繁衍生息。$B$B然而，抛开喜剧不谈，我需要一个有能力和勇气的人来破坏他们。我们人数不足，坦率地说，我们现在缺乏耐心来对付矮人，兽人的威胁更大。谢天谢地，黑铁矮人带了火药桶——一个容易破坏的目标。潜入，或者硬闯——我真的不在乎——只要炸掉那些火药桶就行了！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41678, '我来这里是为了传播圣光的福音，让人们加入我们对抗天灾军团的十字军。然而，当我环顾四周时，我看到的只是对圣光的困境和不信任。这些人几乎无法自救，他们认为自己被圣光抛弃了。$B$B他们不是真正的信徒——这就是一切。洛丹伦完全沦陷于天灾军团之手，但我们的血色修道院仍然闪耀着圣光的光芒。我几乎可怜这些傻瓜。哼。说实话，我有一个任务给你。一旦你拿到我需要的东西，我就会回到修道院，我再也无法忍受看到这些可恶的人了。$B$B他们正沉浸在内疚和酒精的麻醉之中。无论如何，我寻找的东西应该还在被烧毁的修道院里——那是前任修道院院长用来给水赐福的圣杯。它仍然拥有这种力量，我的人民比这些恶棍更需要它。把它还给我，我会付给你一整枚金币。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41679, '威格斯，你这个一无是处的、天生的白——哦，不是说你，威格斯，是吧？真是个困境。$B$B<特里斯顿一边摆弄着烧瓶，一边眨了两下眼睛。>$B$B你站在那里干什么？嘘，走吧。我在这里很忙——在做实验——嗯，想当我的实验耗子吗？不想？有些人太大胆了。你应该为我问过你而感到自豪，哼。那么，你是……什么，一个冒险家？这就是你愚蠢地大老远来到人类王国边缘冒险的原因吗？呸，傻瓜。$B$B去把烧焦的修道院附近的骨头打碎——我需要烧焦的骨头。别问为什么！是为了冒险。$B$B<他自言自语道。>$B可怜的白痴。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41680, '我的那个一无是处的助手还没有回来，这让我非常生气。所以，你去找他。这可真是一次冒险，你不觉得吗？好吧，好吧，我不跟你开玩笑了。我真的需要帮助。我已经把威格斯派到比尔克庇护所——或者说是它剩下的部分，或者随便你怎么称呼它。$B$B他应该杀死这些入侵的黑石兽人中的一个兽人施法者。我想你以前听说过焚化大师吧？没有？长话短说，它是某种兽人——呃……拥有死灵法术天赋，但也擅长使用火？我不确定，所以我需要它死掉——这样我就可以把它带回来，了解它的秘密。$B$B那就上路吧。找到威格斯。哦，对了，威格斯的头发已经白了——秃了。你应该能很容易地找到他，不用担心。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41681, '威格斯闻到了肉人上主人的气味——肉人能帮助威格斯吗？$B威格斯找到了臭兽人，嗷！呃！$B非常臭的兽人。$B$B臭兽人躲在投石器旁边的帐篷下。嗖——咚——咚！$B大石头坠落，摧毁威格斯。威格斯伤心。$B大石头坠落，威格斯就没了！咚咚咚威格斯走了！$B$B肉人离开，威格斯留下？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41682, 'Lok-tar（兽人语：胜利），新部落的小崽子。我是杜尔·狼啸，来自卡鲁法尔要塞。虽然我们结盟的时间不长，但我认为你值得信赖，可以成为我的同伴。我没有必要知道是什么把你带到这片土地上的，但我希望你来这里是为了制造一点混乱。$B$B我们的酋长派我来监视一些仍然向黑石山屈膝的兽人同族。除了那些恶棍之外，黑铁矮人还渗透到这片土地上做他们最擅长的事情——建造采石场。我不明白这种对挖掘的热爱，唉，他们正在自掘坟墓。$B$B把这个袋子带到舍伍德采石场，炸毁他们的火药桶。到早上，他们就不剩下一个了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41683, '每当我们的战争领主决定对抗黑手的后裔时，就会在黑石山的队伍中留下一个巨大的缺口。我们的许多人都是光荣的战士或受人尊敬的长者——说实话，我们是注定要攻占这片土地的人。但糟糕的是，我们没成功。$B$B然而，我们却被一群败类所取代。这是一场闹剧，是对卡鲁法尔力量的嘲弄和侮辱。当我用其他方式消灭他们时，我建议你们以人数取胜，杀死那些忘恩负义的人。$B$B你会发现索克大王在一个叫做黑石裂口的山洞里，奥扎克·末日之刺在一所废墟的房子里咆哮着下令，而舒尼·钢牙已经深入人类领土，她已经占领了他们的一座瞭望塔。你会发现这座塔坐落在曾经守护英雄祭坛的山上。砍下他们的头，带回来给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41684, '<女巫搅拌蘑菇混合物，让它的颜色从浅红色变成鲜艳的蓝色。她狡黠一笑，一饮而尽，然后进入了恍惚状态。她呆呆地站在原地，低声耳语着一些难以理解的话语。片刻之后，她恢复了理智。>$B$B你很幸运，年轻人。我已经看到你在寻找的人了——他们仍然留在北风领。如果你想抓住他们，那就快点。我的幻象向我展示了你带来的梳子属于的那位年轻女子的所在地。爬上安伯伍德城堡旁边的山丘，沿着它的踪迹走。邪恶在那里等着你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41685, '我会在北风领这里忙一段时间，这就是为什么我需要你代替我提交这份报告。它包含了我们收集到的所有证据，以及你在兽人身上找到的那封信。我自己无法解读它，但我的上司精通多种语言，包括兽人语。尽快把它带给暴风城旧城区的马迪亚斯·肖尔。亲自告诉他你所看到和经历的一切。$B$B祝你好运。为了国王的荣誉，朋友。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41686, '你一定想知道他们可能把被绑架的人带到哪里去了。对我们来说幸运的是，这份文件告诉我们他们在哪里行动。虽然这对我们有利，但读到这个岛的名字让我不寒而栗。被诅咒的、可怕的巴洛岛，位于暴风城港口的西海岸外。王国几十年来都没有踏上过这个岛屿，因为它留下的是灭亡和可怕的灾难。$B$B我们不能再等了。如果巴洛真的是他们的行动基地，那么被俘公民的命运将是悲惨的。我会尽快派出一支特遣部队，我希望你能随行。为这个荒岛做好准备，不要掉以轻心。暴风城港口的西蒙斯特工将确保你走上通往巴洛的正确道路。到达那里后，向维罗纳·基里安报告，她将领导行动。$B$B尽力而为，$C。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41687, '这些被圣光所遗弃的黑铁矮人！他们怎么敢闯入我们美丽的山谷？！好像他们的家乡山地还不够好，不！他们就是控制不住自己，夺取了我如此努力管理的美妙采石场的控制权。哦，光是想想就让我很生气！你！拿起你的武器、法术或任何你用来杀戮的东西，去东北方的舍伍德采石场。我要你消灭那里的每一个害虫，并让他们遭受和我的下属同样的痛苦。他们不会逍遥法外的！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41688, '你好，$C。您在安伯伍德城堡过得愉快吗？我和我的贵族同僚有太多问题需要解决，所以目前我们只能提供最低限度的款待。不过，您看起来很活跃，有兴趣帮忙吗？我保证，这值得您的付出。$B$B我的名字是约瑟芬·米登霍尔，我负责管理北风领的农业设施，主要是米登霍尔马场和克劳福德酒厂。米登霍尔马场正因骑士锦标赛和丢失的马饲料忙的不可开交。他们必须从西部荒野订购高质量的马饲料来照顾所有参赛者的马匹，以确保比赛当天能够达到最佳条件。令我沮丧的是，这批饲料被在南部赤褐森林中游荡的豺狼人偷走了，给我的下属带来了巨大的压力。请把马饲料拿回来，带给马场的养马人格林特。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41689, '<那只虚弱的鸭子靠在洞壁上，鸭嘴吐着气，发出微弱的叫声。从翅膀上的红色污渍来看，它遇到了一次小冲突，可能是为了逃离生活在格里门湖周围那些嗜血的鱼人。为了安慰受伤的动物，你向它的小身体伸手。小鸭还很害怕，它尖叫着，惊恐地拍打着翅膀。血溅在地上。如果不先让它平静下来，治疗伤口就很难。也许你可以沿着河涧和格里门湖周围的海岸收集一些蔬菜来与它交朋友>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41690, '<虽然野菜和绷带确实起到了帮助作用，但这只鸭子似乎并没有完全恢复。它的脚摇摇晃晃站不稳，在想离开洞穴时会翻滚。你觉得不能简单地把它留下，应该去北风领找个能照顾它的人。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41691, '北风领是许多各式草药和植物的家。暴风王国的人们很久以前就学会了利用这些产出，并长期使用它们。看着他们通过反复试验获得知识真的很有趣。$B$B为了帮助你嘎嘎叫的小朋友，我需要你为我摘几株冬吻草，一朵开着鲜艳白色花朵的花。它是冬刺草的远亲，如果处理得当，它可以迅速止血和感染。$B$B这种花生长在这里的东边，沿着白雪皑皑的山脊向北生长。为了做有药效的药膏，还需要琥珀汁。居民喜欢赤褐森林的汁液，其中一些汁液粘在它们的皮毛上。帮我收集这个，小家伙应该会安然无恙。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41692, '很高兴有更多的人加入。肖尔并没有派出一整个团人马到这个被诅咒的岛屿上，这意味着我们只能利用手头的人手。我们目前的主要目标是侦察该地区并找出暴掠部族在做什么以及为什么。我们还没有在该地区遇到任何兽人，这意味着我们在线索上有点少。幸好我们现在有你陪着我们。$B$B到达这里后不久，我们派出了一个侦察队到主岛上调查港口废墟是否有任何可疑活动。真的，可能会非常可疑。我们已经几个小时没有收到他们的消息了，这不是个好兆头。我需要你在俯瞰微风港的废墟的高原上检查他们的情况。如果有生还者，就帮助他们。如果不是......了解发生了什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41693, '<该日志专门列出了该小组在高原驻扎的几个小时内的目击报告、观察情况、轮班时间表和奇怪的事情。尽管已经见过几个过去居民的幽灵，但没有任何信息与北风领的失踪有关。虽然看到峡谷对面的城堡废墟冒出浓烟，但尚未进行侦察尝试。此外，萨尔部落的一小支部队似乎已经在其中一个较小的岛屿上定居。无论他们在这个岛上计划什么，目前仍然是一个难题。$B$B这本书的最后一页描述了调查悲痛湖旁废弃旅馆的准备工作，就在这片高原的脚下。也许你可以在那里找到幸存者>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41694, '我的小队由十名特工组成，调查蛙鸣高原周围的周边。在少数幸存者中，我是唯一一个被关在这家旅馆里的人。我不知道是什么原因。然而，我能看到的是我的三个战友——弗林、埃尔罗伊和切瑞丝——被拖过战场到这里的南部。幸运的是，我听懂了他们说的一些兽人话。“洞穴”、“山”和“主人”是我能从他们的演讲中破译出来的。可能不多，但我想总比没有好。很抱歉，但我不会对你造成这些伤害提供太多帮助，我会向基里安特工报告，告诉她发生了什么，我要应付的太多了。我祈祷你能发现更多并安全返回前哨站。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41695, '军情七处在其组织内拥有许多专业力量：侦察特工、间谍、爆炸物专家、战地医务人员、档案员......诺普西·斯皮斯潘就是这样一位档案员，他的目标是记录大规模行动期间发生的一切。因此，他精通许多才能，翻译就是其中之一。您可以想象，有人可以为您破译敌人的情报是多么有用。把卷轴递给他，让我们看看那些神秘的混球在做什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41696, '<诺普西打开卷轴，扫视着旧羊皮纸的表面。皱起的眉毛表明这份文件可能比预期的要难。>$B$B好一个难题，它不仅是兽人语言，而且编码方式对于兽人信件来说也很少见。我需要一些时间来破解代码并进行翻译。幸运的是，您不必坐在这里等我说完。我敢肯定这卷轴不是同类作品中唯一的。肯定还有其他类似的，在巴洛的暴掠部族兽人之间流传。如果我能看到到更多这类文件资料，这将大大加快翻译过程！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41697, '我哥哥诺普西有点古怪，即使在我们这些侏儒中也是如此。他对所有学术事物的狂热推崇使他出名——或者更确切地说是臭名昭著——甚至早在诺莫瑞根就出名了。我不太确定我是否应该赞同你培养他的痴迷，但即使我也无法否认他的技能帮助我们解决了比预料的更多的工作。$B$B当你在外面搜寻岛上的兽人书籍时，我有一份工作给你。我们的特工在巴洛的另一侧找到了一个洞穴，里面充满了各种令人不安的恶魔。好像兽人还不够，他们继续着与恶魔力量交流的习惯。我希望你潜入洞穴，消灭任何可能的杂兵，减少他们的数量。我们要对付的数目越少越好。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41698, '<鲁夫斯打开一个装满黑火药的小锡盒，然后用他的大鼻子深深地嗅了嗅。他满意地叹了口气。>$B$B别让基里安知道我把这个藏起来了，不然我又要上厕所了。真是一团糟，我告诉你！我听说善良的老诺普西请求你的帮助？你不介意我也请你帮个忙吗？信不信由你，但军情七处不仅仅完成无声的工作。不不。渗透和破坏是相辅相成的，如果你想看到事情蓬勃发展，我就是那个男人。巴洛岛的旧防御工事大多破旧不堪，但仍然为我们的敌人提供了显著的优势。将这些放置在破损的哨塔附近及其在旧战场的营地附近。一旦时机成熟，他们就会做好准备！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41699, '<侏儒迷失在深沉的沉思中。他的眉头紧皱，脸上刻着坚定的表情。>$B$B哦，$N！抱歉，我疯狂的想法让我没有意识到你回来了。我刚刚解密完你在那个恶魔洞里找到的卷轴和石板。我发现的是......嗯，轻描淡写地说，很可怕。$B$B你在那个暴掠死灵法师上找到的卷轴上写着对他们的俘虏进行的异常实验。他们中的许多人是“不合适”的，导致——如果我翻译正确的话——液化。同样令人震惊的是我姐姐尼普西递给我的石板里的东西。恶魔的计划是帮助暴掠兽人召唤一个具有无比强大力量的恶魔——他们称之为莫格赛德。我估计他们需要大量的精力才能完成这件事...$B$B$N，请将这份报告交给基里安特工。如果我对情况的理解是正确的，而且我确信它是正确的，那么我们不能再拖延了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41700, '我们的舵手维里克斯带领我们越过这个岛屿，没有意识到我们将直接飞入雷暴的马蜂窝。我会诅咒他去安德麦的贫民窟，但如果要算责任，是我允许他改变航向的。所以我有责任把我们大家带离这个可恶的岛屿。然而，我的指南针丢了，我们几乎没有机会逃离这种坏天气并返回藏宝海湾！$B$B假惺惺的毒蛇维里克斯把它带走了，实际上就是把我们当成了人质。他似乎很了解这个岛屿，因为他喋喋不休地说着在废墟中沉睡的无尽宝藏。坦率地说，如果我们的情况不是那么糟糕，我会陪他一起去，但我的船员的生存是首要任务。他的日记里提到了一个充满黄金的墓穴，去找他并把我的指南针带回来！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41701, '我问你一个问题：你见过比你大两倍的龙虾活生生地吞食地精吗？或者见过在陆地上行走的鱼人啃着哪个倒霉蛋的头吗？如果见过，那么你肯定会和我一样对这些深海怪物怀有强烈的仇恨。鱼人、龙虾人、娜迦，随便什么都可以，我甚至在荆棘谷的暗礁群里被蚌吃掉了一个很好的商业伙伴！命运好像在和我们这些不幸的船员开着肮脏的玩笑，我们被困在咕噜咕噜的鱼头和它们嘎吱嘎吱的邻居之间的地盘争夺战中。我想说，如果他们没事可做，就让他们自己打个头破血流好了，但他们开始侵占我们的营地，我们太累了，修不好飞艇，没法再抵挡他们了。$B$B我看到你眼中的怒火，朋友。出去清理这个地方吧，这里东南方的海里应该有足够多的鱼。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41702, '在你忙着处理这个小麻烦的时候，瑞琪例行巡查回来了。她注意到我们小岛北边有可疑活动。水波荡漾，海浪高涨，海面上形成湍急的漩涡。我最确定的是，那一定是一只拥有强大魔法的龙虾，甚至可能是它们的首领。巧合的是，从这里东边的岛屿外也可以看到类似的东西。说我多疑吧，但这些都是鱼人和龙虾在这场地盘之争中大打出手的迹象。$B$B不管是什么，它们都对我们的逃跑构成了威胁。$N，如果没有人阻止它们，我们逃离这个岛屿的机会就很小了。你已经证明自己有能力对付这些小鱼了，你认为你准备好面对更具挑战性的敌人了吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41703, '我们正在全力修理飞艇，尽可能地利用手头现有的临时材料。不过，我怀疑我们能否凭借目前拥有的材料走得更远。不管是运气不好还是运气好，我们小岛东边就有一艘海盗船。我不知道他们来这里干什么，但考虑到他们是海盗，我只能假设他们来这里是为了战利品。让我们充分利用他们吧。像他们这样的船看起来塞满了补给品和必需品，我们可以用它们来改善我们的生活。虽然我敢肯定他们不会心甘情愿地放弃他们的财物，但你可以强行让他们改变主意，你不觉得吗？$B$B<凯克斯克用咄咄逼人的眼神示意了你一下。>$B$B你出去的时候，能不能顺便去藏宝海湾找我们的承包商要一个备用的飞艇引擎？我确信如果我们能从这里离开并送出他的货物，这对他最有利。他的名字是玛科尔·斯麦瑟，他应该在码头的港务局附近。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41704, '与我不同，我的仆人们并不知道他们可怕的状况。甚至连我妹妹的意志也慢慢地迷失了。农民和工人开始漫无目的地在岛上游荡，执着于他们活着时做过的一切。一个无尽的炼狱，无法进入来世。作为他们的领主，我有义务把他们从那个地狱中解救出来，但我做不到。$B$B我谦卑的请求您，善良的旅行者：净化他们的幽灵之躯，让他们的灵魂回归圣光。看到他们还在受苦，我很痛心。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41705, '<你面前的女人几乎一动不动地躺在你面前。她瘦弱的身体令人毛骨悚然，伴随着沙哑而不规律的呼吸。她瘦骨嶙峋的手紧紧握着一块粘土，粗糙地塑造成一个人形。就在它旁边，原始的符号被画在教堂地面上厚厚的灰尘上。从你能解读到的来看，它们描绘了两个人形生物，一个比另一个大。一条线将这些图形连接到另一幅图画上，曲线上有一个凹凸不平的圆圈，在它下面，许多十字架疯狂地散落在尘土中。你记得在山上俯瞰荒凉的战场，隐约可见一个洞穴。$B$B你很清楚她活不了多久了。也许你可以在那个洞穴里找到一些东西来抚慰她最后的时光。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41706, '自然与你同在，旅行者。在这个岛上找到另一个志同道合的人真是太奇怪了。我以为只有奥尔米尔和我停泊在这些悬崖上。让我介绍一下自己：我的名字是梅森德拉·枭爪，我是塞纳里奥议会的德鲁伊，正在为我的杉多（达纳苏斯语：尊敬的老师）鹿盔执行任务。凭借他无穷的智慧，他感觉到一股可怕的黑暗从这个小岛上弥漫而来，他最后一次感受到这种黑暗是在卡利姆多的第三次战争期间。在我们在这里的短暂时间里，我注意到当地野生动物的可疑行为。尽管生活条件恶劣，但它们表现出不同寻常的侵略性，并经常撕扯周围。有什么东西在折磨着它们，我们必须找出原因。$B$B让这疼痛的动物摆脱痛苦，找出这种痛苦的本质。希望这能揭示出它们身上发生了什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41707, '疾病和病痛在这个岛上肆虐。各种疾病的大熔炉，加上从让人厌恶的土地冒出的反常的黑暗迷雾。我们的特工开始因此患病。高烧、起疹子、内脏和肌肉的剧烈痉挛。作为探险队的医生，我要消除他们的症状，我希望你能帮助我。$B$B我推测，其祖先来自岛上大气中弥漫的微小蘑菇孢子。我猜多年来，地下生长了大量有毒蘑菇，现在它们的孢子正在繁殖。据我们的侦察兵报告，其中一些甚至以可怕的孢子兽的形式复活，在一个废弃的矿井里，在荒凉的战场对面。为了消除这些症状，我需要最有效的孢子，我相信可以在它们身上找到。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41708, '我尊重特工基里安作为我们的领导者，就像尊重这个前哨站的任何人一样。她的步驟有条不紊，在特遣队的安全和任务成功之间取得了很好的平衡。她不怕亲自参与行动，这种恐惧让我想起了在卡利姆多的同胞。她建议我们利用巴洛独特的环境和情况，我非常乐意遵从这个命令。当我早些时候搜索岛屿时，我目睹了一个迷人的场景。其中一个恶魔般的兽人试图与北方的当地蜘蛛种群发生冲突。她被咬了一口，很快就变得昏昏欲睡，直到她成为容易上钩的猎物。这些蜘蛛一定拥有一种非常强效的毒液，具有麻醉和麻痹作用。如果我们能提取它，它将为我们在巴洛的战斗提供充分支持。把它们的毒囊带给我，同时减少它们的数量。它们可能对我们有用，但仍然是一种危险。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41709, '巴洛岛的风暴让我着迷。在达文堡逗留期间，我偶尔能够凝视远方，看到厚厚的云层笼罩着岛屿，就像一层痛苦和阴郁的外衣。我召集了我的水术师同伴，并提出了一些关于这种不自然现象的原因的理论。我们以前从来没有机会安全地探索这个岛屿，然而随着军情七处的探险队来到这里，这样的机会出现了，我自然自愿帮助他们。$B$B近距离感受风暴让我意识到它肯定不同于我们在库尔提拉斯大海上遇到的大风。此外，我开始观察当地的鱼人，因为他们似乎拥有某种与我们水术师类似的潮汐魔法。$N，寻找唤嘲鱼人，看看他们是否拥有任何不寻常的东西。我们最近的报告说他们聚集在西北岛屿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41710, '你发现的珍珠拥有潮汐之力，这意味着它的存在可以控制海洋的流动和气温。鉴于它已经严重受损，这就可以解释为什么这里的风暴如此肆虐。在这个荒岛上看到这样珍贵的遗物真是太迷人了。它一直都在这里吗？不过，我们可以稍后再考虑这个问题。首先，我们需要平衡珍珠中猖獗的能量。$B$B我可以用咒语来减弱珍珠的肆虐力量，但我需要一些材料。一块反光水晶，多面且锋利。荆棘谷北部河流附近的石喉蜥蜴随着年龄的增长会形成这些石头。把你能找到的最大石头带给我。我还需要我的旧法术书，我把它送给了希尔斯布莱德丘陵南海镇的好朋友博学者迪布斯。告诉他是我派你来的，他会很乐意把它还给我。为了完成所有事情，还要给我带来三份强效星界精华。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41711, '<芬尼根把试剂放在他面前的桌子上。背诵他旧日记中写的咒语，你可以感觉到空气中弥漫着你在荆棘谷找到的水晶周围的微弱能量。它开始发出各种色调的蓝光，在黑暗和明亮的光线之间变换。水术师最后动了一下手，完成了魔法，水晶现在静静地躺在那里，完美和谐地嗡嗡作响。>$B$B完成了。快点，拿起水晶，把它放在西北岛屿上破碎的珍珠附近。水晶自身的和谐能量应该足以平息珍珠的狂暴能量。当心可能发生的事情，潮汐魔法是不可预测和难以驯服的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41712, '<你在马厩阁楼里，发现了一具藏起来死者的遗骸，它破碎的骨头告诉你它已经很老了。旁边是一张纸，同样古老，但仍然清晰可辨，可以辨认出上面的内容。读着它，他准是在逃进这个马厩之前随带着的。也许这么多年过去了，你还是能把它送到收信人手上。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41713, '你能想象比意识到自己永远不死更痛苦的事情吗？被束缚在这座被诅咒的塔上直到时间的尽头？我当然不能。我们注定要永远研究奥术的奥秘，我们中的许多人已经失去了理智。谁能责怪他们呢？人们会认为这是摆脱这种孤寂的简单方法。但我不是一个屈服于捷径的人。以我作为一名学者的骄傲，我将摆脱这座尖塔的魔法束缚，而你会帮助我。$B$B搜索图书馆。这座塔的疯狂主人有一本书名很引人注目，这是一本厚重的书，我需要你找到。“奥术共鸣的解决方案”，这就是我需要的。把它带给我，我们最终将能够摆脱这个永恒的枷锁。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41714, '从这里的情况来看，需要大量的奥术能量来打破将我们束缚在塔上的约束。只要有合适的材料组合，我就能创造出一种足够强大的能量源来打破我的永恒锁链。$B$B听着，我再次需要你的帮助。收集以下能量源并将它们带给我。我会念出咒语，希望能一劳永逸地解除束缚。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41716, '我们在碎刃哨岗的情况岌岌可危。我们远离家乡，我们的补给线非常薄弱。这当然不是任何战士或任何前哨的理想情况。$B$B我的顾问拉纳格掌握了最新的信息。如果你真的想在这里帮助我们，就和他谈谈，他会告诉你一切。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41717, '我们最大的威胁是龙喉部族。他们人数众多，力量无时无刻不在。就在最近，他们袭击并摧毁了巴格斯之墙。这是丹基塔斯矮人的主要防御工事之一。$B$B我担心，有了这次胜利，他们的行动会变得更加大胆。$B$B我们必须发现他们的未来计划。我需要你前往西南方向的巴格斯之墙，找到袭击者的龙喉命令。我确信他们中有人拿到了。$B$B当你找到命令后，就回来找我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41718, '这些计划详细说明了对丹基塔斯的进一步攻击，但更重要的是对碎刃哨岗的攻击。这些计划似乎是由龙喉头目之一的格什甘·黑洞协调的。$B$B把这个信息带给指挥官阿格纳什，他会决定我们的下一步行动。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41719, '格什甘·黑洞，这个名字我很熟悉。$B$B当我们第一次到达冷酷海岸时，我们对龙喉部族进行了一系列调查。格什甘是一位忠诚的指挥官，他指挥着一支技术娴熟、身经百战的战士队伍。是时候阻止他的计划了。$B$B格什甘潜伏在西北的斯托尔加兹要塞废墟中。我建议你带上盟友，因为那个被遗忘的地方到处都是龙喉氏族的战士。杀了他，把他的头给我当证据。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41720, '我听说你打算勇敢地前往斯托尔加兹要塞，如果你真想去，我有一个任务需要你注意。$B$B很久以前，斯托尔加兹要塞曾是冷酷海岸的中心。它对外投射武力，并保存着许多重要文件。$B$B我需要的就是这些文件，我相信我能在其中找到一些有用的东西。前往西北部的斯托尔加兹要塞，找到一箱这些文件。把它们带给我，我会奖励你的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41721, '战斗的时刻已经到来，英雄的时刻已经到来。现在是打击敌人心脏并粉碎他们的时候了。西北部的扎姆盖斯要塞是冷酷海岸的龙喉氏族的总部。在那里我们将获得胜利。$B$B前往那里，以部落的名义杀死他们！让他们知道我们的愤怒，等他们被屠杀后再回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41722, 'Lok\'tar、朋友！我是巴戈尔纳克，我负责镇上的烹饪。如果你对边境地带有所了解，你就会知道事情会变得相当乏味。$B$B我的工作是为驻扎在这里的人提供一些变化。你会惊讶地发现，改变膳食对士气的影响有多大。$B$B我唯一可用的口粮是肉，我想要一些变化。$B$B你应该能在冷酷海岸周围找到很多棕色隐匿者，如果你能收集六条隐匿者腿，那将对我有很大帮助。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41723, '碎刃哨岗北部狂暴的野喉雪人已经发展成为比以前想象的更大的威胁。他们的敌意和位置对我们在此地区的行动构成了威胁。$B$B任何以部落的名义提供服务的人都会获得赏金。减少野喉雪人的数量，这样他们的数量就不会对远征队造成真正的威胁，完成后去碎刃岗哨寻找卫兵莫尔坎领取奖励。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41724, '我们曾经在碎刃岗哨有一位术士，他是一个讲究荣誉和忠诚的术士。实际上，他的忠诚对象是龙喉氏族。$B$B这个兽人名叫雷斯卡格·沼牙。一个真正卑鄙无耻、没有骨气的生物。我帮助他找到了一件传家宝，帮助他找到了安宁。几个月来，我甚至把这条虫子当成了好朋友。$B$B他的行为比我所受的任何伤害都要伤人，现在我要他的血。你可以在西北方向的盖斯卡尔的塔上找到他，俯瞰着这个地区。杀了他，然后回来找我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41725, '呸，这个地方的情况几乎无法挽救了。我被委派成为一名攻城工程师，但没有实际的机械或零件？$B$B我唯一需要修理的设备是两台缴获的龙喉投石机。如果我要创造或处理任何东西，我需要即兴发挥。$B$B南部附近的矮人挖掘地最近被黑铁矮人占领。如果他们知道什么，那就是他们的恶毒的装置和工程。$B$B希望你前往这里南部的格罗丹挖掘场，找到他们可能闲置的任何黑铁零件。它们在我手中比在我们的敌人手中更有用。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41726, '现在我已经找到了一些部件，我想弄到一些更复杂的部件。不久前，在丹基塔斯的矮人和龙喉兽人的战争中，许多蒸汽坦克被摧毁。这些曾经强大的机器现在闲置在西部和西南部的乡村，锈蚀着。$B$B如此复杂的工程不是我能在现场复制的。从该地区的残骸中找出六、七个这种精密零件，我会确保你得到丰厚的回报。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41727, '你在这，$c。我需要帮助完成一项对部落至关重要的任务，这项任务可以确保我们在冷酷海岸的优势地位。该地区潜藏着一种潜在的力量，我渴望将其据为己有。$B$B要利用这种能量，需要具有魔法活力的天然材料。我需要你收集附近被迷惑的龙族的血液。这些生物在龙喉氏族的控制之下，可以在这里的西南部找到。收集他们的血液，然后把它还给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41728, '如果我真的想吸引这个地区的魔力，我需要一系列天然材料来增强我的能力。我们真正的工作还没有开始，但我们必须做好准备。$B$B需要一些来自燃烧军团恶魔的邪能，我知道他们在凄凉之地，去那里找他们吧。$B$B最后，我需要蜥蜴的鳞片，更确切地说是晶背蜥蜴。这种稀有品种可以在荆棘谷的野人海岸找到，去寻找它们，然后为我收集一片鳞片。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41729, '在我们的任务完成之前，我还需要最后一种材料。在这个地区的南部有一个叫“冷酷谷”的地方。这是一片荒凉、腐朽的土地，被一种黑暗的未知力量所扭曲。$B$B我所寻求的正是这种力量，矮人的灵魂现在在山谷中徘徊，他们可以获得这种力量。杀死他们，并从他们的遗骸中取回黑暗精华给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41730, '所有材料都已收集完毕，我们的努力已达到顶峰。如果我们想真正利用这种能量，我们必须首先找到合适的容器来容纳它。$B$B很久以前，古尔丹和他的爪牙将一块蕴含巨大能量的宝石带到了这个世界。尤索克的坠饰后来被留给了古尔丹的副官之一欧鲁诺克·裂心。我要找的就是这个坠饰。你可以在巴洛岛的风暴废墟深处找到他。这不是一件容易的事，但我希望你杀了他，并把尤索克的坠饰的力量带给我。$B$B如果你做到了，你就会得到回报。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41731, '现在你已经找回了尤索克的坠饰，我可以开始施法了，请退后，等我完成仪式。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41732, '<一件完美且古老的遗物展现在你眼前。它包含着复杂而古老的机制，让你无法理解。这件物品看起来是经过精心设计和制作的。你应该找一个可能对这种物品熟悉的人。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41733, '你带给我的这个遗物可能与源自奥达曼的技术以及曾经建造它的那些人有关。这个遗物来自冷酷海岸，这令人惊讶，只留下更多的问题。$B$B如果我们想要重建这个遗物的功能，我们需要一些曾经为这个装置提供能量的魔法。据我所知，这样的力量只有在奥达曼本身存在。$B$B我建议你召集一个队伍，深入探险。从奥达曼内部带给我一个远古能量模块，以及从一位工程师那里拿到一个黄金能量核心。一旦这些物品到手，我会尽力修复这个遗物。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41734, '<一件完美且古老的遗物展现在你眼前。它包含着复杂而古老的机制，让你无法理解。这件物品看起来是经过精心设计和制作的。你应该找一个可能对这种物品熟悉的人。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41735, '你在那儿，是否想去碎刃哨岗？如果是的话，我有个好朋友住在那里，我相信他一定会需要一个帮忙。巴戈尔纳克是哨站的屠夫，负责烹饪，他总是希望能获得新鲜的肉类。$B$B如果你能帮我一个忙，从当地的石皮野猪那里带回八块石皮胁腹肉，我相信这对他意义重大。你可以在东边找到碎刃哨岗，收集胁腹肉，然后把它们带给巴戈尔纳克。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41736, '几个月前，我和莫唐来到这里，研究冷酷海岸的元素。正如你所见，我现在独自在这个任务中，因为莫唐已经迷失在追求力量的道路上……$B$B<耶赛格叹了口气。>$B$B这片土地本身在哭泣。我能感受到这里元素的痛苦，并希望能为它们提供帮助。如果你愿意帮助我，我需要岸根草，这是一种生长在这个地区的本地草药，收集八捆后再回来找我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41737, '如果我们想真正理解在冷酷海岸的腐化程度，我们必须获取一些样本。这种污秽能量的表现形式已经以软泥怪的形态在这片土地上扎根。我请求你从冷酷海岸的恶心的软泥怪身上带给我六份残余腐败。在这里东北方的布兰加之愚处可以找到它们的聚集地点。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41738, '情况如我所担心的，土地腐化，处于动荡之中。我需要尽快与元素沟通。$B$B这个仪式需要当地的自然材料来进行。首先，我需要从附近的长尾龙那里获得五根华丽的羽毛。然后，从西北方向的龙喉缚火者那里获取三股束缚之焰。最后，我需要一份来自年迈的石皮野猪的纯净的石皮之心。收集好所有这些材料，归来见我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41739, '达格诺斯之焰？元素给了我们一条非常关键的信息，但我对此一无所知。我能想到的只有一个人可能知道这神秘火焰的真面目。多萨斯·瑞德$B$B。他是一个人类，正在穿越冷酷海岸。上次我和他交谈时，他似乎对这片区域颇为了解，我猜想他也对这火焰略知一二。在西南方，冷酷海岸入口附近找到他，询问达格诺斯之焰的情况。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41740, '如果说我在艾泽拉斯学到了什么，那就是凡事皆有代价。如果你想知道达达格诺斯之焰的信息，我需要你证明你是站在我这边的，而不是伪装的敌方特工。$B$B这听起来像是一个公平的妥协，对吧？$B$B我要你前往西南方的荒芜之地，在莱瑟罗峡谷找到黑龙一族的踪迹。我听说他们的鳞片被施了魔，蕴含着潜在的龙之能量。从“滚烫的雏龙”那里带给我一块这样的“附有魔法的幼龙鳞片”，你就能得到你想要的信息。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41741, '达格诺斯之焰是矮人魔法中一口古老、近乎古老的源泉。这火焰很久以前就被点燃，作为纪念亡灵的传统。$B$B然而，这曾经光荣的火焰如今已被扭曲腐化。$B$B达格诺斯之焰至今仍在冷酷谷深处燃烧，唤醒古老的灵魂。$B$B把这个信息带给耶赛格，或许他能想出净化邪恶的方法。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41742, '做好准备，真正的挑战终于到来了。如果我们要给元素带来和平，就必须驱逐被达格诺斯之焰束缚的邪恶。它的毒性持续太久，给所有人带来了巨大的破坏。$B$B找到达格诺斯之焰，并将这团魔法粉末撒在火焰上。它应该会显现邪恶的能量，请让它被永远、彻底的摧毁，请做到这一点，为了所有元素的美好，为了这片大地本身的美好。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41745, '听好了，年轻的$c，我传授的智慧源自森林深处，源自风的低语。小心谨慎，艾露恩之镰是一件强大的神器，它的力量与我们世界的命运息息相关。以崇敬之心握住它，以你的智慧去运用它，因为它的影响超越凡人的领域。守护它，避免神器落入那些为私利而追求力量的人手中，因为在他们手中，它可能会给我们的土地带来无尽的灾难。$B$B让我们开始吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41746, '几周前，阿祖拉之塔代表肯瑞托的法师们进行了奥术特性的研究。不幸的是，这项实验以奥术能量过载而告终，这些能量现在已经显现在附近的树林中。$B$B你有没有注意到现在在塔周围森林中游荡的元素？如果你能帮忙，我们需要消灭它们。在情况失控之前，把它们的残渣带给我们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41747, '我曾是阿祖拉之塔法师的学生。正是在那里，我学到了很多技能，并练习了我的奥术技能。多年来我一直与他们保持联系，并经常将羊皮纸运送到塔里。他们练习各种法术和咒语时，似乎用得不少羊皮纸！$B$B<扎尔迪玛轻声笑了笑。>$B$B我需要有人帮我运送卷轴，因为我现在因为学业需要待在闪金镇。你可以在水晶湖东边找到阿祖拉之塔。这座高塔应该很容易找到。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41748, '许多年前，我收了一个学生为徒，教他们奥术的秘密，并驾驭他们的思想，成就更伟大的事业。拉尔萨斯是一位才华横溢的学生，注定拥有光明的未来。他本可以精通奥术，甚至有朝一日掌控阿祖拉之塔。$B$B想到他们的心智已被愚蠢的权术和怒火所毒害，我感到痛心不已。如今他们肆意妄为，将我们的秘密传授给任何暴徒和骗子，让他们掠夺弱者，扰乱艾尔文的和平。$B$B必须阻止拉尔萨斯，如果我亲自面对他，我会心碎的。我请求你击败他。我听说他经常潜伏在东北方的石碑湖附近。把他戴的项链带给我，这样我就知道他对艾尔文森林的恐怖已经彻底平息了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41749, '我能和你聊聊吗？你看起来像个随时准备行动的硬汉，寻求冒险的刺激以及黄金和财富的气息。就目前而言，你正是我要找的那种人。你看，任何一个有自尊心的地精，在谈及潜在收入时，都会有很多人脉；有些更合法，有些则不然。我的很多承包商都属于后者，而且有一伙人对一些你平时碰不到的东西很感兴趣。$B$B在东南方，洛克莫丹过来的大瀑布附近，有一处古老的采矿设施，现在人们称之为龙喉居所。里面，据说还有同样古老的傀儡在那些不稳定的大厅里游荡，仍然被古老的协议所控制。如果你能给我一块驱动它们的符文石，我可以给你一个合理的价钱！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41750, '<豺狼人怒不可遏，口水横流，獠牙外露，从他鼻孔喷出的空气在沼泽潮湿的空气中清晰可见。>$B$B叛徒！孤峰大叛徒！和萨满沼爪走了。他们领导着藓皮部族！帮助过孤峰，我们忠诚。现在我们孤零零，在这里等死！叛徒与强大的绿皮战士同行。向东南方，进入群山中的一个洞穴，一个大洞穴！冷酷之咬想要叛徒的头！跟着他们，进入指挥喷火蜥蜴的绿皮战士的家园！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41751, '凡人，屈服的困境再次降临到我的族群头上。过去的恐怖再次笼罩着红龙女王高贵的族群。兽人龙喉氏族继续对我的种族施加令人发指的压迫，强迫他们听从他们的命令。红龙军团正全力守护着格瑞姆巴托，而我则有责任释放我死去的兄弟希瑞斯塔萨和他的子嗣。$B$B我能听到他痛苦的哭喊声回荡在南面古老的矮人矿井中，那里如今已被龙喉氏族占领。凡人，前往龙喉居所，赦免我兄弟和他的子孙们所犯下的罪孽。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41752, '我这辈子都是个懦夫，并非母亲希望我成为的那种战士。伟大的落锤防御者们屹立不倒，毫不留情地对抗着我们的敌人，而我却选择了一条不同的道路。砍杀敌人或许光荣而令人满足，但看到敌人仅仅因为一滴毒药就痛苦地扭动着身躯，更令人着迷。我的族人中没有多少人有这种感觉，我也不能责怪他们，但我来这里并非是为了无用。只要我能为部落贡献一己之力，就没有人能阻止我效忠我的大酋长。$B$B在我寻找新的、更丰富的毒液的过程中，我偶然发现了一条非常有趣的信息。邪恶的古代兽人——龙喉氏族——在格瑞姆巴托地下的矿井中奴役了一群蜘蛛。他们运用黑暗魔法，将这些蜘蛛的力量提升到了深不可测的程度。这些蜘蛛体内一定蕴含着无与伦比的剧毒，所以把它们母蜘蛛的毒囊带给我吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41753, '黑暗女王的野心浩大而复杂。在复仇之路上，她会不惜一切代价，使用一切可以利用的工具。因此，一些强大的遗物引起了她的注意；这些遗物将成为她密谋的关键之一。$B$B兽人将他们古老魔法的秘密深藏不露，不让那些能更好得利用​​他们原始巫术的人发现。其中之一就是永恒之火，它是一种强大的能量源泉，由他们的焚化大师们守护和滋养。黑暗女王渴望得到这件神器，而你将满足她的愿望。$B$B在遥远的南方，在卡兹莫丹次大陆（东部王国大陆的三部分之一,范围从燃烧平原往北一直到湿地）的矮人居住的湿地，你会发现一个名为“龙喉居所”的耗子洞。它是格瑞姆巴托那被诅咒的山脉中一座废弃的采矿设施，居住着古老龙喉氏族的疯狂残党。潜入他们那可怜的藏身之处，把永恒之火交给我，由他们的护焰者守护。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41754, '<你手中拿着的石碑上刻着你从未见过的符文和雕刻。这些文字和线条看起来几乎像是一件古老的艺术品，但你却无法理解它们刻在石头上的含义。考虑到它的起源以及你面前幽灵般的矮人遗存，这肯定是一种早已被遗忘的矮人印刷术。或许铁炉堡的伟大历史学家们能从中找到答案？>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41755, '$N，红标家族内部处理此事才是公平的，就像我的好奇心驱使我与同事分享一样。来，把石碑带回去，送到那边秘法区的红标家族庄园。他毕生致力于延续家族血统，了解这段矮人历史对他最有利。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41756, '即使在格瑞姆巴托惨败多年后，四散的龙喉氏族依然对我们的土地构成威胁。他们卑鄙的战士们在南部山区肆虐，而他们的主要力量则藏匿在遥远东面的一个旧矿场中。我们的报告称，凶猛的兽人聚集在破旧的大厅中，实力日益增强。其中最引人注目的是他们的老兵，他们是第二次战争中经验丰富的生还者，为了满足他们疯狂的主人的要求，他们会不择手段。他们是他们军队的骨干，如果我们想在他们面前有一丝机会，就必须将他们消灭。$B$B 进入我们现在称为龙喉居所的矿场，削弱他们的队伍。越快越好。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41757, '$N，既然我们已经解决了纳克罗什和他的残部，我们就可以集中精力对付更大的威胁了。纳克罗什在这场游戏中只不过是一颗棋子而已；虽是一枚强大的棋子，但终究只是一颗棋子。我们好心的民兵们一直在谈论一个可怕的龙喉兽人，他是过去几周来愈发频繁的凶残劫掠队伍的头目。一个彻头彻尾的怪物，绑架并杀害米奈希尔港的可怜居民。我要他死，越快越好。消灭纳克罗什为我们争取到的一点时间，可以准备对他们的行动基地发动反击。$B$B潜入远在东方的格瑞姆巴托山下的龙喉居所，砍掉那个卑鄙怪物的头颅。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41758, '野猪人是一个蛮荒而充满敌意的种族，他们与我们之间冲突的时间比我记忆中还要久远。无论野猪人走到哪里，他们总是会编织出巨大而沉重的荆棘丛。正是这种魔法扭曲了自然秩序，使其更接近腐化。几个月来，我一直能感​​觉到一些诡异而陌生的东西。$B$B我正在寻找这种自然腐化的证据，我确信它就藏在剃刀沼泽的深处。找到这种扭曲自然魔法的活生生的化身，并将其摧毁。任务完成后，回到我身边。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41759, '你好，旅行者，我是卡拉兰·风行者，来自达纳苏斯的德鲁伊。我一直在研究野猪人家园深处最近的动乱。我听说过一些关于扭曲荆棘和自然能量的怪物的故事。我确信这些生物已经和它们的野猪人主子翻脸了，而我正寻求恢复自然世界的秩序。这些自然生物必须被安抚，我希望收集它们的根须进行研究。$B$B深入剃刀沼泽，找到这些怪物并消灭它们。你可以在东边巨大的升降机上方找到这个被诅咒的巢穴，登上顶峰后，向西走，寻找野猪人。帮我收集三根扭曲的根须，我会好好奖励你的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41760, '巴洛家族统治这座岛屿多年。即使在沦为附属国后，暴风城的国王仍然让第一任公爵来统治这个他饱经风霜建立的国家。他的子孙继承了他的遗志，每个人都以敏锐的洞察力和仁慈的灵魂统治着这个商业天堂。我们格拉汉家族是他们的顾问和保护者，我们为此感到自豪。因此，多年前辜负领主的巨大羞愧感依然萦绕在我的心头，这更令我难以承受。我或许无法改写过去，但我可以传承巴洛家族的荣耀。$B$B我的灵魂被束缚在这片土地上，所以我恳求你代我完成这项壮举。前往风暴城堡，寻找我老朋友的遗骸。他的骸骨或许早已在他那被诅咒的故乡化为灰烬，但他的印记戒指或许依然存在。去寻找它，把戒指还给我，这样我就永远欠你一份人情了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41761, '根据我从斯皮斯潘的调查结果来看，我认为我们现在要对付的不仅仅是暴掠兽人和他们的恶魔朋友。如此规模的行动对于一个在第二次兽人战争中四散奔逃的氏族来说太过宏大。这里肯定还有更多事情在发生。我们的下一步是看看还有谁会把他们脏手伸进这件事里来。登上岛屿，进入风暴城堡的院子，分散他们的兵力。搜索该区域，寻找我们可能遗漏的关键情报。打发掉你遇到的任何高级军官，我们必须迅速而致命。我本人将通知肖尔大师，召集尽可能多的特工。我个人并不指望国王会在这场悲剧中帮助我们。$B$B保持警惕，$C，我期待取得足够的成果。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41762, '嘿，嘘，伙计。钱快花完了？你当然快了，我懂你的表情。我给你找了个活儿，比给食人魔换尿布还轻松！听着，真的，不用问，我保证对你有好处。在西南山区，杜隆塔尔工会正在大规模地开采石油。要我说，这有点冒险；总之，我的客户对他们正在做的事情并不完全满意，而你就是阻止他们的人。拿着，把这些超载装置安到他们的泵站上。小心他们的工人，他们肯定会想办法阻止你。完成后，回来找我领取你辛苦赚来的奖励！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41763, '这些风险投资公司的老鼠到处都是！无论他们走到哪里，他们那肮脏的手都会攫取一切。无论是在石爪山脉、荆棘谷，还是在这里，没有人能逃脱他们的偷窃。在他们如此广泛的影响力下，诚实且不道德的剥削根本不可能进行。如果你问我，我建议他们是时候认清谁才是地精经济学界冉冉升起的新星了。$B$B不过，我们来谈谈真正的悲剧吧；我在海滩的石油钻井平台上工作的时候，把我那套……嗯，无价之宝的收藏藏在附近的仓库里，它们对我来说无比珍贵！这套独一无二的系列画作绝对不能被送到安德麦，在黑市上惨不忍睹的拍卖会上卖掉。快把它给我弄回来！我敢肯定，在我逃命的时候，那些暴徒肯定拿走了我箱子的钥匙！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41764, '问题接踵而至！我真不敢相信我竟然如此天真地相信工会不会有事发生，但你知道是怎么回事：祸从口出。现在我正忙着处理一堆未完成的工作；这些工作我得自己解决！老板真是个天才，我们欠她一大笔超额的配额，所以现在这么麻烦，我真是恼火！我们失去了对泵站的控制；不管这些风险投资公司的魔鬼干了什么，泵都彻底失控了，我们几乎没有机会停用它们来好好修理，因为那些油滴毁了我们的一天。不过既然你来了，运气又站在我们这边了！$B$B海滩那边是我们的大型石油钻井平台，在上面的控制室里你可以找到我的能量调节器。他们突袭的时候我不得不把它落下了。有了它，你就能关闭镇外的四个泵站了！等你搞定了，就回来找我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41765, '安德麦的情况越来越紧张了，小子。虽然那里以前不太平静，但风险投资公司已经开始在艾泽拉斯各地的各种行业获得显著的关注。他们的商业模式一直以来都比较……可以说是“非正统”，但他们的计划看起来也不太乐观。你只要去海滩看看就知道了。$B$B你看，我不久前加入了杜隆塔尔工会；考虑到黑石岛的成就，以及我在科赞岛利润优化方面无可挑剔的记录，纳特很快就给我单独​​分配了一个项目。我们一开始行动，风险投资公司就趁机趁虚而入，开始他们的行动。要我说，现在是时候好好报复一下了。让他们尝尝他们的苦头，你觉得呢？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41766, '地精们如果没人领头，通常不会有好下场，这种事屡见不鲜。没人能推卸责任，他们只会自相残杀。所以很自然地，这些暴徒肯定有人指使。考虑到这次破坏活动的规模，准是风险投资公司高层手下的哪个好手。和黑石岛的那次没什么两样，只是没那么狡猾。$B$B回到海滩，找到那只黄鼠狼，把他们绳之以法。没人能搅和了我的生意还能逍遥法外呢。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41767, '既然你帮了我们大忙，我想我可以告诉你一个小秘密。过去有很多地精加入了杜隆塔尔工会，现在还有很多。这在安德麦引起了轩然大波。一个新生的工会竟然敢与独裁的风险投资公司对抗？报纸上到处都是这事！谣言开始四处传播，一个比一个疯狂，所以最终我的老板给了我一份新工作：加入杜隆塔尔工会，看看到底发生了什么。没想到这么快就被派去执行任务了。$B$B现在我们来了。不得不说，工会和部落都超出了我的预期。你们是一群怪人，但也很强大。你们对资金和经济的掌控简直糟透了，但你们最终会成功的。相信我，纳特是个很棒的人才。说起来，你能把这份报告给他吗？可怜的家伙在怒水港等着报告，肯定很着急。见到他的时候，帮我肘他一下，明白了吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41768, '我得承认，$C，北风领的情况很糟糕。比尔克庇护所遭到了袭击，我们失去了对舍伍德采石场的控制，而且我没有足够的人手保护我的公民。虽然这令我身为贵族和领袖的自尊心备受打击，但我也束手无策。看你的样子，我猜你是云游四方的旅行者吧？如果是这样，或许你有兴趣帮我办点重要的差事？我的臣民已经精疲力竭，抽不出更多人手了。$B$B女伯爵卡特拉娜·普瑞斯托，殿下的顾问，几个月前就命令我的大部分手下前往暴风城提供保护。然而，我自己也急需帮助，所以我请求其中一些人返回家园，保护北风领。我委托你的任务对我和我的人民至关重要。把这个卷轴带给暴风要塞的普瑞斯托女士。顺便去取我弟弟安伯伍德爵士和兰开斯特巡官的报告。你应该会在安伯郡的市政厅里找到他们，他们正在监督锦标赛。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41769, '毫无准备就驯服并骑乘暴掠龙是愚蠢之举。它们的皮毛渗出毒液，在皮肤上覆盖一层致命的外皮；只需轻轻一碰，就可能判处你的死刑。然而，如果你想踏上这条充满艰辛的征程，让强大的暴掠龙屈服于你的意志并非不可能。我可以向你展示我的族人驯服这些充满毒素的野兽的古老方法。$B$B去丛林寻找它们的巢穴。寻找一枚即将孵化的蛋，其他任何蛋都不足以完成我们的任务。成功后就回来找我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41770, '虽然现在幼崽还很虚弱，但它是无害的。由于它的毒皮尚未发育，无论是它的撕咬还是它的皮都无法伤害你。花时间抚养幼崽，你的身体会自然地适应它体内不断增长的毒液。等它成年后，你就能有足够的坚韧去骑着它，而不会受到任何影响。$B$B去丛林里搜寻食物，把野兽的肉喂给它。每吃一顿，它的下巴、身体和心智都会成长和变化。把它的牙齿——它在成长过程中会脱落的牙齿——送给我，以证明你对养育它的承诺。只有这样，我才能教你如何骑乘暴掠龙。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41771, '安戈洛的远古野兽拥有一种奇特的肉。光是那股味道就足以让一些人感到不适，抽搐不止。然而，你的幼崽却吃不够。暴掠龙的后代发育迅速，因此需要大量的营养。通常情况下，它们会跟随母亲外出狩猎，但现在这项任务落在了你的身上。$B$B猎杀环形山的生物，让你的幼崽茁壮成长。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41772, '在遥远的西方，有一片遍布石柱的山谷，名为“恐惧小道”。在这些石柱之中，栖息着强大的剑龙，它们摧毁着附近的一切。它们比环形山的大部分生物都高大，这要归功于它们体内厚厚的腺体，这些腺体促进了它们的肌肉生长和力量。为了确保幼年暴掠龙能够得到良好的抚养，我们需要这些腺体。$B$B前往“恐惧小道”，猎杀剑龙。小心，它们比一般的野兽更加强壮。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41773, '漫步在安戈洛的丛林中，你一定不时感受到大地的轰鸣。远处传来恐怖的咆哮声，以及树木和树枝断裂的声音。强大的魔暴龙是安戈洛的顶级掠食者，它们无与伦比的力量无人能及。猎杀一只魔暴龙本身就是一项壮举，而击倒一只则展现了非凡的实力。它们强大的心脏肌肉将成为幼龙的绝佳营养来源。哦对了,看在命运女神份上,你最好多带点朋友再去。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41775, '$C，靠近点。你对图书馆的贡献巨大，许多被遗弃的典籍也重新回到了我们的怀抱。辛德拉对你迄今为止的行动心怀感激，因此我再次请求像你这样可靠的$R帮个忙。$B$B虽然我们的知识宝库不断增长，但我们仍然缺少一本古老而重要的魔法书，它在学者中臭名昭著。这本书由声名狼藉的巫师公主艾苏恩撰写，详细描述了粉碎和聚合魔法碎片和水晶的精细过程。让它回到图书馆至关重要！$B$B这本书散发出的魔法能量独一无二，我记得很清楚。幸运的是，它们还没有离开埃雷萨拉斯。我察觉到它就在我们上方高处，靠近卑鄙的食人魔国王的王座。毫无疑问，他那肥胖的顾问正用他那双肮脏的手玷污它。把它从他那里拿回来，但要小心！这本书很古老，很容易损坏！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41783, '你可能觉得档案管理员在这样的探险中没什么事可做，但这种想法大错特错！撇开我的其他才能，比如翻译或分析能力，军情七处驻扎的许多地方都充满了丰富的历史。对于像巴洛这样历史悠久的地方来说尤其如此。这座在王国公民中恶名昭彰的古城，围绕着它代代相传的众多故事和谣言层出不穷。虽然我必须客观地完成我的工作，但出于个人兴趣，我仍然希望记录一些特定的文件。$B$B灯塔守护人的航海日志。从这里往北看，微风港海湾对面就是灯塔。$B$B格拉汉家族的记录，他们的庄园遗址，坐落在西部山区。$B$B损毁的城门之后，教堂的布道声曾经此起彼伏。$B$B去岛上探险时，记得去看看它们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41784, '嘿，你来了！你看起来像个勇敢的冒险家！我打赌你肯定需要一份能让你以创纪录的速度恢复食欲的零食……是啊是啊，我从你的表情就能看出来，你现在就想要！嗯，抱歉了，老兄，我的科赞水果蛋糕很稀有，需要进口。如果你想买我的商品，你得先付钱给我。$B$B一百枚金币怎么样？毕竟我的水果蛋糕只卖给有钱的客户，我可不愿意把这么稀有的东西送给一些卑微的乞丐。你拿到金币后再回来找我，好吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41785, '<你手中握着龙喉氏族酋长祖鲁希德曾经持有的闪闪发光的碎片。看着他毫无生气的尸体，你不禁想起他曾经用这件如今在你手中的圣物——恶魔之魂碎片——所取得的成就。这件传奇神器曾被耐克鲁斯·碎颅者用来奴役红龙军团的守护巨龙女王阿莱克丝塔萨。它依然充满着很久以前曾被赋予的力量，你正在思考该如何处理它。或许你能找到一位愿意与你谈谈这件危险的道具的红龙军团的成员。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41786, '这座岛屿在捉弄我。整天都被浓雾笼罩，就在刚刚，我甚至能看见海面上冒出滚滚浓烟。没错，就是从海里冒出来的！看不到陆地，但浓烟却在升上天空，这合理吗？你是在帮助我们行动，对吧？如果您有时间，您能否检查一下从这里往西北方向的海上，让我好安心？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41787, '暗影议会。看来毁灭之锤的走狗们真是邋遢。如果你不熟悉他们，暗影议会是——或者更确切地说曾经是——古尔丹的狂热追随者。一群由异教徒和罪人组成的阴谋集团，将他们的生命献给他们的恶魔领主。据说他们在第二次战争中他们的主子死后就被根除了，但他们的堕落依然盛行。如果这封信可信的话，那么暴掠部族是由暗影议会一位强大的高阶术士领导的，他们在风暴城堡内活动。$B$B$N，时间不多了。召集一支精锐部队，猛攻这座沦陷的城堡。我们必须阻止他们的首领从虚空之外召唤恶魔，并救出仍在他们魔爪下的剩余居民。切勿掉以轻心，做好应对任何可能情况的准备！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41788, '居住在泰达希尔树枝上的熊怪部落并非只有瘤背族。$B$B在遥远的西南，在雾气弥漫的高地中，栖息着一个行踪不定的部落——乌萨部族。他们长久以来一直回避外人走的路，躲避着我们的目光和声音。$B$B然而……我感觉到同样的黑暗正在他们之中蠢蠢欲动——魔苔正在蔓延开来，腐化着它所触及的一切。我们派遣了一位名叫德雷萨尼斯的德鲁伊，前往他们的地盘寻找真相。但是……从那以后，风中再也没有他的任何消息。$B$B我担心他的命运。$B$B你愿意帮助我吗？去乌萨高地的阴影中寻找他——这条路位于阿里斯瑞恩之池的西边。$B$B如果他还在喘气，你就能在那里找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41789, '环顾四周。乌萨部族——曾经高贵，但对于一个低等种族来说——如今却因邪能而疯狂。他们的心灵筋疲力竭，他们的理智迷失。$B$B他们玷污了我们神圣的月亮井……并杀死了它的守护者。如此罪孽，不容置疑。$B$B如果情况不那么糟糕，我会设法抚慰他们的灵魂。但你已经见识过——魔苔对这些树林造成了什么。一旦它扎根，他们的族人将无可救药。$B$B消灭他们。尽可能多地消灭他们。把他们的护身符带给我——那些可怜的遗物，曾经由他们的萨满制作，用来抵御邪灵。真是个古怪的信仰。$B$B<他淡淡一笑，眼中闪过一丝苦涩。>$B$B显然……他们失败了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41790, '部族已支离破碎，他们的力量已随风消散。现在是夺回属于我们的东西的时候了——月亮井不能再浸泡在他们的恶臭之中。$B$B他们所谓的领袖，白色的阿科德，很可能现在还在圣水周围昂首阔步，亵渎守护者们的遗骸。他曾经是乌萨的虔诚仆从……他是熊怪之神最受尊敬的牧师之一。$B$B真是奇怪，不是吗？堕落到这种地步。人们不禁要问，究竟是何等亵渎的行为让乌索尔对此保持沉默。$B$B干掉他。砍下他们腐化的脑袋，带给我。没有他，部落就会崩溃——而我将一劳永逸地净化月亮井，彻底清除他们的污秽。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41791, '我们在东部王国的扩张非常成功。卡加斯的建立是巩固我们在卡兹莫丹边缘地位的关键时刻。但这仅仅是大酋长对无尽之海彼岸土地计划的一步。$B$B洛克莫丹那个大池塘的东北方，有一条通道通往“冷酷海岸”，那是一片山丘矮人的自由之地，充斥着邪恶的龙喉兽人。指挥官阿格纳什在那里的东北郊外建立了碎刃哨岗，这座要塞旨在抵御龙喉兽人对东部王国这片地区的侵略。前往那里冒险，帮助他完成大酋长的使命。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41792, '我的兄弟莫尔坎驻扎在冷酷海岸的碎刃哨岗。那是一片崎岖的土地，位于洛克莫丹和湿地的东边。矮人和龙喉兽人为了争夺那里的控制权，已经争斗了很久，我们的大酋长萨尔想亲自评估一下局势。这片荒野凶险无情，而我的兄弟虽然雄心勃勃、纪律严明，但仍然年轻，缺乏经验。为了鼓舞他的士气，我想让他吃一顿我做的熟猪，这是他最喜欢吃的。如果你能把这个带给他，我将不胜感激，$c。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41793, '部落的过去充满了罪恶和错误。我们过去与各个兽人氏族的联合玷污了我们的荣誉，如果我们想要迈向新的未来，就必须抹去这个污点。龙喉氏族，一群狂热的老兵，曾奴役红龙军团，如今在洛克莫丹东部崎岖的山地——冷酷海岸——集结。他们的妄想让他们像疯子一样固守旧习，却对现实视而不见。$B$B我们奉萨尔酋长的命令，派遣一支部队穿过洛克莫丹，穿过湖泊东南方向远行者小屋的隧道，前往冷酷海岸。我要你跟随他们，前往碎刃哨岗加入他们。务必尽你所能，帮助他们。为部落争光吧，小伙子！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41794, 'Mok\'rah（兽人语的问候），年轻人。在无尽之海的海湾北边，坐落着一座荒凉的巴洛岛。人为的风暴肆虐着它的海岸，古尔丹殒命数十年后，他邪恶的魔法污染依然萦绕在它的土地上。我的氏族，血窟氏族，驻扎在巴洛本岛东部的岛屿之一，代表我们的大酋长萨尔。基尔罗格酋长亲自率领此次攻势，对抗重现的古老暴掠氏族。$B$B我能拜托你一件事吗？我的族人先知萨尔努需要这种药水来进行占卜。如果你能把它带给他，那将是对部落的莫大帮助。与那边的双足飞龙管理员塞斯塔谈谈，她会尽快带你前往巴洛。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41795, '年轻人，可怕的黑暗从我们的过去浮现。这黑暗不仅威胁着部落，也威胁着艾泽拉斯的所有生命。不久前，我们收到一封来自未知寄件人的神秘信件，信是用漆黑的墨水写的。它警告我们，第二次战争的一件遗物正在重生，并将混乱的种子散播到世界各地。古尔丹的傀儡部族——暴掠部族——正在归来，并与其昔日盟友暗影议会联手。他们的术士在过去犯下了无数暴行，如果我们不阻止他们，恐怕我们将面临一个新的恐怖时代。我命令我的一位顾问，同时也是血窟部族的酋长——基尔罗格·死眼，去平息他们的叛乱。他已经前往巴洛岛，那里是他们无数年前的行动基地。$B$B$N，我希望你也效仿他，协助血窟部族。乘坐飞艇前往格罗姆高营地，与当地的双足飞龙管理员交谈。她可以带你前往暴风城西边的岛屿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41796, '你好，亲爱的$c。你听说过北风领的盛大骑士演武吗？当地的贵族正在举办一场骑士演武大会，并邀请了包括塞拉摩在内的众多人类国家参赛！普罗德摩尔女士挑选了几个我们的卫兵作为参赛者，我的宝贝孩子们也在其中！他们必须匆匆离开，我几乎没时间跟他们道别。对了，你是不是正好要去北风领？能不能麻烦你帮我把这些围巾送给我儿子鲍里斯？就算身在塞拉摩，作为他们的父亲，我也要支持他们，这算是我的本分。$B$B我听说你可以穿过暴风城港口再往北到达北风领。祝你好运！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41797, '暮色森林日益危险。无论是狂暴的狼人，游荡的亡灵，还是偷窃的凶手——这里总有东西在威胁你的性命。说到底，人们或许会好奇，我们为什么还留在这里。答案很简单：这片森林是我们的家园，我们不能让这些怪物夺走它们。$B$B然而，我留在这里让我的朋友们感到沉重，而芭芭拉的心情则比其他人更沉重。她是暴风城北部北风领的统治贵族安伯伍德领主的造箭师。我已经很久没见过她了，更别提给她写信了。她一定非常担心我，这让我深感羞愧。如果您有空，能把这封信交给她吗？信里写着我早就应该告诉她的事情，所以我委托您一项非常重要的任务。如果你能帮我做到这点，我会感激不尽。$B$B去北风领最快的路是穿过暴风城港口。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41798, '你好，$c。在我看来，你是个喜欢冒险的人。你经历过如今无处不在的危险吗？无论你去哪里，危机似乎都近在咫尺。这肯定不是我们希望孩子成长的世界。我的妻子竭尽全力让艾泽拉斯变得更美好，但即使在她所在的组织中，这对她来说也是一项几乎不可能完成的任务。这么说，你有兴趣作为雇佣兵协助她吗？她这次被指派的行动……非常棘手，至少她是这么告诉我的。坦白说，我很担心她的安危，即使对她来说，这可能也太过艰难了。如果你能帮助她，我将永远感激你。$B$B如果是，那就前往港口，就在这儿西边。在南边的某个码头，你应该能找到她的一位同事——我想他叫西蒙斯。告诉他，特工基里安请求更多外部援助，他会带你去巴洛岛见她。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41799, '那个没用的芬尼根！我发誓，总有一天，他的一次越界行为会让他完蛋。你看，不久前，一群军情七处特工聚集在码头。据我们偷听到的消息，他们显然是要去西部荒野海岸附近的一个岛上执行一项危险的任务。那个岛名叫巴洛。早在我们定居达文堡之前，那座岛就一直被一场永无休止的雷暴所笼罩。库尔提拉斯过去曾与巴洛及其居民有过接触，所以我们对这个地方并不陌生。$B$B 无论如何，我们当地的水术师芬尼根实际上自愿帮助军情七处完成他们在巴洛的任务，现在就在他们的前哨基地。我们需要他尽快回到达文堡，以免危及我们的外交使命。$C，你愿意帮他完成他未竟的事业，好让他回到我们身边吗？一位特工留在了南边的码头，我相信他可以带你去岛上。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41800, '英雄兴衰旧时地，传说赞歌也曾听，沉寂悲歌亦有闻。在此地，风声低语石间秘，大地满饮战士血，剑与魔法旧沙场，往日征战风中存。$B$B在冷酷谷的阴影中，坐落着先祖之墓——一座与格瑞姆巴托一样古老的圣殿。那里安息着矮人先祖的骸骨，他们的名字刻在符文和记忆中。我们曾以为他们安息了……但我们错了。$B$B他们的里面有什么东西在蠢蠢欲动。$B$B死者不再安眠。他们的灵魂在山谷的迷雾中游荡。一股黑暗的存在盘踞在沼泽之下，看不见也摸不着，扰乱着长久以来建立的秩序。$B$B因此，我对你说道，勇敢的灵魂：前往这片被笼罩的沼泽地，找到这疫病的源头。让他们的祖先再次安息，让生者和受人尊敬的死者之间不再有任何阴霾。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41801, '或许有人能解答这个棘手的问题。在冷酷谷深处，矗立着一棵参天大橡树，这棵古老的哨兵早在第一批矮人踏足此地之前就已扎根于此。它的年龄久远，人们也一直对它肃然起敬。$B$B但最近，我的矮人朋友们带来了消息，说有一位蓝龙在橡树粗壮的枝干下扎营。我无法解释他为何在此徘徊，但我怀疑他的存在可能与这片土地上弥漫的腐化有关。正如你所知，龙族拥有强大的力量，却又异常神秘——它们很少关心凡人的事务。$B$B如果你选择接近他，务必谨慎，因为龙族的耐心如同熔化的钢铁般薄弱。然而，如果你能赢得他的倾听，他或许能为你揭示冷酷谷即将降临的黑暗。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41802, '只有瞎子才看不到腐败已经笼罩了这片沼泽，它污秽的卷须渗透到每一处根源和阴影之中。我被派到这里，是为了揭开冷酷谷瘟疫的真相，但我的任务却远非易事。沼泽里巡逻着红色的龙族，他们的思想也被毒害这片土地的腐败所束缚。$B$B我们龙族之间有着共同的纽带，彼此拥有同胞的感知，而它们也像我一样清晰地感知着我。每次我试图接近先祖之墓，它们都会拦截我，驱使我的并非理性，而是被笼罩在它们心中的黑暗所驱使。因此，我留在这里，躲藏在这棵古老的橡树下，却无法实现我来到这片诅咒之地的初衷。$B$B然而，你们却摆脱了龙族的束缚。你们必须深入先祖之墓，揭开腐败的根源。我确信它就潜伏在其中，溃烂蔓延，蔓延着它的污染。这片土地的命运或许取决于你凡人的勇气。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41803, '现在，凡人，听好了。如果你想理解我们所面临的严峻形势，你必须首先了解灰鳞矮人以及他们诞生的邪恶起源。他们的故事充满了背叛、腐败，以及本应被深埋的黑暗。留心观察，因为这些知识既危险又必要。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41806, '单靠火腺不足以突破灰鳞矮人的防御——不，远远不够。他们扭曲的肉体已被阴影硬化，可以抵御单纯的火焰。我们需要一种催化剂……一种能够有效引导龙焰怒火的聚焦导管。$B$B在凡人称之为藏宝海湾的混乱屎坑里，栖息着一个好奇狡猾的侏儒——名叫奥布索普·奥布洛提库斯。他年轻时，曾努力研究挥发性火焰，试图净化诺莫瑞根的枯萎之灾。他的方法……非同寻常，而且饱受争议。工匠大师本人也对此表示反对。$B$B然而，如果真有哪个人能够打造出威力足以穿透灰鳞矮人那暗影锻造的外皮的龙火装置，那一定是他。$B$B去寻找他吧。时间不等人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41807, '啊哈！嗯……嗯，这还不算太糟。我有——让我想想——螺旋弹簧、助熔调节器、密封凝胶……没错！我需要的大部分材料我都准备好了！ $B$B可是！我缺少几个关键部件——也就是实心炸药、青铜框架和高速青铜齿轮。没什么稀奇的！任何一个半吊子的工程师都能用合适的材料做出来。当然，如果你只有一半的水平，也没关系！$B$B现在，有一件事可能有点棘手……耐热扳机。注意，这不是普通的老式扳机——这是安德麦的特产。专为承受极端温度而设计。据我所知，安德麦最新一批货物被那些卑鄙的血帆海盗拦截了。$B$B如果你够幸运——到最后你的四肢都还完好无损——你可能会在东南方的海盗营地里找到一个珍贵的扳机。$B$B走吧！把货物给我，我来给你带来轰隆声！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41808, '<奥格索普看着完成的炸弹，脸上流露出自豪与深重的忧虑> $B$B嗯……经过一番深思熟虑——或许还有一点点后见之明——我并不完全相信为你制作这个是我有过的最好的主意……$B$B也——也许我应该把它留着……只是为了，你知道，让世界再完整一两天……$B$B哦好吧，好吧！不用死亡凝视——哎！只要……拿着这该死的东西！但帮我们一个忙，把它带到尽可能远的地方！避开火焰、地精、突然的动作、巨大的噪音，尤其是拿着它的时候！$B$B<他小心翼翼地把炸弹放到你手里> $B$B现在走，走！嘘！趁我还没改变主意，赶紧走！$B$B哦哦哦——但是等等！所有这些修修补补让我想到了一个绝妙的主意——爆炸鸭子（突然大声）！没人会想到会爆炸的鸭子！嘻嘻！蹒跚而行！引爆！一切皆有可能（大喊）！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41809, '别再等了，凡人。$B$B那污秽的灰鳞矮人蜷缩在下面，他的爪子深深地陷入地脉，毒害他所触及的一切。他的防御或许很强大——但无法抵挡你现在携带的火焰。就让我逝去的同胞的愤怒成为将他的防御烧成灰烬的火花。$B$B然后取下他的头。干净利落地。让他的血成为他洒下的最后的腐败。$B$B但不要犯傻。独自一人走进去，你只会是他收藏中的另一具尸体。带上战士。带上钢铁。带上足够的愤怒来对抗他的背叛。$B$B现在走吧。别让我失望。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41811, '<扎尔苏似乎心不在焉，仿佛正试图聆听遥远的事物。他的注意力从遥远的思绪中抽离出来，只是好奇地看着你。>$B$B我感觉到你来此是有目的的，你能听到它拖着沙子，从沙丘中升起的声音吗？是的……某种邪恶之物已经出现，某种污秽之物。我从祖尔法拉克深处感知到了它，它已经污染了塔纳利斯的沙丘！远古邪恶的存在激怒了众神，我毫不怀疑，这就是泽尔杰布的回归。$B$B他，在我们的世界尚且年轻时他就已经年迈，是法拉基最位高权重的军阀之一，拥有黑暗不腐和邪恶魔法的力量。如果这片土地想要和平，他的灵魂必须被终结。在祖尔法拉克深处找到他，并带上你最信任的盟友，你需要他们的帮助来击败泽尔杰布。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41812, '在我们脚下的深处，有一座曾经供奉艾露恩的古老神庙，德鲁伊们在那里种植了一棵蕴含强大力量的神奇之树，用来重振自然。这棵树的美丽鲜为人知，但现在我担心它落入了邪恶之手。$B$B我听到传言说，萨特如今潜伏在黑暗深渊这些曾经神圣的殿堂里。我委托你从这棵树上取下一粒种子，带给我，或许我的德鲁伊同伴们就能发现古代德鲁伊的力量。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41813, '探险者协会今非昔比，我告诉你！我告诉他们，我来这里是为了探索历史、发掘传家宝，以及一些足以被放置在铁炉堡探险者大厅的伟大宝藏！但他们嘲笑我，没有给我任何资金。这个矮人怎么能在没有资金的情况下买得起他的啤酒？$B$B他们就是山羊和公羊的杂种儿子。哼。呃，说到这，我怀疑你身上没带多少钱，所以我就不说资金问题了。我听一些人类大谈巴洛以前有私酒。有个叫范德的小伙子以前有个农场，据说他酿的酒很厉害。我怀疑他现在还活着，不过或许你能在他老家附近找到一些他的酒？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41814, '每次我离开铁炉堡，我都会向探险家联盟承诺一份奖品，主要是因为他们伤了我的自尊！我到处挖，但在岛的这一边没找到什么，而且我也没强大到能为了实现我的野心而对付一整支兽人大军。虽然很痛苦，但我可能还是会空手而归。$B$B除非……我们做个交易怎么样？一件传家宝换一件传家宝。你帮我，我也帮你，诸如此类。我手上有一件在另一次探险中挖到的文物，如果你能从公爵的城堡里带回点什么，我愿意拿来交换。我承认我对巴洛的了解有限，但已故公爵肯定留下了一些值钱的东西。一把剑，一面盾牌，一顶王冠——无论你找到什么，都带回来给我，我们就可以交易。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41815, '西北方向有一处海盗营地——纯粹意义上的“舱底鼠”。我猜他们来这里是为了洗劫城堡。可惜城堡里鬼魂出没，被恶魔和他们的主子撵得到处跑，对吧？$B$B总之，这对我们俩来说都意味着一个工作机会。我是一名工匠，一名商人——但最重要的是，我是一个科赞的地精！我永远不会放弃免费的商品。$B$B好吧，“免费”……你知道的——你得从他们冰冷的手中抢过来。但它仍然是免费的，对吧？那就行动吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41816, '雷声。咆哮的雷声。每当天空裂开，云层都会颤抖，我的身体也随之颤抖。我多么希望自己骑在云层之上的一头强大野兽身上，咆哮着让所有人都听到！不辜负我氏族的名字——雷神——一个即将被这个世界遗忘的名字。很少有人能和我一样忧郁；这就是我追随他，那个脾气暴躁的老兽人的原因。$B$B哀悼过去毫无意义。部落才是我们现在的样子。我只希望传承狩猎精神，传承先辈们的心灵和思想，以便他们——还有我——能够延续下去。$B$B而你，你是我用火焰点燃的蜡烛。总有一天，从你的火焰中，另一支蜡烛将诞生。$B$B穿过微风港的废墟，找到前往主岛的路。经过矿井和果园，右转找到悲痛湖。鳄之血涂满汝身，带着五条尾巴回来。我已经很久没尝过它们的肉了。$B$B要大胆，要小心——一定要享受狩猎的刺激。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41817, '感觉很温暖，不是吗？一次成功的尝试，你们与他人慷慨分享了猎物，对狩猎的相互尊重使你们紧密相连。$B$B我们现在分享的这一刻，我曾无数次与家乡的人民分享过。我们每天都会满载而归，享用战利品，讲述我们的狩猎故事。$B$B我们曾经过着美好的生活——现在依然如此。尽管如此，许多人已经迷失；一个简单的疏忽就可能让你丧命。$B$B恐惧是你的对手，我的朋友。你必须控制它，否则它就会控制你。不要担心与他人竞争——要与你的恐惧竞争。一秒钟就足以让你灭亡。$B$B考虑到这一点，你必须返回悲痛湖，沿着长长的桥梁前往疾奔树林。你的下一次狩猎正在等待你。杀死雾木蜘蛛，看看你如何对抗多足且有毒的敌人。$B$B当你走到那里时，记住我告诉你的：你真正战斗的不是它们，而是你的恐惧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41818, '这将是一场更具挑战性的狩猎，但还有更多的挑战在等着你。你必须学会的教训是，没有任何生物生来平等。那些声称平等的人缺乏远见或常识。$B$B在你的旅程中，你将面临重重考验。艾泽拉斯广阔而残酷；你必须做好一切准备。$B$B不平等也标志着我们的独特性。不要看到“不平等”这个词就陷入黑暗的思考。放眼未来，明白虽然世界可能不会向你低头，但做你自己就足够了。你会找到一条路，你自己的路，你将是独一无二的。$B$B你已经直面了你的恐惧，这是找到你自己道路的第一步。$B$B现在，返回主岛。在果园岔路口左转，穿过残破的城堡城墙。穿过教堂和墓穴，找到另一个入口。穿过它，穿过洞穴。在远处松散的山丘中，你会发现秃鹫和秃鹫。直面它们，学习如何与飞行的敌人战斗。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41819, '我从来都不喜欢鱼的味道——主要是因为它在暗矛群岛上是常见的食物。然而，自从我们被迫离开家园以来，困扰我的不是鱼的味道，而是它带来的记忆。邪恶的海巫、她的纳迦以及她们愚蠢的鱼人爪牙让我们的人民付出了惨痛的代价。虽然我并不执着于过去，但我还是忍不住渴望看到这些肮脏的生物被杀。$B$B我预见到我们部落在部落中拥有美好的未来，就像我的父亲和祖父一样。我骄傲地举着它的旗帜，但今天我的思绪却背叛了我。因此，我委托你，一个将与我一起塑造部落未来的人，在你的路上杀死泥腮鱼人，以消除隐藏在他们中间的神秘领袖。$B$B爬下山坡，在那个山洞里，你会发现他们守卫着入口，海之先驱或许在那里面有什么阴谋。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41820, '我的职责是留在这里，见证暗影议会的终结。然而，我不禁思考这究竟意味着什么。海巫在如此漫长的岁月后再次出现……这令人心神不宁。你必须明白，我的人民因她而失去了许多。虽然我可能重复了一遍，但我确实想寻求你的同情。$B$B我无法离开这里。虽然我的双脚酸痛，但我无法忍受留下基尔罗格和我们的盟友独自面对这一切。我的确只是个巨魔，但平心而论，我已经越来越喜欢这位老酋长了。他残酷无情，却又英明睿智。他热情奔放，活力十足，我可以向他学习很多。终有一天，我将接过暗矛酋长的衣钵，随之而来的是巨大的责任。$B$B这个兽人饱经沧桑，肩上依然负重前行。我会给他机会，让他通过我来培育部落的下一代。因此，我请求你返回奥格瑞玛，将这份卷轴交给我的父亲沃金。你可以在格罗玛什要塞，大酋长的身边找到他。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41821, '私语来来去去；这里的幽灵永远躁动不安。但即使有这么多的窃窃私语，仍有一些声音是我无法使其沉默的。$B$B敌人邪恶、卑鄙，他们的所作所为已无可救药。我听到了——如此响亮和清晰——我能听到。$B$B一个憎恶，生来残忍，出自一个没有灵魂的恶棍。我再也无法忍受了。$B$B你必须进入那座城堡，将它摧毁。我无法用言语形容——你必须亲眼看看。它令人难以忘怀。$B$B你必须杀死它，杀死它才能解救他们——那些可怜的、年轻的灵魂。$B$B不要留下任何暴掠兽人活口；他们必须承受生者世界的愤怒，这样生者才能安息。$B$B现在就走。走吧。当你看到时你就会知道……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41822, '由人类之手打造，巴洛本岛上唯一可见的光源就被囚禁在我们的眼皮底下。一座灯塔——一种奇怪的人造光源。在我的部落村庄之外，世界广阔无垠，大地母亲怀抱许多孩子——但有些是她被迫收养的。$B$B部落对他们来说也不陌生，虽然我很想这么说，但我认为我永远不会用真正的同情心看待他们。一丝尊重？也许是怜悯。不过，我已经偏离了我们谈话的目的。$B$B在那座灯塔的底下，你会发现许多所谓的秘法师，如果你愿意，你也可以在其他地方寻找他们。$B$B要求你尽可能多地杀死他们。邪能腐化的空壳和它们腐烂的血肉终将滋养我们，让自然再次回归自然。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41823, '在战场的废墟中，可以找到一个洞穴——也许是一个旧矿井。正是在那里，我感知到了一股非自然的骚动。$B$B某种曾经静止不动的生物，如今自行开始活动了。就像散布在这片废墟中的亡灵一样，这些生物毫无意识，会攻击任何目击者。$B$B我派你去那里，找到它们，并猎杀一些。我需要样本，所以一定要带上一些锋利的东西。有了这些样本，我就能研究它们复活的原因。$B$B我应该提前告诉你——这不会帮助我们消灭暴掠兽人——但我会为你准备好一份赏金。$B$B别让我等太久。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41824, '这些样本散发着一种阴暗的气息。我不知道你是否能察觉，但它们似乎被注入了某种魔法——赋予它们生命力的魔法。$B$B据我所知，它们与卡利姆多大陆上那些令人难以置信生物的形态相似，但更加扭曲。我还没尝试净化它们，不过说实话，目前它们只是一些死去的组织。$B$B我相信这些活体真菌的来源相同。简而言之，应该有一个更大的真菌感染了其余的真菌。我这么说并非一时兴起，而是因为我感觉到岛上——在城堡废墟周围——或者说，在城堡下方——有某种气息。$B$B我相信污染源就在那里。如果你能找到城堡下方的路，你或许就能找到我们寻找的答案。$B$B把你认为重要的东西还给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41825, '净化这颗核心远非我所能。尽管我不愿承认，但我绝对无法独自完成。$B$B怀着沉重的心情，我与这颗核心分离；我唯一的愿望就是研究它，揭开它复活的真相。然而，这份知识必须传承下去。$B$B肯定有人知道如何处理这颗核心——我们的主母。你可以在雷霆崖的长者高地找到她。$B$B别在意考尔和高尔姆；我会给你我的印记，然后你就可以自由地从他们身边走过。$B$B在主母面前不要多言。她脾气暴躁，而且——信不信由你——我已经喜欢上你了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41826, '一捧灰烬。我一直相信这就是我的命运。然而命运另有安排。我没有坠入我曾经掌控的烈火，而是屈服于扭曲虚空的冰冷怀抱。对于一个抛弃祖先、投奔燃烧军团的人来说，这真是一个合适的结局。$B$B即便如此，我仍然诅咒我的命运。我追随我的族长——我的长者耐奥祖。在元素曾经说话的地方，我聆听。但我背叛了它们。恶魔的低语填满了虚空，而我欣然接受它们。我比以往任何时候都更加强大。我并不完全后悔我的道路；我仍然拥有我们前任主子赋予的力量。$B$B我现在寻求的是复仇，报复所有声称追随古尔丹的人。我的灵魂被困在碎片中，无法死亡。而现在，我站在一个女人腐烂的肉体中，她愚蠢到敢于挑战部落。恶人不得安宁，但并非所有人都能保留自我意识。前往微风港的废墟，让那些残存的人们安息。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41827, '我从来都不是一个喜欢讽刺的人。但在这种情况下，我却忍不住看到了讽刺。到头来，似乎只有傻瓜才会被幸运眷顾——我猜是这样。当古尔丹去往萨格拉斯之墓而一去不复返时，所有人都一致认为他，以及那些追随他完成这个愚蠢使命的人，都死了。$B$B 然而，有一个人活了下来，他就在这里。他被困在一只龟背上，从破碎群岛回来了。我还不知道他来这里是为了帮助那些躲藏在这座岛上的败类，还是他的目的与我们如出一辙。我所知道的是：有他加入我们——或者至少从他那里套出一些情报——就值得我们花时间。$B$B 过了灯塔所在的小岛，往前游，你就能找到他的小屋。从这个洞穴出来，径直往前走。但要小心在水里出没的鱼人。当你看到他的时候……替我朝他脸上吐口水。或者不吐。你自己决定吧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41828, '多年前，当我们的人民初次踏足这个世界时，我们自以为是无敌的。在第一次战争真正爆发之前，我们与那只肮脏的双头杂种古加尔联手，将人类的土地带到了毁灭的边缘。我们的军队开到了暴风城的城门前，胜利触手可及。我们显然是更胜一筹的战士。$B$B傲慢啊，年轻人。自以为强大的人最大的敌人就是他们自己。从城门处，骑马的战士们布里森般出击。在魔法的支持下，这些骑士迫使这位骄傲的酋长夹着尾巴撤退。谦逊——这是每个准备在战场上战斗的战士都必须具备的品质。永远假设你的敌人更强大。永远相信，如果你活了下来，你会比以前更强大。$B$B不要低估人类。马虎大意地离开这个营地，你可能会发现背后插着一把匕首。他们潜伏在阴影中，比我们感到舒适的距离更近。他们可能不是我们的主要目标，但我们必须找到并杀死他们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41829, '在他们无休止地嘲弄中，这些愚蠢的术士以我失落的眼睛命名了他们的一种能力。我决不能面不改色的接受这种侮辱。这是一种耻辱！$B$B要不是被某种邪恶的力量困在这可怜的帐篷里，迫使我不得不相信你们，而不是亲自去伸张正义，我早就亲自出马，把这些该死的、渴望邪能的蠢货的眼睛都收起来了。$B$B但我没有这个权利，所以你们得替我去。回到巴洛岛，杀掉那些暴掠术士。给我带回至少三十只他们的眼睛！他们说，如果你相信“以眼还眼”，总有一天全世界都会瞎掉。暴掠兽人们再也不需要他们的视力了——等你解决了他们之后。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41830, '我向你们表示欢迎，欢迎来到你们称之为家的犯罪遗产——庇护所、家族。见证奴役部落之手带来的浩劫。如果我们没有除掉这些恶魔主人，艾泽拉斯就只能沦为废墟。接受这一切。然后集中注意力——我们来这里不为征服，也不为拯救。我们来这里是为了承担责任。$B$B一如既往，暗影议会那些被诅咒的杂种总是能让他们变得无比可恨。他们的数量还不足以困扰这片饱受战争摧残的土地，所以他们甚至不惜一切代价，将肉体和灵魂从死亡的面纱中解放出来。$B$B在曾经的微风港，你会发现一座矿井。消灭那些阻挡在你和他们可怜主人之间的白骨和腐肉。找到这些所谓的通灵师，用他们充满邪能的鲜血染红你的刀刃。我和那些胆敢自称“暴掠兽人”的败类有一笔账要算。面对一个足以吞噬一切的虚空，风暴又算什么呢？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41831, '重获自由后，我想了很多。许多问题像迷宫一样盘踞在我的脑海中，我努力想要克服它们。正因为如此，我选择暂时隐居一段时间。然而，我没想到自己会如此轻易地被遗忘。只是一些想法。$B$B在我短暂的隐士生涯中，曾有一两次我面临和邪恶观念的较量。我们是生来邪恶的——还是后天环境所致？我得出的结论很简单：我们每个人的诞生都蕴藏着邪恶的种子，但它是否生长则取决于我们的选择。$B$B这就引出了你的下一个任务。如果你觉得我之前的话很无聊，那就听我说。他们知道浩劫，所以你也会给他们带来浩劫。走出微风港，逼近城堡——你的目标正在等待着你。你并非杀手——你是它们行为的后果，带去它们应得的报应。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41832, '士兵，你会养虫子吗？我对蚂蚁很感兴趣。你看，虽然它们的种类、等级甚至习性各不相同，但如果你敞开心扉去看待它们——真相只有一个。蚁后死亡的那一刻，可能会发生三种情况：蚁群瓦解，在没有新工蚁的情况下慢慢消亡；蚁群拥有多个蚁后，因此它们仍然能够生存；或者蚁群会孕育出新的蚁后，以确保蚁群的延续。$B$B就像蚂蚁一样，暴掠氏族的数量也很多。你的努力虽然没有白费，但几乎没有削弱它们真正的实力。所以，为了确保我们任务的目标，你必须再次出发，为我们开辟一条道路——这一次，要更靠近它们的巢穴。前往风暴城堡的遗迹。不要退缩。尽可能地走远些。在那无尽的战场上，你将是践踏蚁群的靴子。$B$B冒险不意味着孤独——向你的兄弟姐妹寻求帮助。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41833, '如果你还没有找到达克苏尔，现在是时候了。达克苏尔掌握着攻占城堡的关键，而你的下一个任务就是平息这一切。一位老熟人来拜访我了。虽然我们在很多事情上意见不一致，但我们有一个共同的仇恨——对古尔丹在组建这个氏族时站在他身边的卑鄙家伙的仇恨。$B$B虽然那个懦夫本人不在这里，但他派了他最得意的学生来监督这场新的暴乱。虽然他是你的主要目标，但别怕、杀死所有你看到的人——尤其是达加尔和欧鲁诺克。坚强起来；我不知道他们会给你带来什么。$B$B虽然我对他们的仇恨如同黑石山最深处的深渊般灼烧，但我心里清楚——他们虽然卑鄙，但能力非凡。但我相信你更胜一筹。再次向你的盟友伸出援手，确保能搞定。我真想知道……等你回来，阳光还会回到这座岛上吗？毕竟，雨不会一直下。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41834, '当我被派到这座岛上时，我相信大酋长——和大多数人一样——只看到了一个随时准备赴死的老兽人。他命令我成为一名指挥官，而不是一名战士。若非伊崔格的忠告和萨鲁法尔的嘲讽，我恐怕自己不会完成我的使命。但我相信我的朋友，他们也相信大酋长。$B$B霜狼的心在胸膛里怦怦跳动。他拥有超越年龄的智慧，就像德雷克塔尔和奥格瑞姆一样。看来他对我的判断是对的。虽然我渴望与你并肩作战，用我的战斧染红这座岛屿，但我也学到了别的东西。$B$B我是血窟部族的最后一任酋长，部落的长老，我将用这双手引领下一代。现在，怀着胜利的喜悦，前往格罗玛什要塞。向酋长呈上我们的胜利果实，并告诉他我很快就会回来。或许到时候我会去拜访地狱咆哮的纪念碑。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41835, '虽然他们已经占领了岛屿的大部分地区，但似乎并没有真正沉浸在自己的傲慢之中。仿佛预料到联盟和部落都会来似的，大量的恶魔被召唤而来。我甚至能从很远的地方感受到他们回荡的气息。我不知道他们是为了自保还是入侵。$B$B这其实并不重要，因为你将挫败他们的计划。你可以在岛屿西南端附近的一个洞穴里找到这些恶魔。就在风暴城堡西边，穿过一片战场废墟的地方。虽然小鬼可能不是什么真正的挑战，但你还得对付地狱猎犬和魅魔。$B$B我很想知道——你会屈服于小鬼的火焰、地狱猎犬的暴食，还是魅魔的欲望？我真心希望不会，因为你在这里的角色尚未结束。我会给你一块治疗石——不是我不信任你，而是当意外来袭时，最好能有办法治愈，不是吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41836, '我相信你渴望不惜一切代价，尽快攻入城堡。但要做到这一点，我们必须先找到打开城堡的钥匙。在我派你去猎杀暴掠氏族召唤的恶魔的那个洞穴里，你还会找到一个自称领导其他恶魔的恶魔。她自称哈雷利斯女士。$B$B这个恶魔非常重要，原因很简单——如果我的爪牙说的是真的，她手中有一件能帮我们拿到城堡钥匙的物品。虽然我不能让你把她送回这里，因为你必须把她拖过战场，但我会给你一块灵魂碎片——一旦你发出最后一击，你就能将她的灵魂捕获其中，只需将它带在身上即可。$B$B一定要取回我们真正想要的物品，她的死亡是不可避免的，而捕获她的灵魂只是我们的保险措施，以免我们可能需要收集更多信息。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41837, '暴掠氏族并非完全由暗影议会的兽人组成，还包括侍奉古加尔的食人魔法师。尽管古尔丹与这个双头小丑的关系存疑，但他始终尽可能地与这家伙保持密切联系。我怀疑他这样做是否是因为他知道，他们终有一天会在对权力的渴望中互相背叛。$B$B唉，一个失败了，另一个却活了下来——藏身于沙漠之下，躲藏在一个崇拜与这个世界一样古老的神话传说的邪教的幌子下。我擅自让魅魔们与我分享了她们的计划。向西走，穿过你击败她的那个洞穴，你就会找到风岩崖。在那里，暮光之锤的一名成员掌握着钥匙的碎片。杀了他，把你找到的东西带回来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41838, '嘿，你！你看起来是个硬汉，而硬汉正是我们需要的。在灌木谷南部的群山附近，我们开始了最新的赚钱计划——滑芯石油钻井平台。一开始一切都很顺利，直到泵站开始失控，石油开始自己流动起来！我跑遍了整个沙漠回到加基森，想找人帮忙解决我们的问题，而你看起来正是我们需要的那个人！别担心，我们会付给你一大笔金币！一旦你到达南部的山脉，靠近大仙人掌的地方，你会发现一个通往山脉的斜坡。石油钻井平台就在附近。和助手气闪谈谈，她会知道是我派你来的。$B$B 哦，对了，你顺便能把路上的油清理一下吗？相信我，绝对值得！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41840, '<在那怪物留下的水坑中，你发现了一把严重受损的木剑。它很小，而且大部分表面都被泥浆的酸液腐蚀掉了。然而，你可以辨认出玩具剑柄上“提米爵士——”的字样。也许这足以让你知道它的主人是谁。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41841, '<你手中拿着破碎的血石吊坠，它是疯狂的古加尔的弟子伊加尔弗用来召唤可憎的眼魔墨苟斯来到艾泽拉斯的。与恶魔激战所造成的伤口仍然遍布你的全身。鲜血顺着你的手臂流到手掌上。突然，吊坠剧烈地摇晃起来，发出一声扭曲的尖叫，吸入了红色的液体。不久之后，鲜血消失了——吊坠开始搏动。$B$B你还记得在塔伦米尔协助一位被遗忘者典狱长找回类似的文物；黑暗女王希尔瓦娜斯·风行者的遗物。最好把她被偷走的饰品还给她。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41842, '如果你要进入风暴城堡，我有一个卑微的请求。巴洛家族在统治岛屿的漫长岁月中积累了无数的书籍和典籍。经过数十年的贸易，他们在图书馆里收集了难以想象的丰富知识。其中之一，是第二任巴洛公爵的弟弟沃尔顿·巴洛爵士关于隐秘贸易实践的私人教诲和讲座，这本书是我和暴风城都非常感兴趣的。$B$B如果你偶然发现了风暴城堡的庞大图书馆，就去里面找找那本书。还有$N：小心里面的危险。我不敢想象那些阴森的大厅里都有哪些恐怖等待着你。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41843, '所以，潜入风暴城堡的时刻终于到了。要想毫发无损地从这个恶魔的巢穴回来，你必须集中全部精力，运用全部技能。我直言不讳，但你肯定已经意识到了这一点，不是吗？我和其他人会守住城堡庭院的防线，防止援军干扰你的行动。$B$B基瑞安特工命令你砍掉九头蛇的脑袋，这无疑是所有任务中最重要的。不过，为了确保幸存的傀儡不会卷土重来，我们也必须消灭它们。消灭你遇到的任何强硬分子。我们不想再和那帮败类打交道了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41844, '当我们迫降在这个岛上时，我们发现大部分货物都掉进了茫茫大海。虽然我们仍然保住了很大一部分，但这远远不足以满足藏宝海湾的接收者。尤妮和其他人忙着修理飞艇，还要确保我们不会被可怕的甲壳类生物吃掉。而我，前段时间我们寻找维里克斯的时候，正好有一次绝佳的机会侦察一下这座岛屿。你知道吗：悬崖顶上有一座巨大的城堡。你大概能猜到我在暗示什么。虽然我不像维里克斯那样疯狂和有自杀倾向，但错过这个机会去抢一些地精从未见过的宝物，那也太失礼了。$B$B这就是你的用武之地。叫上几个朋友，或者如果你没有朋友，可以雇些个人，去巴洛另一边的城堡里尽可能多地抢些宝物。相信我，这绝对值得！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41845, '异形潜伏在这些大厅里。源于恶意的怪物和来自堕落深渊的恶魔，把这个曾经辉煌的地方当成了自己的家。巴洛，我仍然记忆犹新——它曾经的样子。熙熙攘攘的生机与商业。如今一切都已不复存在，唯有那些依然顽强生存的灵魂。几十年前遭受的残酷迫害将我们牢牢束缚在故乡，阻碍我们前行。善良的$C，你愿意成为打破我们枷锁的人吗？$B$B在城堡深处，栅栏之外，兽人的恶魔盟友正在进行着邪恶的实验。他们的一名监督者，一个长着翅膀和蹄子的邪恶女恶魔，掌握着我灵魂的碎片，让我无法逃脱时间的束缚。杀了她，取回它。然后或许……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41846, '丹基塔斯的蛮锤部族急需援助。龙喉氏族日益嚣张，镇长荷丹姆·硬手担心他们随时可能发动袭击！$B$B在我们整备军队进行妥善防御的同时，我们也有责任向像你这样的冒险者寻求帮助。你们被选中协助荷丹姆镇长和丹基塔斯的人民度过这关键时刻。$B$B要前冷酷海岸，需要穿过高处小径——洛克莫丹远行者小屋附近的一条山间小道。保持警惕，因为龙喉氏族的威胁不容小觑。到达丹基塔斯后，请立即向荷丹姆镇长汇报。愿高山的力量指引你们！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41847, '很久以前，我们曾与高贵的蛮锤矮人并肩作战——这是基于相互尊重和共同需要而建立的联盟。在我们最需要的时候，他们毫不动摇。鹰巢山敞开大门，接纳了数百名难民，他们坚韧的巡山人保护了无数商队免受荒野的危险。他们的行为，高尚而无私，是我们永远的恩人，尽管任何感激都无法偿还。$B$B因此，得知位于遥远而危险的“冷酷海岸”中的丹基塔斯聚居地所面临的困境，我感到无比沉重。在他们危难之际，我们不能袖手旁观。我已经派遣了一支由我们最优秀的游侠组成的小队前往支援他们，但我相信，他们也会以他们传奇般的热情好客接受任何额外的援助。$B$B当你抵达丹基萨斯时，请去找游侠快步。她被委以一项极其艰巨的任务——你的技能或许能助她一臂之力。赶快行动，分秒必争。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41848, '你走过阿尔萨拉斯的小径时，一定见过他们——枯法者。这些可怜的生物……对奥术的渴望吞噬了他们的心智，只留下一具躯壳。$B$B 真是一场悲剧。最令人心碎的是，他们的数量会随着每个黎明的到来而增长。枯萎一旦开始，就无法逆转——只能延缓。但即使如此，也需要大量的法力，而许多人认为，对于那些已经因饥饿而迷失的人来说，这代价太高了……$B$B 然而，塞隆老爷依然抱有希望。他相信，这片土地上或许蕴藏着解药的钥匙。希望渺茫，但无论如何，希望依然存在。$B$B 尽管如此，一切都在按计划进行。现在，我有一个任务交给你。有传言说，一条通往格瑞姆巴托的古老通道已被毁坏，位于西边某处，埋藏在群山之中。如果传闻属实，你找到了这条被遗忘的道路……请速回我这里。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41849, '那么……有一个古老的传说，讲述一位矮人珠宝匠，他曾居住在格瑞姆巴托的这一带。他的技艺无与伦比——据说他打造的宝石闪耀着星光般的光芒。$B$B但不仅仅是美丽……据说他能打造储存法力的水晶——不仅如此，他还能打造出能够反复补充法力且不会破碎的水晶。这真是一项罕见而神奇的壮举，如果真有的话。$B$B相信你知道这会带来什么结果吧？如果我们能找到哪怕一颗这样的宝石，我们的奥术师或许就能解开它的制造秘密。制造法力水晶的负担可以减轻了……这样一来，或许我们就能更好地照顾枯法者了。$B$B如果你能勇敢地走进废墟，寻找这些魔法石的任何踪迹——一块碎片、一条线索，或者最好是一块完整的水晶——那对我们人民来说将是无价之宝。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41850, '就在这些山丘以东，坐落着塞尔加拉兹矿井。是的，几十年来，丹基塔斯的勇士们一直在开采它们——直到穴居人的到来。那些矿工们，该死的贪婪，很可能挖进了某些古老黑暗的隧道，那些肮脏的生物就潜伏在那里。$B$B通常我不会为此烦恼——这地方地下蕴藏着大量的财富——但这些矿井里却有些特别。某种稀有的东西。就在穴居人出现之前，矿工们在最南端的矿井里发现了一颗宝石。而且，要知道，这可不是普通的宝石。如果传闻属实，这颗宝石很可能就是纳拉兹宝石，由造物主亲手打造。$B$B肯定要得到它。但我不是战士，那些穴居人对我来说太强大了。把宝石带给我，你就能得到奖赏，我发誓。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41851, '勘探员铁趾被派往荒芜之地挖掘造物主的遗物。那傻瓜一直对古老的宝藏情有独钟，他确信纳拉兹宝石可能就在那里。我们意见不合，所以各奔东西——我则去了冷酷海岸寻找。结果发现，我们在某种程度上都是对的。宝石已经裂成了两半。$B$B但现在这些都不重要了。重要的是，我需要你前往荒芜之地，去他的挖掘地点，找到那颗宝石。如果他们发现了它，嗯……如果它不见了，铁趾恐怕不会注意到。$B$B你把它带给我，明白了吗？纳拉兹宝石必须归我所有——才能让它恢复原状。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41852, '$C！探险者协会急需你的帮助！$B$B你肯定已经听到了消息——我们位于此地北边的挖掘点遭到了那些该死的暗炉矮人的野蛮袭击！这些野蛮人伏击了我们，杀死了我们的同胞，然后像疯癫的野兽一样开始挖掘，丝毫不顾及考古过程和土灵的神圣遗迹！$B$B需要你前往那里，找回任何可能在他们肆意掠夺中幸存下来的土灵遗物。拜托，时间紧迫——我们族人的遗产岌岌可危！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41853, '这根本没有道理！我以我的胡子的名义发誓要报复暗炉矮人和他们那一大堆邪恶的倒霉玩艺！$B$B我领导了探险者协会在冷酷海岸的挖掘工作，请注意，这是一次和平的努力。然后，那些奸诈的黑铁矮人在夜色的掩护下突然袭击了我们！我们只有少数人活着逃脱了——我的大部分战友都在他们待着的地方被屠杀了！$B$B我们必须反击！向东北方向去，我的旧挖掘场那，尽可能多地杀死那些黑铁渣滓。把他们的头拿来作为证据。不要怜悯他们——他们什么都不配。$B$B另外听着——如果你有机会在那里发现我的私人宝藏，把它带回给我。它里面保存了挖掘过程中的珍贵笔记，我不能失去这些笔记！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41854, '你发现了一个装满笔记、文物和各种垃圾的宝箱。锁上写着“格罗丹·黑炉”这个名字。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41855, '我叫科格·石靴，我在塞尔加拉兹矿区担任工头已经整整三十年了......一切都很顺利——真的比好的还要好。矿井很丰富，到处都是铁和煤.$B$B可然后......然后我们发现了那颗被诅咒的宝石。从我们发掘出它的那一刻起，穴居人就开始像瘟疫一样从裂缝和隧道中蜂拥而出。他们很快就占领了我们的坑道。$B$B多亏了造物者的恩典，大多数矿工都设法逃脱了，但矿井本身——它已经失守了！随着龙喉氏族威胁的迫在眉睫，市议会没法派哪怕一名士兵来帮助我们夺回它。$B$B拜托了$r，我求求你——帮帮我。在采石场中杀死 10 个碎骨穴居人和 10 个 碎骨断骨者。这是我们夺回属于我们的东西的唯一机会！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41856, '我还有一个人要帮你一个忙，$r.$B$B采石场目前可能没有穴居人，但侵扰的真正来源在于更深的地方——矿井本身。如果我们要永远夺回这个地方，你就需要冒险进入矿井并应对其核心的威胁。$B$B至少需要 10 个碎骨击颅者和 10 个碎骨地卜师。希望这足以阻止这股浪潮......就目前而言。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41857, '呸！东边的穴居怪，北边的龙喉兽人，南边的鬼魂，现在还有 鱼人？！按照这个速度，如果黑暗之门就在我自家后院打开，我也不会感到惊讶！$B$B不谈这些了，那些聚集在冷酷河附近的爆炸性增长的鱼人正在成为一个真正的问题。它们的数量越来越多，如果我们不尽快捕杀它们，它们将对我们的渔民构成危险。$B$B给我十二片鱼鳞片作为你行为的证明，$r。让我们提醒那些他们正在闯入的水域的鱼人！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41858, '迄今为止，您无疑已经注意到了冷酷河南岸的那个巨大的洞穴。前段时间，沼腮鱼人接管了它，现在我们因为他们而没办法开发洞里的资源。$B$B我们需要打击并一劳永逸地将他们赶出那个洞穴。事实证明，消灭一个地方的鱼人的最好方法是砍掉头——杀死它们的首领。$B$B一个名叫嘉吉的鱼人指挥着这群糟糕的鱼人，但我们的渔民知道他的另一个名字：屠夫。他已经杀死了我们这边不少人，如果不阻止他，还会杀死更多人。$B$B你们的任务很简单，$r——杀死嘉吉和 8 个沼腮鱼人及 泥浆鱼人。这应该足以将他们永远赶出洞穴！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41859, '<小盒子生锈了，只有在用力时才能打开。霉菌和潮湿泥土的刺鼻气味散发出来，在里面的只不过是一张折叠的纸条和一个邋遢的吊坠。你小心翼翼地展开精致的纸张，露出上面的旧体字：$B$B“沃尔拉姆，我从来没有机会感谢你所做的一切，甚至没有机会为我所做的一切道歉。你去世还没多久，我试着继续前进，但内疚感仍然让我心碎。您总是告诉我要带着信念和目标向前看，我打算听从您的建议。我在格兰村(夜色镇的前身——译注)的行为是我最大的遗憾，你为此付出了生命的代价。我将通过延续您的遗产来赎罪，我会以我父亲的吊坠发誓。请保护它，直到我履行了这个誓言，这样我就可以安心地把它放在他的坟墓上。$B$B——埃德林“$B$B看着这个吊坠，你思考着那个坟墓可能在哪里。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41860, '$N，很高兴见到你。不久前，一位陌生人正在寻找你。我告诉他们我可以转达一个信息，之后他们告诉我：$B$B“在大德鲁伊的兽穴与我们会面。我们恭候您的到来。”$B$B他们看起来很神秘，但并无恶意。我相信你无需担心。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41861, '我们看到我们的消息已经传到了你那里，$N。你的事迹传遍了很远的地方，甚至传到了翡翠梦境的青翠之地。你对玛洛恩的英勇事迹引起了人们的关注。他的同胞，荒野诸神，以及他的挚友伊瑟拉都欠你很多，因为你将他从梦魇的魔爪中拯救了出来。一旦他恢复形态，我们将获得另一个强大的盟友，对抗梦魇瘴气中的黑暗存在。$B$B我们的母亲伊瑟拉派我们前往神圣的月光林地，寻找唯一一个率先对抗梦魇的德鲁伊。作为对他在海加尔山和黎明森林中行动的奖励。我们会做到的。不过，首先要进行一个测试。我们知道你的能力——你的智慧、力量和毅力无人能及。再次向我们证明你的能力，我们将赋予你更多力量，以完成守卫者赋予你的祝福。$B$B我们不会退缩；准备好面对绿龙军团的力量吧！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41862, '欢迎来到丹基塔斯，朋友。我很乐意讲述我们城镇的历史和骄傲，但现在不是讲故事的时候。$B$B你可能已经注意到了，我们的处境很严峻。龙喉氏族再次崛起，我们深陷于一场节节败退的冲突之中。$B$B你的到来，以及为数不多的联盟部队的到来，给了我一线希望。也许我们仍然有机会再次看到太阳从这些群山中升起。$B$B我最信任的指挥官，巡山人钢风，驻扎在巴格斯之墙以北的东脊哨站。他正在领导对抗龙喉氏族的行动，我们需要每一个能人。立即前往那里报告。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41863, '他们无处不在。$B$B在道路上，在我们古老的堡垒里，在洞穴中，在整个山丘上。每个商队都需要十几个巡山人才能到达目的地——即使这样，龙喉氏族也经常发动袭击。$B$B这是对巴格斯记忆的耻辱……也是我荣誉的污点。$B$B我们已经忍够了。是时候让龙喉氏族明白，恐怖之地的矮人再也无法忍受这种屈辱了。$B$B我们要反击。我们要伏击他们。我们要让他们看看谁才是这片山脉的真正统治者。$B$B尽可能多地杀敌，并带给我二十个他们的印记作为证据。让他们知道对抗蛮锤氏族意味着什么。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41864, '有一件事我无法忍受——留下一位真正的矮人英雄的旗帜。$B$B当龙喉氏族攻占巴格斯堡垒时，我们被迫撤退，速度比我愿意承认的要快。在混乱中，我们的旗帜——巴格斯指挥官的私人旗帜——被留在了中央塔顶。$B$B它不仅仅是一块布。这面旗帜经历了十几场战斗，承载着每一位在其下服役的矮人的骄傲。让它留在兽人手中，是我们无法忍受的侮辱。$B$B爬上城墙，杀出一条血路，打败龙喉氏族的败类，夺回那面旗帜。把它完好无损地带回来。为了巴格斯，为了这块土地。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41865, '你已经证明了自己的实力，现在是时候发起真正的进攻了。$B$B北方是斯托尔加兹要塞——或者说是它的废墟。它曾是一座引以为豪的前哨，由深谙忍耐之道的矮人一砖一瓦地建造而成。$B$B如今，它只剩下一片废墟，到处都是龙喉氏族的污秽。但别被它现在的状况迷惑——这座要塞仍然具有战略价值。我们夺回它，就能找到一个立足点，进一步向山中推进。$B$B需要你带头冲锋。进去把他们消灭掉。斩杀十二名龙喉氏族入侵者、十名叛节者和十名该死的缚火者。$B$B还有一件事——他们的首领，一个名叫格拉乔克·焰手的蛮族，在要塞的密室里指挥着这支部队。那个兽人要为毁掉兵营和烧毁我们的补给站负责。$B$B杀了他。为了那些逝去的人们。为了斯托尔加兹。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41866, '红标家族掌控着卡兹莫丹的大部分地区——我的父亲纳兹戈林想要让人们记住这一点。$B$B他想让我们帮助丹基塔斯的人民，为战争出一份力。唯一的问题是……我可不是那种好斗的人。$B$B不过，如果能传扬开来，说我，加林·红标，为这项事业做出了真正的贡献，那也无妨。$B$B此处以北是盖斯卡尔，一座龙喉要塞，已经成为蛮锤部族的眼中钉。更重要的是，它是兽人们的主要补给站。如果你能潜入并偷走他们的补给箱——比如八个——那对他们的战争成果将造成真正的损害。$B$B而且，嗯……这么说吧，这对红标家族来说也是一件好事。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41867, '自从我和我的团队踏入冷酷海岸以来，我的胃里就一直有一种挥之不去的预感。这地方有点不对劲——某种不自然的东西。这片土地本身就感觉……恶心。树木、野兽，甚至风——都被一种奇怪的腐烂所侵蚀。$B$B更糟糕的是，我亲眼目睹了它成形。这些泥怪——阴暗、邪恶的东西——正从山里爬出来，就像伤口感染一样。无论它们走到哪里，都会把同样的腐烂蔓延到周围的土地上。$B$B需要了解我们在这里面对的是什么。如果你遇到任何泥怪，介意……帮我收集一些样本吗？只是，呃，尽量别沾染上任何东西。我会让你觉得值得的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41868, '我们不是随风乱搭帐篷的。我们来这里是有原因的。$B$B我们身后是一个古老的洞穴——其实更像一条隧道。它通向哪里？格瑞姆巴托。或者说，格瑞姆巴托的废墟。不过，别慌——主城已经被封锁了。更深的大厅很久以前就坍塌了。我们能到达的只是一个被遗忘的前哨，是外围废墟的一部分。$B$B我们试着四处寻找，但没走多远。怨灵把我们赶了回去——蛮锤氏族的幽灵，可能是在格瑞姆巴托之战中陨落的。只是……它们有点不对劲。它们不仅仅是躁动不安。它们被污染了，就像你发现的那些软泥怪一样。$B$B需要更多证据。如果你愿意去那里，让那些灵魂安息，并把你找到的任何东西带回来——样本、诅咒的残留物，任何东西——我想我们最终将能够拼凑出这里发生的事情。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41869, '呸！愿扭曲虚空带走这位镇长和他们的借口！$B$B他们只关心那些该死的龙喉兽人，而那些酷鳞野兽则像稻草人一样横行，撕裂旅行者。$B$B他们袖手旁观，看着我唯一的儿子在那里被撕裂。我的儿子。死了——因为他们袖手旁观。$B$B无法让他起死回生……但我确信我能阻止这种事情发生在其他矮人的亲属身上。$B$B去那些山里。追捕八只酷鳞迅猛龙和它们尖叫的表亲。把它们一个个砍掉。然后回来找我，我们看看这世上是否还残存着正义。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41870, '所以……你砍掉了那些小家伙。很好。但这仅仅是个开始。只是血腥的表面。$B$B真正的巢穴——它们变得巨大、强壮、致命的地方——在基塔斯湖的北边。那是一片荒凉的高原，爬满了最邪恶的怪物。酷鳞长尾龙。邪恶、聪明、快如布里森。那是它们繁殖的地方，也是这片污秽滋生的核心。$B$B镇长称之为自然循环。呸！看着你的儿子被野兽撕成碎片，而你却离得太远，无能为力，这可不是什么自然现象！$B$B如果你消灭了足够多的怪物，也许——只是也许——巡山队会清醒过来，完成任务。$B$B屠杀他们。为了我。为了我的孩子。这样做，就不会有其他矮人需要埋葬自己的骨肉了。$B$B如果可以的话，我会和你一起骑行，但我的这把老骨头连酒杯都端不起来，更不用说刀刃了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41871, '是的，丹基塔斯出现了新面孔！$B$B欢迎来到我们的山间家园。它或许不如格瑞姆巴托宏伟，但别被这朴素的石头迷惑——我们这里的矮人如同群山般坚固而骄傲。$B$B不过……最近日子并不好过。龙喉兽人强势回归，虽然我们的战士挥舞着锤子，力大无穷，但寡不敌众。$B$B荷丹姆·硬手镇长正在指挥我们的行动。他命令任何体格健全的冒险者——比如你——直接向他汇报。你可以在镇长大厅找到他，就在我身后的小路上。那是一座巨大的石头建筑，很难错过。他通常在底层的议会大厅里。$B$B去吧，小子。丹基塔斯需要另一只强壮的臂膀。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41872, '巴格斯之墙屹立不倒！不过我跟你们说，吃不饱肚子可不行……$B$B这场与龙喉恶狗的战争对我们族人可不好。乡间危机四伏，而我们的农民——愿神明保佑他们——都躲在丹基塔斯，田地荒芜。$B$B我们几个月来一直啃着树根、浆果和坚硬的老豆科植物！而且我跟你们说——这可不是给一个真正的矮人吃的。我需要一块结实的野猪肉，用啤酒慢烤，配上切厚的面包和黄油来吸收滴落的……$B$B咳咳！但比起食欲，更重要的是士气。我这城墙上的小伙子们日夜奋战，他们已经好几个星期没见到肉了。我们不能离开岗位，但你……你看起来腿脚有力，瞄准也很准。$B$B去山上带回新鲜的石皮野猪肉。巴格斯之墙和丹基塔斯都会感谢你们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41873, '<这本日记用破旧不堪的皮革装订。里面的大部分内容记录着一位辛勤劳作的矮人农夫的日常生活——天气预报、种植周期、牲畜记录。然而，在最后几页，字迹开始颤抖，线条变得飘忽不定……字迹也变得更暗了。>$B$B她让我留在这里，是的。她让我留下。$B$B镇长……他们想把她从我身边带走。$B$B不会离开，不会。我会保护她的安全。是的。$B$B听到了声音。哦，我听到了。$B$B他们让我留下。$B$B必须留下。$B$B会的。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41874, '斯托尔加兹要塞……如今，一个名字激起了昔日的骄傲和新的悲伤。$B$B这座要塞曾是蛮锤部族引以为豪的堡垒，在保卫冷酷海岸方面占据着至关重要的地位。但那是在龙喉兽人占领它之前。它多年来一直屹立在敌人手中——虽遭破坏、玷污，但依然屹立不倒。$B$B真正让我痛心的不仅仅是要塞的消失……而是里面的东西。要塞里珍藏着我们最珍贵的一些历史记录。血统、皇家法令、逝去英雄的日记——整卷整卷地记载着我们人民的崛起。$B$B现在，我怀疑龙喉氏族是否真的有智慧或心思去销毁书籍。他们很可能甚至没有意识到自己拿走了什么。如果你设法进入斯托尔加兹的内部，一定要留心观察。你取回的任何卷宗都可能恢复我们历史的一部分。$B$B你这么做，我会确保你得到丰厚的补偿。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41875, '巴格斯之墙经受了龙喉氏族无数次的袭击，我都记不清有多少次了。但石头不会自我修复，经过多年的围攻和忽视……她开始崩塌了。$B$B城垛上布满了裂缝，砂浆也碎裂了，我还亲眼见过地精的炮弹直接穿透了其中一道护墙。更糟糕的是，来自南方的石材运输一如既往地延误了。$B$B但海岸地带一直以来都是建立在过去的遗迹之上的。古老矮人要塞和瞭望哨的遗址散布在整个地区，它们的砖块在苔藓和泥土之下依然坚固。只要稍加修缮，它们就能很好地修补城墙。$B$B尽你所能找到任何坚固的砖块或雕刻的石头。古老的废墟、废弃的前哨，甚至是倒塌的城堡——收集任何可以重新利用的东西。你带来的每一块石头都有助于防止龙喉剑落入丹基塔斯手中。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41876, '欢迎来到岩须的锻炉——火花四溅，锤击高歌，钢铁坚守阵地。$B$B我们世世代代都在这里为巡山人提供装备。盔甲、战斧、弩箭——每一件都倾注着我们的骄傲。但最近……骄傲无法让熔炉保持热度。战争的需要超出了我们的承受能力，我们的铁快用完了。$B$B通常我会让我儿子去丹基塔斯打听下一批矿石的运输情况。但我几乎喘不过气来，而他却像疯子一样不停地敲打着。$B$B你能帮我们一个忙吗？去丹基塔斯问问硬手镇长，什么时候能从塞尔加拉兹矿井得到更多矿石。如果再不来，我们就只能用勺子敲打钢铁了……') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41877, '即便我们成功夺回塞尔加拉兹矿井——提醒一下，我正在努力——我们的矿工也需要数周时间才能清理隧道、修复支撑架，并恢复正常的矿石运输。$B$B而我们没有时间了。每浪费一分钟，就意味着又有一把剑没有磨快，又有一面盾牌没有修复。$B$B我该去求个老朋友了。$B$B铁炉堡有个矮人——纳兹戈林·雷德布兰德领主。我知道他的名字很厉害。但他欠我人情，更重要的是，他掌控着矿工公会。$B$B去铁炉堡和纳兹戈林谈谈。告诉他是我派你来的，并解释一下我们的情况。如果他能帮助我们，熔炉可能在这周内就能再次燃烧起来。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41878, '矿石会来的。$B$B我会让我在铁炉堡矿工工会的人从今天开始重新安排一些货物的运输路线。可能会拖累其他一些项目，但丹基塔斯更需要它。荷丹姆迅速行动是对的。$B$B现在去——回去告诉他，铁炉堡和丹基塔斯站在一起。让他知道，这下我们扯平了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41879, '我父亲是整个冷酷海岸最优秀的铁匠之一，众所周知。多年来我一直努力赢得他的尊重，但无论我做什么，似乎都比不上玛格拉的技艺。她只是……更胜一筹。$B$B但我一直在研究一件特别的东西——一件或许最终能改变现状的东西。一把钉头锤，我真正的杰作。但它还没有完成。它需要一件稀有的东西，一件威力强大的东西，让它在城墙上的其他武器中脱颖而出。$B$B我听说在巴洛的风暴城堡废墟的深处，有闪闪发光的红色水晶——风暴水晶石。据说它们拥有不可思议的力量，如果我能把它们镶嵌在钉头锤的头部，或许就能证明我也是个合格的铁匠。$B$B如果你要去巴洛，能帮我带一个回来吗？') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41880, '现在是时候让我们进攻冷酷海岸中龙喉氏族的核心势力了。$B$B扎姆盖斯要塞位于北部荒野——一座由石头和钢铁雕刻而成的堡垒，里面布满了陷阱、高墙和最致命的兽人。精英战士、久经沙场的勇士，并且毫无疑问的、他们残忍的首领也在那里指挥着一切。$B$B这不会是一场孤军奋战的战斗。如果你想突破他们的防线，赢得胜利，你需要战友的帮助。$B$B你的目标很明确：击杀十名龙喉精英和十名龙喉勇士。击杀如此多的精英战士无疑会摧毁他们的斗志。$B$B打败他们，你的这一击将响彻群山。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41881, '现在，我们肚子里有肉了……但光有肉根本撑不住。我们真正需要的是面包——能保存很久、饱腹的正宗矮人食物。$B$B或许有解决办法，但风险很大……$B$B远在东北方，坐落着布兰加的农庄。嗯——也就是它残存的部分。现在人们叫它布兰加之愚。布兰加曾经是整个冷酷海岸最富有的农民，拥有无尽的金色田野。$B$B当龙喉兽人来袭时，他拒绝离开。他说他宁死也不会放弃他的土地。他确实这么做了。$B$B有人说他在最后的日子里疯了……还有人悄悄说他隐藏着更黑暗的东西。我不太相信这些传闻——但有一件事是肯定的：他粮仓里的粮食没人认领。如果还有好粮食，我们会在它们腐烂甚至更糟之前利用起来。$B$B去那里看看你能找到什么。十箱应该足够我们的粮食储备了。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41882, '浴血奋战、刀光剑影之后，只剩下一件事要做——将我们来之不易的胜利报告给丹基塔斯的治安官。$B$B我想不出比你更合适的人选来承担这份荣耀，朋友。正是凭借你的双手和你族人的力量，我们才击溃了龙喉氏族，守护了冷酷海岸——至少目前如此。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41883, '在祖鲁希德的尸体上发现了一封磨损的信。这封信似乎是写给他的，字迹粗糙：$B$B<这么说你终于回来了？自从我们其他人为了生存而拼死搏斗，你消失去追寻你的神器以来，已经过去了多久？你为了自己愚蠢的荣耀抛弃了龙喉氏族，现在，因为你回来了，你就指望所有的酋长们会毫无悔意和敌意地团结起来？$B$B别指望我会像其他祖鲁希德的人一样愚蠢。你想躲在格瑞姆巴托的地下世界里就躲吧。我会带领我们氏族在冷酷海岸的土地上取得辉煌而伟大的胜利，而不是像雷德之流那样躲在洞穴里。我们当中有些人知道黑石的真相，也不想用光荣的“黑暗部落”来掩盖真相……老朋友，你的命令被否决了。$B$B科尔拉格·末日之歌，龙喉氏族。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41884, '这封信证实了一些流传已久的谣言，龙喉氏族并非完全团结。$B$B祖鲁希德已被击杀，现在只剩下一个人有资格角逐族长，那就是指挥官科尔拉格·末日之歌。我们矮人与龙喉氏族的争斗已经久到我们无法记起的地步，现在是时候发出最后一击了。召集所有能召集的盟友，向北深入扎姆盖斯要塞。在那里，你们会找到科尔拉格·末日之歌，以及龙喉氏族的最后一位首领。杀了他，把我们从这场永无休止的战争中解放出来！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41885, '<矮人凝视着湖面，喃喃自语。他身上散发着浓重的鱼腥味和烟斗味。>$B$B它们就在那里……等着。牙齿像匕首，眼睛像被诅咒的珍珠！你以为在基塔斯湖钓鱼安全吗？你错了！大错特错！$B$B那些该死的剃齿鳄鱼不停地咬我的鱼线——上周差点咬断我的手！它们不仅仅是钓鱼的障碍，它们是怪物，我告诉你！$B$B你有武器，对吧？去那该死的湖里干掉它们几个。八只足以让剩下的鳄鱼三思而后行，不敢再惹努德鲁。$B$B我保证，你不至于白费力气！要是我不乖——嗯，在我感到愧疚之前，鳄鱼会先抓走我！') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41886, '听着，我可不是胆小鬼……但冷酷谷这地方有点不对劲。空气很浓重，即使没有风，树木也会嘎吱作响，而且我敢发誓，只要你不注意，影子就会动。$B$B还有蜘蛛——就在石头边上，就是那些蜘蛛。注意，可不是你平常看到的洞穴爬行动物。它们体型巨大，眼神中充满了饥饿。它们被称为巨型棕色蜘蛛，它们成群结队地出现在沼泽小径上，仿佛它们是这里的主人。$B$B如果我们不减少它们的数量，我们就会睡梦中被蛛网缠住。你看起来意志坚定——出去至少解决掉十二只这种畜生。我会在这里......监视周边情况。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41887, '如果您想了解我们最重要、最稀有的药剂，那么您来对地方了。为了感谢您在海加尔山的贡献，我可以传授您我先辈的知识。梦精猫鼬药剂是一种相当强效的炼金药剂。它可以用来扭转战局，使之对您有利。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41888, '我们的斥候报告称：敌方要塞——卡拉赞下层大厅、祖尔格拉布和安其拉的异动有所增加。$B$B我们需要历战的精锐勇士来清除这些地方的腐化，并带回他们行动的证明。给我带回一些英雄纹章——你只有通过战胜那些强大的敌人才能获得它们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41889, '我们脚下的大地正因愤怒而颤抖。在熔火之心深处，远古的敌人再次蠢蠢欲动。新的火焰副官以拉格纳罗斯之名崛起，威胁着要开启又一个火焰时代。$B$B我们不能让他们就这么扩展自身势力。找到并干掉他们！带回他们陨灭的证据：一块来自因辛迪斯的熔火鳞片，以及从巫王手上夺下的印记。让所有侍奉炎魔之王的人都知道：联盟不会燃烧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41890, '放任威胁不管只会让它日益严重。我们的斥候报告称，在敌方最坚固的地下城中，敌方指挥官的攻击性和协同性有所增强。$B$B我们应该趁他们还过于自信的时候出击！将从他们阵亡领袖身上夺取的勇气纹章带给我。让他们知道，部落不会心慈手软——我们会粉碎所有与我们作对的人。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41891, '我们的斥候报告称：敌方要塞——卡拉赞下层大厅、祖尔格拉布和安其拉的异动有所增加。$B$B这些地方黑暗魔法密布，远古威胁横行。我们需要历战的精锐勇士深入敌方，清除这些地方的腐化，并凯旋而归。给我带回一些英雄纹章——你只有通过战胜那些强大的敌人才能获得它们。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41892, '我们脚下的大地正因愤怒而颤抖。在熔火之心深处，远古的敌人再次蠢蠢欲动。新的火焰副官以拉格纳罗斯之名崛起，威胁着要开启又一个火焰时代。$B$B我们不能让他们就这么扩展自身势力。找到并干掉他们！带回他们陨灭的证据：一块来自因辛迪斯的熔火鳞片，以及从巫王手上夺下的印记。让所有侍奉炎魔之王的人都知道：部落不会燃烧。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41893, '<你面前这本干巴巴的旧书似乎记载了下层储备矿井的建造过程，以及监督其建造的众多著名蛮锤矮人。书中多次提到了冷酷海岸的丹基塔斯，是了解矿井采矿成就的关键资料。肯定有人会觉得这本书很有价值。>') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41894, '你是想帮助一个被流放、受压迫的地精找回他失去的财富，让他重返杜隆塔尔工会联盟吗？$B$B好吧，看来你来对地方了。我被派到这片偏僻之地，作为对黑石岛搞砸了某些事的惩罚……$B$B这些是我最不想插手的事——听着，我需要你帮我策划一次抢劫。往西南走，过河就是蛮锤矮人的主要城镇丹基塔斯。俯瞰着东边的悬崖峭壁，有一间专门修理破损蒸汽坦克的小车间。我需要你进去，找到一台“多彩传动电机”并把它带给我。我的线人说，应该就有一台在那附近。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41895, '有人看到当地的森林蜘蛛在艾尔文附近爬行，似乎已经很久了。它们的毒液总是能卖个好价钱，我知道有人在求购这东西。你可以在闪金镇周围找到它们，潜伏在南边和西边。$B$B给我带三瓶森林毒液来，我会给你丰厚的报酬！……丰厚的报酬。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41896, '我听说，一股黑暗魔法的腐化正在吞噬东部王国边缘的冷酷海岸。一个名为“沼腮”的鱼人部落已被强烈的黑暗魔法所腐蚀，这股黑暗魔法正在侵蚀着这片土地……$B$B 我想要掌控这股魔法，并将其作为一道屏障，保护自己免受暗影的侵袭。前往那里，收集被腐化的沼泽中的鱼人的鱼鳍，收集到后带给我。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (41897, '放任威胁不管只会让它日益严重。我们的斥候报告称，敌军指挥官的活动有所增强。$B$B我们必须先发制人！打倒他们的首领，夺取他们的纹章，然后将它们带回给我。让他们知道我们不会退缩。让他们见识到联盟的力量。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Details_loc4`) VALUES (80745, '中秋佳节来临，象征着团圆与美好的时光。作为庆祝活动的一部分，你被邀请参与放置花灯的仪式。这不仅仅是一个简单的任务，而是传递祝福和心意的美好时刻。在这个特别的夜晚，找到指定的河边，轻轻放下你的花灯，让它随着柔和的河流漂浮，象征着你对亲朋好友的美好愿望和祝福。每一盏花灯都承载着希望与祝福，随着水流而去，照亮黑夜，温暖每一个心灵。') ON DUPLICATE KEY UPDATE `Details_loc4` = VALUES(`Details_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39977, '获得三种奢华的烟花，以及一些诺达纳尔草药茶给和谐之灵。他在藏宝海湾等待着。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39978, '在大海龟之灵前发射三种奢华烟花三遍。您可以在地下城中最强的生物上找到它们。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (39979, '在大海龟之灵前发射三种奢华烟花三遍。您可以在地下城中最强的生物上找到它们。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41274, '从艾泽拉斯各地取回爱情的纪念品并将它们交给基维·Q·真银箭头') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41275, '与铁炉堡秘法区的塔瓦斯德·基瑟尔进行对话。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41276, '与荒芜之地卡加斯的加卡尔交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41277, '前往荒芜之地的的科萨恩废墟，寻找齐格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41278, '前往荒芜之地的的科萨恩废墟，寻找齐格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41279, '在科萨恩废墟东边寻找赤褐色巨人博尔哈斯特，并将你的发现带回给齐格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41280, '完成齐格伦的工匠考验并向他展示你的作品。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41281, '从玛拉顿的兰斯利德身上取得大理石块，并交给荒芜之地科萨恩废墟附近的齐格伦。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41282, '完成最后的考验。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41283, '将所需的材料带给塔瓦斯德。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41284, '将所需的材料带给塔瓦斯德。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41285, '把冒险者的项链交给铁炉堡的塔瓦斯德·基瑟尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41286, '去凄凉之地寻找的神秘的导师。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41287, '将这些材料交给荒芜之地卡加斯的加卡尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41288, '将这些材料交给荒芜之地卡加斯的加卡尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41289, '在吉尔尼斯城找到这本书籍，并将其带给荒芜之地卡加斯的加卡尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41290, '去凄凉之地寻找的神秘的导师。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41291, '将珠宝工具包交给凄凉之地艾瑟雷索的巧匠。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41292, '制作以下珠宝。证明你的才能后，巧匠会把他的技艺传授予你。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41293, '向巧匠展示你自己或者其他人加工制作的珠宝。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41294, '向巧匠展示你的技艺。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41295, '让巧匠相信你理解了他的课程。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41296, '找到诅咒之地的库米沙。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41297, '从诅咒之地的德莱尼人手中夺回被翻乱的箱子，并将其归还给诅咒之地的库米沙。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41298, '将马托加尔的头颅带给诅咒之地的收藏家库米沙。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41299, '将库米沙的卷轴交给悲伤沼泽的珊弗科拉。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41300, '与威胁铁炉堡塔瓦斯德·基瑟尔的可疑人员交谈。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41301, '把这些报酬交给铁炉堡秘法区的塔瓦斯德·基瑟尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41302, '把这些报酬交给铁炉堡秘法区的塔瓦斯德·基瑟尔。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41303, '前往贫瘠之地的棘齿城并四处打听格雷兹比及其货物的下落。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41304, '寻找格雷兹比，然后返回怒水港的塔克纳兹·铜火那里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41305, '塔克纳兹需要一颗血色修道院的巨大红宝石和一条金项链。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41306, '在剃刀高地寻找特拉克西斯失踪的保镖。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41307, '收集特拉克西斯丢失的货物并将其运送至塔纳利斯热砂港的承包商。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41308, '将八个钢腭腺体、一个强效秘法精华和一个水晶瓶交给热砂港南部凡齐的神秘生意伙伴。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41309, '将萨拉辛的宝石油带给热砂港的凡齐·火花弹簧。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41310, '阅读卡德加的日记，揭开其背后的谜团。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41311, '杀死多万告诉你的末日守卫，并带回桑拉嵌座。他在塞拉摩南部的家中等着你。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41312, '如果你想修复这件遗物，就把必要的部件和来自高阶蓝龙的奥术法器交给多万。这位法师位于塞拉摩南部的海岸线上。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41313, '为艾萨拉高塔里的大法师克希雷姆收集地脉水晶。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
