INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41634, '"女巫玛琪露需要她的年鉴和八块来自入侵元素的残渣，来自她在北风领西部的塔楼中。 ﻿"') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41635, '清除北风领伐木营地的入侵迪菲亚。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41636, '从北部山区的盗贼那里取回箱子，并将其带到安伯郡教堂的阿金特修女那里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41637, '与安伯郡教堂的孩子们交谈，帮他们复习对巴洛岛的了解。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41638, '找到格雷厄姆修士母亲的骨灰盒，并带到北风领的安伯郡教堂归还给他。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41639, '将北风的魔女要的食材带到她在北风领的房子里。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41640, '将杜尔米的物品归还给他,他在丹莫罗的南门哨岗。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41641, '清除石爪山脉大地之环的入侵元素。之后返回先知格雷卡那。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41642, '在北风领伐木营地附近搜索克里斯托弗。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41643, '审问安伯郡的居民。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41644, '找到位于北风领的迪菲亚总部并寻找有关绑架案的线索。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41645, '搜索舍伍德采石场。带上你找到的任何有用的东西回报给安伯郡的霍桑特工。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41646, '揭开黑石兽人扩展到北方瞭望塔的意图。向安伯郡的霍桑特工报告。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41647, '与森林中的神秘女人会面。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41648, '为在北风领西北部的女巫集会所的北风的魔女搞到她所需的材料。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41649, '请听查波·查皮布拉斯的录音。录音盒就在永望镇他的身边。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41650, '找到永望广播公司劫持者。查波建议搜索艾萨拉东北部。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41651, '把你找到的日志和设备带给查波·查皮布拉斯。他在冬泉谷永望镇等你。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41652, '前往冬泉谷永望镇的永望广播公司。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41653, '在尘泥沼泽寻找智慧之灵。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41654, '将十份野猪尸体带给月光林地的虎凡·地弓。艾泽拉斯的任何野猪都适用于此任务') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41655, '从艾泽拉斯地下城中最强大的敌人那里取回春节代币，并交给丽珊卓·翔天。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41656, '从冷酷海岸的龙喉兽人那里收集30枚龙喉徽章，交给冷酷海岸的碎刃岗哨的指挥官阿格纳什。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41657, '把这封信带给冷酷海岸的某位掌权者。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41658, '杀死扎姆盖斯要塞内的科尔拉格·末日之歌，并将他的头颅带给恐怖之地碎刃岗哨的指挥官阿格纳什。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41659, '为在冷酷海岸 的碎刃岗哨的卫兵莫尔坎消灭 6 个碎骨穴居怪、6 个 碎骨先知、6 个 碎骨断骨者和 6 个 碎骨击颅者。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41660, '在格罗丹挖掘场周围杀死黑铁矮人，并为在冷酷海岸的碎刃岗哨的卫兵莫尔坎收集 15 个暗炉徽记。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41661, '杀死9个黄爪豺狼人，并将暴风城补给品送回狮子岗哨。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41662, '在树叶堆中找到里昂丢失的戒指。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41663, '向演武场的舍伍德公爵报告。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41664, '搜索黑暗骑士的帐篷，然后将你的发现带回给舍伍德公爵。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41665, '将舍伍德公爵的邀请函交给安伯伍德领主。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41666, '收集琥珀甜甜圈所需的原料并返回米切尔身边。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41667, '在阿尔萨拉斯寻找查杜斯·桑克利尔，寻找一对附魔马蹄铁，然后返回指挥官莱德身边。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41668, '收集一包琥珀甜甜圈、一捆苹果和英维尔德的馅饼，然后回到在雕像旁的她身边。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41669, '将打包好的货物带给暴风城要塞的安度因·乌瑞恩。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41670, '从刺须洞穴中取回20支蜡烛，并将它们归还给看守者克莱夫。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41671, '杀死旧修道院的哀泣的修女并取回北风讣告，将其归还给看守者克莱夫。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41672, '杀死6个黄鳍鱼人、4个黄鳍巡湖者和2个黄鳍唤嘲鱼人。之后返回北风领“丰满的南瓜”找贾罗德·索普。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41673, '进入岸边的洞穴，杀死扎什女士，将她的珍珠送回给码头边的亨利。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41674, '在北风领酒厂外面的田里杀死20名黑石部族入侵者。完成后向老克劳福德回报。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41675, '从克劳福德酒厂的上层取回北风琥珀的配方。将其送回给丰满的南瓜旅馆的老克劳福德。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41676, '为德里斯科尔上校杀死索克大王、奥扎克·末日之刺和舒尼·钢牙，然后向他回报。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41677, '破坏15个黑铁火药桶，并回报给北风领“丰满的南瓜”里的德里斯科尔上校。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41678, '从旧修道院为检察官阿巴顿取回光之圣杯。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41679, '收集10块烧焦的骨头，并将它们带回给特里斯顿·兰开斯特。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41680, '找到威格斯！') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
INSERT INTO `locales_quest` (`entry`, `Objectives_loc4`) VALUES (41681, '杀死黑石焚化大师，然后向威格斯回报。') ON DUPLICATE KEY UPDATE `Objectives_loc4` = VALUES(`Objectives_loc4`);
